window.ETSDATA=window.ETSDATA||{};window.ETSDATA[19]={"lc":{"p1":[{"n":1,"opts":["He's standing on a rug.","He's turning a doorknob.","He's climbing a ladder.","He's painting a wall."],"vi":["Anh ấy đang đứng trên tấm thảm.","Anh ấy đang vặn tay nắm cửa.","Anh ấy đang leo thang.","Anh ấy đang sơn tường."],"ans":"C","xp":"Tranh 1 người: người đàn ông đang trèo lên thang → (C) đúng. (A) không thấy anh ấy đứng trên thảm; (B) anh ấy không vặn tay nắm cửa; (D) anh ấy không đang sơn tường.","a":"E24-T09-01.mp3","img":"q1.jpg"},{"n":2,"opts":["Some shirts have been hung on a clothing rack.","A light fixture is attached to a column.","Some boxes of clothing have been set on the floor.","Some merchandise is on display in a store."],"vi":["Vài chiếc áo sơ mi đã được treo trên giá quần áo.","Một bộ đèn được gắn vào cột.","Vài thùng quần áo đã được đặt trên sàn.","Hàng hóa đang được trưng bày trong cửa hàng."],"ans":"D","xp":"Tranh đồ vật: hàng hóa được bày trên bàn, kệ trong cửa hàng → (D) đúng ('on display' = được trưng bày). (A) không thấy áo treo trên giá; (B) không có đèn gắn trên cột; (C) không thấy thùng quần áo đặt trên sàn.","a":"E24-T09-02.mp3","img":"q2.jpg"},{"n":3,"opts":["The woman is putting some papers into a file folder.","The woman is typing on a keyboard.","The woman is seated in front of a computer.","The woman is holding a cup."],"vi":["Người phụ nữ đang cho giấy tờ vào bìa hồ sơ.","Người phụ nữ đang gõ bàn phím.","Người phụ nữ đang ngồi trước máy tính.","Người phụ nữ đang cầm một cái cốc."],"ans":"C","xp":"Người phụ nữ đang ngồi trước màn hình máy tính → (C) đúng ('be seated' = đang ngồi). (A) không thấy bìa hồ sơ; (B) cô ấy không gõ phím; (D) cô ấy không cầm cốc.","a":"E24-T09-03.mp3","img":"q3.jpg"},{"n":4,"opts":["Some employees are washing some windows.","A shopper is carrying a package.","Some shopping carts have been lined up in a row.","Some products have fallen on the ground."],"vi":["Vài nhân viên đang lau cửa sổ.","Một người mua sắm đang mang một thùng hàng.","Vài xe đẩy mua hàng đã được xếp thành một hàng.","Vài sản phẩm đã rơi xuống đất."],"ans":"B","xp":"Một người mua sắm đang ôm/mang một thùng hàng (package) → (B) đúng. (A) không có nhân viên lau cửa sổ; (C) xe đẩy không được xếp thành hàng; (D) không có sản phẩm nào rơi xuống đất.","a":"E24-T09-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Snow is being cleared away.","Bricks are being arranged on a walkway.","Tree branches are being trimmed.","A shovel is leaning against a flowerpot."],"vi":["Tuyết đang được dọn đi.","Gạch đang được xếp trên lối đi.","Cành cây đang được cắt tỉa.","Một cái xẻng đang dựa vào chậu hoa."],"ans":"A","xp":"Người đàn ông đang dọn tuyết (bằng xẻng) → (A) đúng ('be cleared away' = được dọn đi). (B) không có ai xếp gạch; (C) không có ai cắt tỉa cành cây; (D) cái xẻng đang được dùng, không dựa vào chậu hoa.","a":"E24-T09-05.mp3","img":"q5.jpg"},{"n":6,"opts":["A potted plant is hanging above a window.","There is a lamppost in front of a building.","Some chairs have been arranged in a line.","Some bricks have been piled on a patio."],"vi":["Một chậu cây đang treo phía trên cửa sổ.","Có một cột đèn đường trước tòa nhà.","Vài chiếc ghế đã được xếp thành một hàng.","Vài viên gạch đã được chất đống trên sân hiên."],"ans":"C","xp":"Tranh cảnh vật: các ghế bập bênh được xếp thành một hàng dọc hiên nhà → (C) đúng. (A) không có chậu cây treo; (B) không thấy cột đèn đường; (D) không có đống gạch nào.","a":"E24-T09-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Who's covering for Ms. Hamada?","qvi":"Ai đang làm thay cho cô Hamada?","opts":["Yes, it may rain later.","No, I have enough.","Her assistant."],"vi":["Vâng, lát nữa có thể trời mưa.","Không, tôi có đủ rồi.","Trợ lý của cô ấy."],"ans":"C","xp":"Câu hỏi Who (ai) làm thay cô Hamada → (C) trả lời đúng một người: trợ lý của cô ấy. (A), (B) bắt đầu bằng Yes/No – không dùng để trả lời câu hỏi Who.","a":"E24-T09-07.mp3"},{"n":8,"q":"Where is the fashion seminar?","qvi":"Hội thảo thời trang diễn ra ở đâu?","opts":["It's in room 235.","No, the black one.","Just some blouses."],"vi":["Ở phòng 235.","Không, cái màu đen.","Chỉ vài cái áo cánh thôi."],"ans":"A","xp":"Câu hỏi Where (ở đâu) → (A) nêu địa điểm cụ thể 'room 235'. (B) Yes/No không trả lời câu Where; (C) 'blouses' (áo cánh) chỉ liên tưởng đến 'fashion', bẫy từ liên quan.","a":"E24-T09-08.mp3"},{"n":9,"q":"Why do we have to put on safety goggles?","qvi":"Tại sao chúng ta phải đeo kính bảo hộ?","opts":["No, the door on your left.","Because of safety regulations.","A hat and a scarf."],"vi":["Không, cửa bên trái của bạn.","Vì quy định an toàn.","Một cái mũ và một chiếc khăn quàng."],"ans":"B","xp":"Câu hỏi Why (tại sao) → (B) 'Because of safety regulations' nêu lý do. (A) Yes/No không trả lời câu Why; (C) mũ và khăn liên tưởng đến 'put on' (mặc, đeo), bẫy liên tưởng.","a":"E24-T09-09.mp3"},{"n":10,"q":"What did you do for Mr. Sugiyama's retirement party?","qvi":"Bạn đã làm gì cho tiệc nghỉ hưu của ông Sugiyama?","opts":["I helped decorate the room.","He's not tired.","Try the file cabinet."],"vi":["Tôi đã giúp trang trí căn phòng.","Ông ấy không mệt.","Thử tìm ở tủ hồ sơ xem."],"ans":"A","xp":"Hỏi What – bạn đã làm gì cho bữa tiệc → (A) 'Tôi đã giúp trang trí phòng' trả lời đúng việc đã làm. (B) 'tired' phát âm na ná 'retirement' – bẫy âm; (C) không liên quan.","a":"E24-T09-10.mp3"},{"n":11,"q":"Can I take another bottle of water?","qvi":"Tôi lấy thêm một chai nước nữa được không?","opts":["If there are any left.","An old refrigerator.","No, the clock is fast."],"vi":["Nếu vẫn còn chai nào.","Một cái tủ lạnh cũ.","Không, đồng hồ chạy nhanh."],"ans":"A","xp":"Câu xin phép/yêu cầu → (A) 'được, nếu vẫn còn (nước)' là câu đồng ý có điều kiện. (B) 'refrigerator' (tủ lạnh) chỉ liên tưởng đến 'water'; (C) không liên quan.","a":"E24-T09-11.mp3"},{"n":12,"q":"Isn't this the last train out?","qvi":"Đây chẳng phải là chuyến tàu cuối cùng sao?","opts":["A round-trip ticket to New York.","The office next door.","No, there's one more."],"vi":["Một vé khứ hồi đi New York.","Văn phòng bên cạnh.","Không, còn một chuyến nữa."],"ans":"C","xp":"Câu hỏi phủ định để xác nhận đây có phải chuyến tàu cuối → (C) 'Không, vẫn còn một chuyến nữa' trả lời hợp lý. (A) 'vé khứ hồi' liên tưởng đến 'train'; (B) không liên quan.","a":"E24-T09-12.mp3"},{"n":13,"q":"What was the highlight of your visit to the city this weekend?","qvi":"Điều thú vị nhất trong chuyến thăm thành phố cuối tuần này của bạn là gì?","opts":["Definitely the art museum!","Sorry, I already have plans.","Yes, the guidebook was helpful."],"vi":["Chắc chắn là bảo tàng nghệ thuật rồi!","Xin lỗi, tôi có kế hoạch rồi.","Vâng, cuốn sách hướng dẫn rất hữu ích."],"ans":"A","xp":"Hỏi What – điểm nổi bật (highlight) của chuyến đi → (A) nêu cụ thể 'bảo tàng nghệ thuật'. (B) 'plans' liên tưởng đến 'this weekend'; (C) Yes không trả lời câu hỏi What.","a":"E24-T09-13.mp3"},{"n":14,"q":"When was that news story about the merger published?","qvi":"Bản tin về vụ sáp nhập đó được đăng khi nào?","opts":["A few weeks ago.","A reporter from the Springfield News.","No, I think that's the right address."],"vi":["Vài tuần trước.","Một phóng viên của tờ Springfield News.","Không, tôi nghĩ đó là địa chỉ đúng."],"ans":"A","xp":"Câu hỏi When (khi nào) → (A) nêu thời điểm 'vài tuần trước'. (B) lặp từ 'News' và trả lời câu hỏi Who; (C) No không trả lời câu When.","a":"E24-T09-14.mp3"},{"n":15,"q":"We need to install a security system at the office.","qvi":"Chúng ta cần lắp đặt hệ thống an ninh ở văn phòng.","opts":["It's a new ID badge.","Yes, I think that's a good idea.","I bought some lightbulbs."],"vi":["Đó là thẻ nhân viên mới.","Vâng, tôi nghĩ đó là ý hay.","Tôi đã mua vài bóng đèn."],"ans":"B","xp":"Câu trần thuật nêu ý kiến → (B) đồng tình 'Vâng, ý hay đấy'. (A) 'ID badge' liên tưởng đến 'security'; (C) 'lightbulbs' liên tưởng đến 'install' – bẫy liên tưởng.","a":"E24-T09-15.mp3"},{"n":16,"q":"Where are the job fairs being held?","qvi":"Các hội chợ việc làm được tổ chức ở đâu?","opts":["I'll take seven of them.","There's a list in the folder.","OK, I can drive."],"vi":["Tôi sẽ lấy bảy cái.","Có danh sách trong bìa hồ sơ đấy.","Được, tôi có thể lái xe."],"ans":"B","xp":"Hỏi Where nhưng đáp án trả lời gián tiếp: 'Có danh sách (địa điểm) trong bìa hồ sơ' → bạn tự xem → (B). (A) trả lời số lượng; (C) OK không phù hợp với câu Where.","a":"E24-T09-16.mp3"},{"n":17,"q":"When can we use the new color printer?","qvi":"Khi nào chúng ta có thể dùng máy in màu mới?","opts":["This afternoon.","OK, that's good to hear.","Sure, I can take a photograph."],"vi":["Chiều nay.","Được, nghe vậy thật tốt.","Chắc chắn rồi, tôi có thể chụp ảnh."],"ans":"A","xp":"Câu hỏi When → (A) 'Chiều nay' nêu thời gian. (B) OK và (C) Sure giống câu trả lời Yes – không hợp với câu When; (C) 'photograph' liên tưởng đến 'color printer'.","a":"E24-T09-17.mp3"},{"n":18,"q":"Could you order some more paper plates?","qvi":"Bạn đặt mua thêm ít đĩa giấy được không?","opts":["Thanks for the invitation.","He got a job at the restaurant.","We have enough for three months."],"vi":["Cảm ơn lời mời của bạn.","Anh ấy đã có việc ở nhà hàng.","Chúng ta có đủ dùng trong ba tháng."],"ans":"C","xp":"Câu nhờ vả → (C) trả lời gián tiếp: 'chúng ta còn đủ dùng 3 tháng' = chưa cần đặt thêm. (A) không liên quan; (B) 'He' không rõ là ai, 'restaurant' liên tưởng đến 'plates'.","a":"E24-T09-18.mp3"},{"n":19,"q":"Should I pick up the food order for Ms. Santos?","qvi":"Tôi có nên đi lấy phần đồ ăn đã đặt cho cô Santos không?","opts":["Let's meet next week.","Yes, if you have the time.","I don't cook with vegetable oil."],"vi":["Tuần sau gặp nhau nhé.","Vâng, nếu bạn có thời gian.","Tôi không nấu ăn bằng dầu thực vật."],"ans":"B","xp":"Câu đề nghị giúp → (B) 'Vâng, nếu bạn có thời gian' là đồng ý. (A) không liên quan; (C) 'cook', 'vegetable oil' chỉ liên tưởng đến 'food'.","a":"E24-T09-19.mp3"},{"n":20,"q":"Why don't you distribute this flyer around the office?","qvi":"Sao bạn không phát tờ rơi này quanh văn phòng nhỉ?","opts":["Sure—that's a great idea.","Our flight's been canceled.","I'll take the elevator."],"vi":["Được chứ — ý hay đấy.","Chuyến bay của chúng tôi đã bị hủy.","Tôi sẽ đi thang máy."],"ans":"A","xp":"'Why don't you...?' là lời đề nghị, không phải hỏi lý do → (A) đồng ý 'Được, ý hay đấy'. (B) 'flight' dễ nhầm âm với 'flyer'; (C) 'elevator' liên tưởng đến 'office'.","a":"E24-T09-20.mp3"},{"n":21,"q":"How often do you go to concerts?","qvi":"Bạn có thường đi xem hòa nhạc không?","opts":["I ride my bicycle to work every day.","No, he's not a professional musician.","I don't have a lot of free time."],"vi":["Tôi đạp xe đi làm mỗi ngày.","Không, anh ấy không phải nhạc sĩ chuyên nghiệp.","Tôi không có nhiều thời gian rảnh."],"ans":"C","xp":"Hỏi How often (bao lâu một lần) → (C) trả lời gián tiếp 'tôi không có nhiều thời gian rảnh' = ít khi đi. (A) 'every day' là bẫy về tần suất nhưng nói việc đạp xe; (B) No không trả lời câu How often.","a":"E24-T09-21.mp3"},{"n":22,"q":"Do you want me to fix the printer in your office?","qvi":"Bạn có muốn tôi sửa máy in trong văn phòng bạn không?","opts":["An official document.","Yes, that would be helpful.","I printed it on both sides."],"vi":["Một văn bản chính thức.","Vâng, như vậy sẽ giúp ích lắm.","Tôi đã in hai mặt."],"ans":"B","xp":"Lời đề nghị giúp đỡ → (B) 'Vâng, vậy thì giúp ích lắm' là chấp nhận. (A) 'official' na ná 'office'; (C) 'printed' lặp gốc từ 'printer' – bẫy.","a":"E24-T09-22.mp3"},{"n":23,"q":"Will the company's warehouse be built in the city or farther out?","qvi":"Nhà kho của công ty sẽ được xây trong thành phố hay xa hơn ra ngoài?","opts":["It'll be in the city.","Yes, he's wearing a red sweater.","Two square kilometers."],"vi":["Nó sẽ ở trong thành phố.","Vâng, anh ấy đang mặc áo len đỏ.","Hai kilômét vuông."],"ans":"A","xp":"Câu hỏi lựa chọn (A or B) → (A) chọn một phương án 'trong thành phố'. (B) Yes không dùng cho câu hỏi lựa chọn; (C) 'kilometers' liên tưởng đến 'farther', trả lời diện tích.","a":"E24-T09-23.mp3"},{"n":24,"q":"The taxi has finally arrived.","qvi":"Cuối cùng thì taxi cũng đến rồi.","opts":["Oh, did it get stuck in traffic?","Thanks, but I already have some.","It's their final offer."],"vi":["Ồ, nó bị kẹt xe à?","Cảm ơn, nhưng tôi có rồi.","Đó là lời đề nghị cuối cùng của họ."],"ans":"A","xp":"Câu trần thuật 'cuối cùng taxi cũng đến' (ý là đến muộn) → (A) hỏi lại lý do muộn 'bị kẹt xe à?' là phản hồi tự nhiên. (B) không liên quan; (C) 'final' lặp gốc từ 'finally' – bẫy.","a":"E24-T09-24.mp3"},{"n":25,"q":"How can we train all the new team members?","qvi":"Làm sao chúng ta có thể đào tạo tất cả thành viên mới của nhóm?","opts":["Yes, I worked on those.","It wasn't as long as we thought.","People like watching videos."],"vi":["Vâng, tôi đã làm những cái đó.","Nó không dài như chúng ta nghĩ.","Mọi người thích xem video."],"ans":"C","xp":"Hỏi How (cách thức) → (C) gợi ý gián tiếp: mọi người thích xem video → đào tạo bằng video. (A) Yes không trả lời câu How; (B) không liên quan.","a":"E24-T09-25.mp3"},{"n":26,"q":"The party is supposed to start at six P.M., right?","qvi":"Bữa tiệc dự kiến bắt đầu lúc 6 giờ tối, phải không?","opts":["I added her name to the guest list.","No, the invitation said seven.","Because the party decorations were expensive."],"vi":["Tôi đã thêm tên cô ấy vào danh sách khách mời.","Không, thiệp mời ghi là bảy giờ.","Vì đồ trang trí tiệc đắt."],"ans":"B","xp":"Câu hỏi đuôi xác nhận giờ bắt đầu → (B) 'Không, thiệp mời ghi 7 giờ' sửa lại thông tin. (A) 'guest list' liên tưởng đến 'party'; (C) lặp từ 'party' và trả lời câu Why.","a":"E24-T09-26.mp3"},{"n":27,"q":"Does the manager want us to pick up the supplies or have them delivered?","qvi":"Quản lý muốn chúng ta đi lấy đồ dùng hay cho người giao đến?","opts":["She'll be here soon.","You dropped your pen.","You're right about that."],"vi":["Cô ấy sẽ đến đây sớm thôi.","Bạn làm rơi bút kìa.","Bạn nói đúng về điều đó."],"ans":"A","xp":"Câu hỏi lựa chọn nhưng đáp án là kiểu 'không chọn': 'Cô ấy (quản lý) sắp đến rồi' → lát nữa hỏi trực tiếp → (A). (B) 'pen' liên tưởng đến 'supplies'; (C) không liên quan.","a":"E24-T09-27.mp3"},{"n":28,"q":"Has Jacob come into the office today?","qvi":"Hôm nay Jacob có đến văn phòng không?","opts":["His briefcase is on his desk.","Yes, it is a nice office.","I can come in for just a minute."],"vi":["Cặp tài liệu của anh ấy ở trên bàn.","Vâng, văn phòng đẹp đấy.","Tôi có thể ghé vào một phút thôi."],"ans":"A","xp":"Hỏi Jacob đã đến chưa → (A) trả lời gián tiếp: cặp của anh ấy đang ở trên bàn = anh ấy đã đến. (B) lặp từ 'office'; (C) lặp từ 'come' – bẫy lặp từ.","a":"E24-T09-28.mp3"},{"n":29,"q":"Are you joining the team for today's briefing?","qvi":"Bạn có tham gia buổi họp giao ban với nhóm hôm nay không?","opts":["My top client is in town.","Vittorio's Pizzeria.","I enjoyed that film."],"vi":["Khách hàng quan trọng nhất của tôi đang ở trong thành phố.","Tiệm pizza Vittorio's.","Tôi rất thích bộ phim đó."],"ans":"A","xp":"Câu hỏi Yes/No nhưng đáp án trả lời gián tiếp: khách hàng lớn nhất đang ở đây (tôi phải gặp họ) → không tham gia được → (A). (B), (C) không liên quan.","a":"E24-T09-29.mp3"},{"n":30,"q":"I'm organizing a healthy eating program at the office.","qvi":"Tôi đang tổ chức một chương trình ăn uống lành mạnh ở văn phòng.","opts":["She studied at that theater program.","Right beside the new projector.","Do you need any help with it?"],"vi":["Cô ấy đã học ở chương trình sân khấu đó.","Ngay bên cạnh máy chiếu mới.","Bạn có cần giúp gì không?"],"ans":"C","xp":"Câu trần thuật cho biết thông tin → (C) hỏi lại 'Bạn có cần giúp không?' là phản hồi tự nhiên. (A) 'She' không rõ là ai, lặp từ 'program'; (B) trả lời câu hỏi Where.","a":"E24-T09-30.mp3"},{"n":31,"q":"Is your car expensive to repair?","qvi":"Xe của bạn sửa có tốn kém không?","opts":["The largest model available.","Only a few more times.","It's been running perfectly since I bought it."],"vi":["Mẫu lớn nhất hiện có.","Chỉ vài lần nữa thôi.","Nó chạy hoàn hảo từ khi tôi mua."],"ans":"C","xp":"Hỏi sửa xe có đắt không → (C) trả lời gián tiếp: xe chạy hoàn hảo từ lúc mua (chưa phải sửa nên không biết). (A) 'model' liên tưởng đến 'car'; (B) không liên quan.","a":"E24-T09-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Mr. Hughes? My name is Ms. Ayhan. I'll be interviewing you today for the open position of patient transporter. I see on your application that you've worked in health care before.","Anh Hughes phải không? Tôi là Ayhan. Hôm nay tôi sẽ phỏng vấn anh cho vị trí nhân viên vận chuyển bệnh nhân đang tuyển. Tôi thấy trong đơn ứng tuyển anh đã từng làm trong ngành y tế."],["M","That's right. I worked at the main reception desk at the Southeast Regional Hospital for a while. But I'd like to try a different role.","Đúng vậy. Tôi đã làm ở quầy lễ tân chính của Bệnh viện Khu vực Đông Nam một thời gian. Nhưng tôi muốn thử một vai trò khác."],["W","You'd be responsible for moving patients to various locations throughout the hospital. It'll involve about six miles of walking every shift. Are you OK with that?","Anh sẽ chịu trách nhiệm đưa bệnh nhân đến nhiều nơi khác nhau trong bệnh viện. Công việc này sẽ phải đi bộ khoảng sáu dặm mỗi ca. Anh thấy ổn chứ?"],["M","I actually do a lot of hiking and rock climbing in my free time. So I'm looking forward to having a job that'll have me on my feet more.","Thật ra lúc rảnh tôi đi bộ đường dài và leo núi đá rất nhiều. Nên tôi rất mong có một công việc được đi lại nhiều hơn."]],"qs":[{"n":32,"q":"Where is the conversation taking place?","qvi":"Cuộc hội thoại diễn ra ở đâu?","opts":["At an athletic club","At a hospital","At a shipping company","At an accounting firm"],"vi":["Ở câu lạc bộ thể thao","Ở bệnh viện","Ở công ty vận chuyển hàng hóa","Ở công ty kế toán"],"ans":"B","xp":"Người phụ nữ nói: \"I'll be interviewing you today for the open position of patient transporter\" và \"moving patients to various locations throughout the hospital\" → phỏng vấn vị trí đưa bệnh nhân trong bệnh viện → (B)."},{"n":33,"q":"What was the man's previous job?","qvi":"Công việc trước đây của người đàn ông là gì?","opts":["Receptionist","Custodian","Tour guide","Bus driver"],"vi":["Nhân viên lễ tân","Nhân viên vệ sinh/bảo quản tòa nhà","Hướng dẫn viên du lịch","Tài xế xe buýt"],"ans":"A","xp":"Người đàn ông nói: \"I worked at the main reception desk at the Southeast Regional Hospital\" → làm ở quầy lễ tân = Receptionist → (A)."},{"n":34,"q":"What does the woman emphasize about the job being offered?","qvi":"Người phụ nữ nhấn mạnh điều gì về công việc đang tuyển?","opts":["It demands long hours.","It requires a lot of experience.","It offers a competitive salary.","It involves a lot of walking."],"vi":["Nó đòi hỏi làm việc nhiều giờ.","Nó yêu cầu nhiều kinh nghiệm.","Nó trả lương cạnh tranh.","Nó phải đi bộ nhiều."],"ans":"D","xp":"Người phụ nữ nói: \"It'll involve about six miles of walking every shift\" → sáu dặm đi bộ mỗi ca = 'a lot of walking' → (D)."}],"a":"E24-T09-32-34.mp3"},{"ns":[35,37],"script":[["W","Hello. I'm calling to discuss the men's suit and coat store that you want to open.","Xin chào. Tôi gọi để bàn về cửa hàng com-lê và áo khoác nam mà các anh muốn mở."],["M1","Thanks for returning our call. My cousin and I are both on the line.","Cảm ơn chị đã gọi lại. Tôi và anh họ tôi đều đang nghe máy."],["M2","Yes-thanks. At first, we were just going to open the business without any advertising.","Vâng, cảm ơn chị. Lúc đầu, chúng tôi định mở cửa hàng mà không quảng cáo gì cả."],["M1","Right. But then we consulted a friend in the retail industry. He said a strong advertising campaign makes a difference and referred us to you.","Đúng vậy. Nhưng sau đó chúng tôi hỏi ý kiến một người bạn làm trong ngành bán lẻ. Anh ấy bảo một chiến dịch quảng cáo mạnh sẽ tạo ra khác biệt và giới thiệu chúng tôi đến chị."],["W","He's right. You need to advertise your store before it opens.","Anh ấy nói đúng. Các anh cần quảng cáo cửa hàng trước khi khai trương."],["M2","Have you looked at the information we sent?","Chị đã xem thông tin chúng tôi gửi chưa?"],["W","Yes, and here's what I think: first, you should emphasize the fact that this will be a family-run business. Local customers will appreciate that.","Rồi, và đây là ý kiến của tôi: trước tiên, các anh nên nhấn mạnh rằng đây sẽ là một cửa hàng do gia đình điều hành. Khách hàng địa phương sẽ đánh giá cao điều đó."]],"qs":[{"n":35,"q":"What kind of business will the men open?","qvi":"Hai người đàn ông sẽ mở loại hình kinh doanh nào?","opts":["An electronics repair shop","A car dealership","A restaurant","A clothing store"],"vi":["Tiệm sửa đồ điện tử","Đại lý ô tô","Nhà hàng","Cửa hàng quần áo"],"ans":"D","xp":"Người phụ nữ nói: \"I'm calling to discuss the men's suit and coat store that you want to open\" → cửa hàng com-lê và áo khoác nam = cửa hàng quần áo (clothing store) → (D)."},{"n":36,"q":"How did the men learn about the woman's consulting service?","qvi":"Hai người đàn ông biết đến dịch vụ tư vấn của người phụ nữ bằng cách nào?","opts":["From a local business owner","From a marketing course","From a friend who works in retail","From a newspaper advertisement"],"vi":["Từ một chủ doanh nghiệp địa phương","Từ một khóa học marketing","Từ một người bạn làm trong ngành bán lẻ","Từ một quảng cáo trên báo"],"ans":"C","xp":"Người đàn ông nói: \"we consulted a friend in the retail industry... and referred us to you\" → người bạn trong ngành bán lẻ đã giới thiệu → (C)."},{"n":37,"q":"What does the woman say should be emphasized about a business?","qvi":"Người phụ nữ nói nên nhấn mạnh điều gì về cửa hàng?","opts":["That it will provide many jobs","That it will be run by family members","That its owners have a lot of experience","That its owners live in the neighborhood"],"vi":["Rằng nó sẽ tạo ra nhiều việc làm","Rằng nó sẽ do các thành viên gia đình điều hành","Rằng chủ cửa hàng có nhiều kinh nghiệm","Rằng chủ cửa hàng sống ở khu phố này"],"ans":"B","xp":"Người phụ nữ nói: \"you should emphasize the fact that this will be a family-run business\" → 'family-run' = do người trong gia đình điều hành (run by family members) → (B)."}],"a":"E24-T09-35-37.mp3"},{"ns":[38,40],"script":[["M","Look what just arrived—they're the new handheld scanners we've been waiting for!","Xem cái vừa được giao tới này — đó là những máy quét cầm tay mới mà chúng ta đang chờ!"],["W","That's exciting! It's going to be so much easier to scan the groceries with these. Do you know when they'll be installed at each of the checkout stations?","Thật thú vị! Quét hàng tạp hóa bằng mấy cái này sẽ dễ hơn nhiều. Anh có biết khi nào chúng được lắp ở từng quầy thanh toán không?"],["M","Our manager is hoping to set them up tomorrow night after the store closes. She asked if I could help, but I'm not available.","Quản lý của chúng ta muốn lắp đặt chúng vào tối mai sau khi cửa hàng đóng cửa. Chị ấy hỏi tôi có giúp được không, nhưng tôi lại bận."],["W","Oh, I can stay late tomorrow night. I'll go let her know.","Ồ, tối mai tôi có thể ở lại muộn. Tôi sẽ đi báo với chị ấy."]],"qs":[{"n":38,"q":"What are the speakers excited about?","qvi":"Hai người nói hào hứng về điều gì?","opts":["An upcoming holiday","A staff training session","Some new equipment","Some staff discounts"],"vi":["Một kỳ nghỉ sắp tới","Một buổi đào tạo nhân viên","Một số thiết bị mới","Một số ưu đãi giảm giá cho nhân viên"],"ans":"C","xp":"Người đàn ông: \"they're the new handheld scanners we've been waiting for!\" và người phụ nữ: \"That's exciting!\" → máy quét cầm tay mới = thiết bị mới (new equipment) → (C)."},{"n":39,"q":"Where most likely do the speakers work?","qvi":"Hai người nói nhiều khả năng làm việc ở đâu?","opts":["At a train station","At a grocery store","At an electronics store","At a medical center"],"vi":["Ở nhà ga xe lửa","Ở cửa hàng tạp hóa","Ở cửa hàng điện tử","Ở trung tâm y tế"],"ans":"B","xp":"Người phụ nữ nói: \"It's going to be so much easier to scan the groceries with these\" và nhắc đến 'checkout stations' (quầy thanh toán) → họ làm ở cửa hàng tạp hóa → (B)."},{"n":40,"q":"What will the woman tell her manager?","qvi":"Người phụ nữ sẽ nói gì với quản lý của mình?","opts":["She can work extra hours.","She needs more supplies.","She stocked some shelves.","She completed a project."],"vi":["Cô ấy có thể làm thêm giờ.","Cô ấy cần thêm đồ dùng.","Cô ấy đã xếp hàng lên kệ.","Cô ấy đã hoàn thành một dự án."],"ans":"A","xp":"Người phụ nữ: \"I can stay late tomorrow night. I'll go let her know.\" → ở lại muộn = làm thêm giờ (work extra hours) → (A)."}],"a":"E24-T09-38-40.mp3"},{"ns":[41,43],"script":[["W1","I'm Mona Pahlavi, from Pahlavi Construction, and this is Ms. Taylor, our interior designer. We're looking for a source for reclaimed lumber. Many customers are asking to incorporate old wood into their construction projects.","Tôi là Mona Pahlavi, đến từ Công ty Xây dựng Pahlavi, còn đây là chị Taylor, nhà thiết kế nội thất của chúng tôi. Chúng tôi đang tìm nguồn cung gỗ tái chế. Nhiều khách hàng yêu cầu đưa gỗ cũ vào các công trình xây dựng của họ."],["M","You've come to the right place. We carry wood rescued from barns, factories, and other structures that have been torn down.","Các chị đến đúng chỗ rồi. Chúng tôi có gỗ được thu hồi từ các nhà kho, nhà máy và những công trình khác đã bị phá dỡ."],["W2","People think using reclaimed lumber is cost-effective. Is that true?","Mọi người nghĩ dùng gỗ tái chế thì tiết kiệm chi phí. Có đúng vậy không?"],["M","Surprisingly, no. It's actually more expensive because we have to go through a lengthy process to make the wood reusable.","Thật bất ngờ là không. Thực ra nó đắt hơn vì chúng tôi phải trải qua một quy trình dài để làm cho gỗ có thể tái sử dụng."],["W1","Hmm. What do you think about that, Ms. Taylor?","Hừm. Chị nghĩ sao về điều đó, chị Taylor?"],["W2","Customers will pay more for the old wood look, but I'm sure they'd like to see some samples before deciding.","Khách hàng sẽ sẵn sàng trả nhiều hơn cho vẻ ngoài gỗ cũ, nhưng tôi chắc là họ muốn xem vài mẫu trước khi quyết định."]],"qs":[{"n":41,"q":"What type of business do the women work at?","qvi":"Hai người phụ nữ làm việc ở loại hình doanh nghiệp nào?","opts":["A furniture store","A hardware store","A construction company","A landscaping service"],"vi":["Cửa hàng nội thất","Cửa hàng đồ kim khí","Công ty xây dựng","Dịch vụ cảnh quan sân vườn"],"ans":"C","xp":"Người phụ nữ thứ nhất giới thiệu: \"I'm Mona Pahlavi, from Pahlavi Construction, and this is Ms. Taylor, our interior designer\" → họ làm ở công ty xây dựng → (C)."},{"n":42,"q":"According to the man, what may be surprising about a product?","qvi":"Theo người đàn ông, điều gì về sản phẩm có thể gây bất ngờ?","opts":["Its weight","Its durability","Its cost","Its color"],"vi":["Trọng lượng của nó","Độ bền của nó","Giá của nó","Màu sắc của nó"],"ans":"C","xp":"Khi được hỏi gỗ tái chế có tiết kiệm chi phí không, người đàn ông nói: \"Surprisingly, no. It's actually more expensive\" → điều bất ngờ là giá của nó (đắt hơn) → (C)."},{"n":43,"q":"What will Ms. Taylor most likely ask the man for?","qvi":"Chị Taylor nhiều khả năng sẽ đề nghị người đàn ông điều gì?","opts":["Some samples","A software demonstration","Some equipment","Free delivery"],"vi":["Một số mẫu","Một buổi trình diễn phần mềm","Một số thiết bị","Giao hàng miễn phí"],"ans":"A","xp":"Chị Taylor nói: \"I'm sure they'd like to see some samples before deciding\" → khách muốn xem mẫu trước, nên chị ấy sẽ xin vài mẫu gỗ → (A)."}],"a":"E24-T09-41-43.mp3"},{"ns":[44,46],"script":[["M","Thanks for agreeing to give me a tour of your company, Ms. Varma. It'll provide plenty of information to use in my article for the newspaper.","Cảm ơn chị Varma đã đồng ý dẫn tôi tham quan công ty. Chuyến tham quan sẽ cho tôi rất nhiều thông tin để viết bài báo."],["W","No problem. Did you say you write a series about local businesses?","Không có gì. Anh nói anh viết một loạt bài về các doanh nghiệp địa phương phải không?"],["M","Yes. I do a weekly column spotlighting the histories of unique companies in our region. Now, I read that your father founded the company.","Vâng. Tôi phụ trách một chuyên mục hằng tuần giới thiệu lịch sử của những công ty độc đáo trong vùng. Tôi có đọc được rằng cha chị là người sáng lập công ty."],["W","That's right. He started it with only ten employees.","Đúng vậy. Ông bắt đầu với chỉ mười nhân viên."],["M","It seems like it's expanded a lot since then, right?","Có vẻ như từ đó đến nay công ty đã mở rộng rất nhiều, phải không?"],["W","We export to fifty-nine countries around the world.","Chúng tôi xuất khẩu sang năm mươi chín quốc gia trên khắp thế giới."],["M","Impressive!","Ấn tượng thật!"],["W","Let me show you the shipping area.","Để tôi dẫn anh xem khu vực vận chuyển hàng."]],"qs":[{"n":44,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["A history professor","A mechanic","A lawyer","A journalist"],"vi":["Giáo sư lịch sử","Thợ cơ khí","Luật sư","Nhà báo"],"ans":"D","xp":"Người đàn ông nói: \"It'll provide plenty of information to use in my article for the newspaper\" và \"I do a weekly column\" → anh ấy viết bài cho báo → nhà báo (journalist) → (D)."},{"n":45,"q":"What does the man say he read about the company?","qvi":"Người đàn ông nói anh ấy đã đọc được gì về công ty?","opts":["It was started by the woman's father.","It manufactures automobile parts.","It was recently purchased by a competitor.","It is the area's largest employer."],"vi":["Nó được thành lập bởi cha của người phụ nữ.","Nó sản xuất phụ tùng ô tô.","Nó vừa được một đối thủ cạnh tranh mua lại.","Nó là nơi tuyển dụng nhiều lao động nhất khu vực."],"ans":"A","xp":"Người đàn ông nói: \"I read that your father founded the company\" → 'founded' (thành lập) = 'was started by' → (A)."},{"n":46,"q":"Why does the woman say, \"We export to fifty-nine countries around the world\"?","qvi":"Tại sao người phụ nữ nói \"Chúng tôi xuất khẩu sang 59 quốc gia trên thế giới\"?","opts":["To correct an error","To justify a decision","To confirm an assumption","To explain a delay"],"vi":["Để sửa một lỗi","Để biện minh cho một quyết định","Để xác nhận một giả định","Để giải thích một sự chậm trễ"],"ans":"C","xp":"Câu hỏi hàm ý. Người đàn ông đoán: \"It seems like it's expanded a lot since then, right?\" (có vẻ công ty đã mở rộng nhiều). Cô ấy đáp 'xuất khẩu sang 59 nước' → xác nhận điều anh ấy phỏng đoán là đúng → (C)."}],"a":"E24-T09-44-46.mp3"},{"ns":[47,49],"script":[["W","Hi, Sergey. Have you been able to finish the updates for the new bridge we're designing? I'd like to include them in the agenda for our client meeting next week.","Chào Sergey. Anh đã hoàn thành phần cập nhật cho cây cầu mới mà chúng ta đang thiết kế chưa? Tôi muốn đưa chúng vào chương trình cuộc họp với khách hàng tuần sau."],["M","Yes. I've reinforced some structural features and added the pedestrian walkway they asked for.","Rồi. Tôi đã gia cố một số bộ phận kết cấu và thêm lối đi bộ mà họ yêu cầu."],["W","Oh, perfect! Could you take over that part of the meeting to explain the changes to the clients?","Ồ, tuyệt quá! Anh có thể phụ trách phần đó trong cuộc họp để giải thích các thay đổi cho khách hàng không?"],["M","Sure, I can do that. But first, I'll send you the updated calculations on the bridge's weight capacity. Some of the numbers have changed significantly because of the structural changes we've made.","Được, tôi làm được. Nhưng trước hết, tôi sẽ gửi chị các tính toán cập nhật về tải trọng của cây cầu. Một số con số đã thay đổi đáng kể do những thay đổi kết cấu chúng ta đã thực hiện."],["W","OK. I'll take a look tomorrow and get back to you.","Được. Mai tôi sẽ xem và phản hồi anh."]],"qs":[{"n":47,"q":"Who most likely are the speakers?","qvi":"Hai người nói nhiều khả năng là ai?","opts":["Artists","Engineers","Accountants","Lawyers"],"vi":["Nghệ sĩ","Kỹ sư","Kế toán viên","Luật sư"],"ans":"B","xp":"Người phụ nữ hỏi về \"the updates for the new bridge we're designing\", người đàn ông nói \"I've reinforced some structural features\" → họ thiết kế cầu, gia cố kết cấu → kỹ sư → (B)."},{"n":48,"q":"What does the woman ask the man to do?","qvi":"Người phụ nữ nhờ người đàn ông làm gì?","opts":["Lead part of a meeting","Revise a cost estimate","Contact a client","Perform an inspection"],"vi":["Chủ trì một phần cuộc họp","Chỉnh sửa bảng dự toán chi phí","Liên hệ với khách hàng","Tiến hành kiểm tra"],"ans":"A","xp":"Người phụ nữ: \"Could you take over that part of the meeting to explain the changes to the clients?\" → phụ trách một phần cuộc họp = 'lead part of a meeting' → (A)."},{"n":49,"q":"What will the man send the woman?","qvi":"Người đàn ông sẽ gửi cho người phụ nữ cái gì?","opts":["An itinerary","A contract","Some driving directions","Some calculations"],"vi":["Lịch trình chuyến đi","Hợp đồng","Chỉ dẫn đường lái xe","Một số tính toán"],"ans":"D","xp":"Người đàn ông: \"I'll send you the updated calculations on the bridge's weight capacity\" → gửi các tính toán → (D)."}],"a":"E24-T09-47-49.mp3"},{"ns":[50,52],"script":[["W","Ketan, what do you think about this month's marketing report? It looks like our computer keyboard sales are decreasing.","Ketan, anh thấy báo cáo marketing tháng này thế nào? Có vẻ doanh số bàn phím máy tính của chúng ta đang giảm."],["M","Yes, I saw that. I think it may be connected to our existing marketing strategies. The keyboards are advertised mostly on our Web site. I think we need to look into expanding our advertising campaign to other types of media.","Vâng, tôi thấy rồi. Tôi nghĩ có thể nó liên quan đến chiến lược marketing hiện tại của chúng ta. Bàn phím chủ yếu được quảng cáo trên trang web của chúng ta. Tôi nghĩ chúng ta cần tính đến việc mở rộng chiến dịch quảng cáo sang các loại phương tiện truyền thông khác."],["W","That's a good idea. Perhaps we need to advocate for a larger marketing budget. That would provide us with more options. Let's bring this up at our next marketing meeting.","Ý hay đấy. Có lẽ chúng ta cần đề xuất tăng ngân sách marketing. Như vậy chúng ta sẽ có nhiều lựa chọn hơn. Hãy nêu vấn đề này trong cuộc họp marketing tới."]],"qs":[{"n":50,"q":"What products are the speakers discussing?","qvi":"Hai người đang thảo luận về sản phẩm nào?","opts":["Software programs","Screen protectors","Computer keyboards","Wireless printers"],"vi":["Chương trình phần mềm","Miếng dán bảo vệ màn hình","Bàn phím máy tính","Máy in không dây"],"ans":"C","xp":"Người phụ nữ: \"It looks like our computer keyboard sales are decreasing\" và người đàn ông: \"The keyboards are advertised mostly on our Web site\" → sản phẩm là bàn phím máy tính → (C)."},{"n":51,"q":"According to the man, how are the products currently being advertised?","qvi":"Theo người đàn ông, sản phẩm hiện đang được quảng cáo bằng cách nào?","opts":["On television","On a Web site","In magazines","By direct mail"],"vi":["Trên truyền hình","Trên trang web","Trên tạp chí","Qua thư gửi trực tiếp"],"ans":"B","xp":"Người đàn ông: \"The keyboards are advertised mostly on our Web site\" → quảng cáo trên trang web → (B)."},{"n":52,"q":"What topic will the speakers discuss at a meeting?","qvi":"Hai người sẽ thảo luận chủ đề gì tại cuộc họp?","opts":["Budget changes","Design modifications","Production delays","Open job positions"],"vi":["Thay đổi ngân sách","Điều chỉnh thiết kế","Chậm trễ sản xuất","Các vị trí đang tuyển dụng"],"ans":"A","xp":"Người phụ nữ: \"Perhaps we need to advocate for a larger marketing budget... Let's bring this up at our next marketing meeting\" → sẽ bàn về việc tăng ngân sách = thay đổi ngân sách → (A)."}],"a":"E24-T09-50-52.mp3"},{"ns":[53,55],"script":[["W","Hi, Raul. I wanted to let you know that we received all of the bids we were waiting on for the Meyerville Bridge replacement project.","Chào Raul. Tôi muốn báo với anh là chúng ta đã nhận được tất cả các hồ sơ dự thầu đang chờ cho dự án thay thế cầu Meyerville."],["M","Thanks. Are there any acceptable bids? I'm worried that with costs rising nowadays we may exceed our budget for city infrastructure projects.","Cảm ơn chị. Có hồ sơ nào chấp nhận được không? Tôi lo là với chi phí đang tăng như hiện nay, chúng ta có thể vượt ngân sách cho các dự án hạ tầng của thành phố."],["W","Well, steel costs per ton are in the thousands for every bid.","À, giá thép mỗi tấn đều lên tới hàng nghìn (đô la) trong mọi hồ sơ dự thầu."],["M","I see. We've already reached out to all of the contractors we can, so we'll just need to seek additional funding, then. Let's put together a spreadsheet comparing the bids this afternoon. We'll use that for reference at our next transportation department meeting.","Tôi hiểu rồi. Chúng ta đã liên hệ với tất cả các nhà thầu có thể rồi, vậy thì chúng ta chỉ còn cách tìm thêm nguồn vốn thôi. Chiều nay chúng ta hãy lập một bảng tính so sánh các hồ sơ dự thầu. Chúng ta sẽ dùng nó để tham khảo trong cuộc họp tới của sở giao thông."]],"qs":[{"n":53,"q":"What project are the speakers mainly discussing?","qvi":"Hai người chủ yếu thảo luận về dự án nào?","opts":["The demolition of a shopping center","The construction of a skyscraper","The replacement of a bridge","The redesign of a train station"],"vi":["Việc phá dỡ một trung tâm mua sắm","Việc xây dựng một tòa nhà chọc trời","Việc thay thế một cây cầu","Việc thiết kế lại một nhà ga xe lửa"],"ans":"C","xp":"Người phụ nữ: \"we received all of the bids we were waiting on for the Meyerville Bridge replacement project\" → dự án thay thế cầu → (C)."},{"n":54,"q":"What does the woman imply when she says, \"steel costs per ton are in the thousands for every bid\"?","qvi":"Người phụ nữ ngụ ý gì khi nói \"giá thép mỗi tấn đều lên tới hàng nghìn trong mọi hồ sơ dự thầu\"?","opts":["A coworker's calculations are incorrect.","The man's concern is justified.","A contractor should be replaced.","A new construction method will be used."],"vi":["Tính toán của một đồng nghiệp bị sai.","Mối lo của người đàn ông là có cơ sở.","Nên thay một nhà thầu.","Một phương pháp xây dựng mới sẽ được áp dụng."],"ans":"B","xp":"Câu hỏi hàm ý. Người đàn ông lo: \"I'm worried that with costs rising nowadays we may exceed our budget\". Cô ấy đáp giá thép hồ sơ nào cũng hàng nghìn/tấn → đúng là chi phí cao, nỗi lo của anh ấy có cơ sở → (B)."},{"n":55,"q":"What will the speakers do this afternoon?","qvi":"Chiều nay hai người sẽ làm gì?","opts":["Take some photographs","Organize a site visit","Create a spreadsheet","Speak to an accountant"],"vi":["Chụp vài bức ảnh","Tổ chức một chuyến khảo sát công trường","Lập một bảng tính","Nói chuyện với kế toán"],"ans":"C","xp":"Người đàn ông: \"Let's put together a spreadsheet comparing the bids this afternoon\" → 'put together' = lập/tạo (create) bảng tính → (C)."}],"a":"E24-T09-53-55.mp3"},{"ns":[56,58],"script":[["M","Hi, Amy. I just got back from that industry trade show in Vancouver. Thanks for recommending the Arch Coast Hotel.","Chào Amy. Tôi vừa trở về từ hội chợ thương mại ngành ở Vancouver. Cảm ơn chị đã giới thiệu khách sạn Arch Coast."],["W","I thought you'd like it. I know how important conservation is to you. Did you know that it was the first environmentally sustainable hotel in Canada?","Tôi nghĩ là anh sẽ thích nó. Tôi biết việc bảo tồn môi trường quan trọng với anh thế nào. Anh có biết đó là khách sạn bền vững về môi trường đầu tiên ở Canada không?"],["M","Yes, I spoke with the owner. He described the hotel's history and told me about their plans. They'll be closed next month while they work on an addition to the main building.","Có, tôi đã nói chuyện với chủ khách sạn. Ông ấy kể về lịch sử khách sạn và cho tôi biết kế hoạch của họ. Tháng sau họ sẽ đóng cửa trong lúc xây phần mở rộng cho tòa nhà chính."]],"qs":[{"n":56,"q":"Why was the man in Vancouver?","qvi":"Tại sao người đàn ông đến Vancouver?","opts":["To attend a trade show","To meet with a client","To take a vacation","To facilitate a workshop"],"vi":["Để tham dự hội chợ thương mại","Để gặp khách hàng","Để đi nghỉ","Để điều phối một buổi hội thảo"],"ans":"A","xp":"Người đàn ông: \"I just got back from that industry trade show in Vancouver\" → anh ấy đến Vancouver để dự hội chợ thương mại → (A)."},{"n":57,"q":"What does the woman say about a hotel?","qvi":"Người phụ nữ nói gì về một khách sạn?","opts":["It was a suitable venue for an event.","It was reserved by a professional organization.","It is environmentally friendly.","It is convenient to public transportation."],"vi":["Đó là địa điểm phù hợp cho một sự kiện.","Nó được một tổ chức nghề nghiệp đặt trước.","Nó thân thiện với môi trường.","Nó thuận tiện đi lại bằng phương tiện công cộng."],"ans":"C","xp":"Người phụ nữ: \"it was the first environmentally sustainable hotel in Canada\" → 'environmentally sustainable' (bền vững về môi trường) = 'environmentally friendly' → (C)."},{"n":58,"q":"Why will the hotel close temporarily?","qvi":"Tại sao khách sạn sẽ tạm đóng cửa?","opts":["To allow staff to conduct a training session","To be subject to an inspection","To accommodate an expansion","To ensure movers have access to the rooms"],"vi":["Để nhân viên tổ chức một buổi đào tạo","Để được thanh tra","Để tiến hành việc mở rộng","Để đảm bảo nhân viên chuyển đồ có thể vào các phòng"],"ans":"C","xp":"Người đàn ông: \"They'll be closed next month while they work on an addition to the main building\" → xây thêm phần mở rộng (addition) = expansion → (C)."}],"a":"E24-T09-56-58.mp3"},{"ns":[59,61],"script":[["M","Francesca, welcome! I hope you didn't have too much trouble finding our banking office. Please, take a seat. I've read your application, and it looks like we'll be able to finance your business project.","Chào mừng chị Francesca! Hy vọng chị tìm đến văn phòng ngân hàng của chúng tôi không quá vất vả. Mời chị ngồi. Tôi đã đọc đơn đăng ký của chị, và có vẻ chúng tôi sẽ có thể cấp vốn cho dự án kinh doanh của chị."],["W","Oh, that's wonderful news! Opening a flower shop has been my dream for so long.","Ôi, tin tuyệt vời quá! Mở một tiệm hoa là ước mơ của tôi từ rất lâu rồi."],["M","Absolutely. I just have one detail to confirm. Do you still live at 21 Anderson Avenue?","Chắc chắn rồi. Tôi chỉ cần xác nhận một chi tiết. Chị vẫn sống ở số 21 đại lộ Anderson chứ?"],["W","Actually, I've recently moved. Here's a card with my new address.","Thật ra tôi mới chuyển nhà. Đây là tấm thẻ có địa chỉ mới của tôi."],["M","Thanks! I'll be right back. I need to go over to the printer to pick up some documents that I need you to sign.","Cảm ơn chị! Tôi quay lại ngay. Tôi cần qua máy in lấy một số giấy tờ cần chị ký."]],"qs":[{"n":59,"q":"What did the woman apply for?","qvi":"Người phụ nữ đã nộp đơn xin cái gì?","opts":["A professional license","A job at a bank","A business loan","A credit card"],"vi":["Giấy phép hành nghề","Việc làm ở ngân hàng","Khoản vay kinh doanh","Thẻ tín dụng"],"ans":"C","xp":"Người đàn ông (ở ngân hàng): \"I've read your application, and it looks like we'll be able to finance your business project\" → ngân hàng cấp vốn cho dự án kinh doanh = khoản vay kinh doanh → (C)."},{"n":60,"q":"What information does the man ask the woman to verify?","qvi":"Người đàn ông đề nghị người phụ nữ xác nhận thông tin gì?","opts":["Her income","Her account number","Her phone number","Her address"],"vi":["Thu nhập của cô ấy","Số tài khoản của cô ấy","Số điện thoại của cô ấy","Địa chỉ của cô ấy"],"ans":"D","xp":"Người đàn ông: \"I just have one detail to confirm. Do you still live at 21 Anderson Avenue?\" → xác nhận nơi ở = địa chỉ → (D)."},{"n":61,"q":"What will the woman most likely do next?","qvi":"Người phụ nữ nhiều khả năng sẽ làm gì tiếp theo?","opts":["Sign some documents","Download some software","Speak with a friend","Make an appointment"],"vi":["Ký một số giấy tờ","Tải một phần mềm","Nói chuyện với một người bạn","Đặt lịch hẹn"],"ans":"A","xp":"Người đàn ông: \"I need to go over to the printer to pick up some documents that I need you to sign\" → tiếp theo cô ấy sẽ ký giấy tờ → (A)."}],"a":"E24-T09-59-61.mp3"},{"ns":[62,64],"script":[["W","Goodland Nature Preserve and Resort. How may I help you?","Khu bảo tồn thiên nhiên và khu nghỉ dưỡng Goodland xin nghe. Tôi có thể giúp gì cho anh?"],["M","I have a two-person cabin booked for next Monday night, but I'm hoping to change my reservation.","Tôi đã đặt một nhà gỗ cho hai người vào tối thứ Hai tuần sau, nhưng tôi muốn thay đổi đặt phòng."],["W","OK—to a different day?","Vâng — đổi sang ngày khác ạ?"],["M","No, we still want to stay on Monday night, but we'd like a bigger cabin.","Không, chúng tôi vẫn muốn ở vào tối thứ Hai, nhưng chúng tôi muốn một căn nhà gỗ lớn hơn."],["W","What size do you need?","Anh cần căn cỡ nào?"],["M","One that accommodates three or more people.","Căn chứa được từ ba người trở lên."],["W","Well, there's only one larger cabin available. It costs 150 dollars.","À, chỉ còn trống một căn lớn hơn thôi. Giá là 150 đô la."],["M","That's fine—we'll take it! Also, do you offer private tours of the nature preserve?","Được thôi — chúng tôi lấy căn đó! Ngoài ra, bên chị có tổ chức tour riêng tham quan khu bảo tồn thiên nhiên không?"],["W","We do! It's complimentary with your cabin booking. Just let me know when you'd like to do it, and I'll make arrangements with our guide.","Có ạ! Tour này miễn phí khi anh đặt nhà gỗ. Anh chỉ cần cho tôi biết khi nào anh muốn đi, tôi sẽ sắp xếp với hướng dẫn viên của chúng tôi."]],"qs":[{"n":62,"q":"When will the man stay at the resort?","qvi":"Người đàn ông sẽ ở khu nghỉ dưỡng khi nào?","opts":["On Monday night","On Tuesday night","On Wednesday night","On Thursday night"],"vi":["Vào tối thứ Hai","Vào tối thứ Ba","Vào tối thứ Tư","Vào tối thứ Năm"],"ans":"A","xp":"Người đàn ông: \"we still want to stay on Monday night, but we'd like a bigger cabin\" → vẫn ở tối thứ Hai, chỉ đổi căn lớn hơn → (A)."},{"n":63,"q":"Look at the graphic. Which cabin does the man agree to reserve?","qvi":"Hãy nhìn bảng. Người đàn ông đồng ý đặt căn nhà gỗ nào?","opts":["North cabin","East cabin","South cabin","West cabin"],"vi":["Nhà gỗ phía Bắc","Nhà gỗ phía Đông","Nhà gỗ phía Nam","Nhà gỗ phía Tây"],"ans":"D","xp":"Người phụ nữ: \"there's only one larger cabin available. It costs 150 dollars\" và người đàn ông: \"That's fine—we'll take it!\" → nhìn bảng, căn giá $150 là West cabin → (D)."},{"n":64,"q":"What can cabin guests receive free of charge?","qvi":"Khách thuê nhà gỗ được nhận miễn phí cái gì?","opts":["Shuttle rides","Swimming pool access","A hot breakfast","A guided tour"],"vi":["Xe đưa đón","Sử dụng hồ bơi","Bữa sáng nóng","Một tour có hướng dẫn viên"],"ans":"D","xp":"Người đàn ông hỏi \"do you offer private tours of the nature preserve?\", người phụ nữ đáp: \"We do! It's complimentary with your cabin booking... I'll make arrangements with our guide\" → 'complimentary' = miễn phí; tour có hướng dẫn viên → (D)."}],"a":"E24-T09-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["W","Can I help you find something, Lee?","Tôi giúp anh tìm gì được không, Lee?"],["M","Please! One of the tractors just broke down out in the cornfield, and Kyle sent me back for a toolbox. I just started working here, though, so I'm still getting used to the layout of this place.","Nhờ chị với! Một chiếc máy kéo vừa bị hỏng ngoài cánh đồng ngô, và Kyle bảo tôi quay về lấy hộp dụng cụ. Nhưng tôi mới bắt đầu làm ở đây nên vẫn chưa quen cách bố trí của nơi này."],["W","Oh, you'll want to go to the toolshed. It's right across the road, next to the pond.","À, anh cần đến nhà kho dụng cụ. Nó ở ngay bên kia đường, cạnh cái ao."],["M","Alright. Which way is that?","Được rồi. Đi lối nào vậy?"],["W","Actually, I'll head over there with you. I need to grab a wheelbarrow.","Thật ra tôi sẽ đi cùng anh qua đó. Tôi cũng cần lấy một chiếc xe cút kít."]],"qs":[{"n":65,"q":"What problem does the man mention?","qvi":"Người đàn ông đề cập đến vấn đề gì?","opts":["A worker has not yet arrived.","Some tools have been misplaced.","A tractor is not working.","Some crops are damaged."],"vi":["Một công nhân vẫn chưa đến.","Một số dụng cụ bị để nhầm chỗ.","Một chiếc máy kéo không hoạt động.","Một số cây trồng bị hư hại."],"ans":"C","xp":"Người đàn ông: \"One of the tractors just broke down out in the cornfield\" → 'broke down' (bị hỏng) = 'is not working' → (C)."},{"n":66,"q":"Look at the graphic. Where does the woman tell the man to go?","qvi":"Hãy nhìn sơ đồ. Người phụ nữ bảo người đàn ông đi đến đâu?","opts":["To building 1","To building 2","To building 3","To building 4"],"vi":["Đến tòa nhà 1","Đến tòa nhà 2","Đến tòa nhà 3","Đến tòa nhà 4"],"ans":"A","xp":"Người phụ nữ: \"you'll want to go to the toolshed. It's right across the road, next to the pond\" → trên sơ đồ, tòa nhà nằm cạnh ao (Pond) là tòa nhà 1 → (A)."},{"n":67,"q":"What does the woman offer to do?","qvi":"Người phụ nữ đề nghị làm gì?","opts":["Complete the man's work shift","Go with the man","Move some boxes","Unlock a gate"],"vi":["Làm nốt ca làm việc của người đàn ông","Đi cùng người đàn ông","Chuyển vài cái thùng","Mở khóa cổng"],"ans":"B","xp":"Người phụ nữ: \"I'll head over there with you\" → cô ấy sẽ đi cùng anh ấy → (B)."}],"a":"E24-T09-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","A client just called. I need to check on a large batch of tablecloths, napkins, and linens that we're cleaning.","Một khách hàng vừa gọi. Tôi cần kiểm tra một mẻ lớn khăn trải bàn, khăn ăn và đồ vải lanh mà chúng ta đang giặt."],["W","What's the job number?","Số đơn việc là bao nhiêu?"],["M","Um. Seventeen. They requested that everything be ready tonight instead of tomorrow. Let's make this a priority.","Ừm. Số mười bảy. Họ yêu cầu mọi thứ xong trong tối nay thay vì ngày mai. Hãy ưu tiên đơn này."],["W","OK. I see their initial order came in at eleven thirty this morning. Their items haven't been placed in the washer yet. When do they need this rush work done?","Được. Tôi thấy đơn ban đầu của họ đến lúc mười một giờ ba mươi sáng nay. Đồ của họ vẫn chưa được cho vào máy giặt. Họ cần đơn gấp này xong lúc mấy giờ?"],["M","By five P.M.","Trước 5 giờ chiều."],["W","We can do it if we put them ahead of job sixteen.","Chúng ta có thể làm kịp nếu xếp đơn của họ lên trước đơn số mười sáu."],["M","Sounds good.","Nghe được đấy."],["W","So I'll just hold sixteen back then. That will help free up some washing machines and dryers.","Vậy tôi sẽ tạm hoãn đơn mười sáu. Như thế sẽ giúp trống ra vài máy giặt và máy sấy."]],"qs":[{"n":68,"q":"Where do the speakers most likely work?","qvi":"Hai người nói nhiều khả năng làm việc ở đâu?","opts":["At a fabric store","At an employee staffing service","At a health-inspection department","At a commercial laundry facility"],"vi":["Ở cửa hàng vải","Ở dịch vụ cung ứng nhân sự","Ở phòng thanh tra y tế","Ở cơ sở giặt là thương mại"],"ans":"D","xp":"Người đàn ông: \"a large batch of tablecloths, napkins, and linens that we're cleaning\"; người phụ nữ nhắc đến 'washer', 'washing machines and dryers' → họ làm ở cơ sở giặt là → (D)."},{"n":69,"q":"Look at the graphic. Which business did the man receive a request from?","qvi":"Hãy nhìn bảng. Người đàn ông nhận được yêu cầu từ doanh nghiệp nào?","opts":["Larkston Hotel","Trissler Hotel","Benchlal Restaurant","Cho Fine Dining"],"vi":["Khách sạn Larkston","Khách sạn Trissler","Nhà hàng Benchlal","Nhà hàng Cho Fine Dining"],"ans":"C","xp":"Khi được hỏi số đơn, người đàn ông trả lời: \"Seventeen\" (người phụ nữ cũng nói đơn đến lúc 11:30 sáng) → trong bảng, đơn số 17 là Benchlal Restaurant → (C)."},{"n":70,"q":"How does the woman suggest resolving an issue?","qvi":"Người phụ nữ đề xuất giải quyết vấn đề bằng cách nào?","opts":["By issuing a refund","By consulting with a supervisor","By explaining a policy to a customer","By adjusting the order of some work"],"vi":["Bằng cách hoàn tiền","Bằng cách hỏi ý kiến cấp trên","Bằng cách giải thích chính sách cho khách hàng","Bằng cách điều chỉnh thứ tự công việc"],"ans":"D","xp":"Người phụ nữ: \"We can do it if we put them ahead of job sixteen\" → đưa đơn 17 lên trước đơn 16 = thay đổi thứ tự công việc → (D)."}],"a":"E24-T09-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Attention, all Curious Minds shoppers. During our going-out-of-business sale, all of our hardcover books are being deeply discounted. From now until the end of the week, they will be sold at an 80 percent discount. In addition, all paperbacks will be 50 percent off this week.","Xin quý khách mua sắm tại Curious Minds chú ý. Trong đợt bán hàng thanh lý đóng cửa, tất cả sách bìa cứng của chúng tôi đang được giảm giá sâu. Từ bây giờ đến cuối tuần, sách bìa cứng sẽ được bán với mức giảm 80%. Ngoài ra, tất cả sách bìa mềm sẽ được giảm 50% trong tuần này."],["","And please remember—while this store will be shutting down soon, you will still be able to shop in person at our Lawrenceville location, which is just a fifteen-minute drive from here.","Và xin hãy nhớ — dù cửa hàng này sắp đóng cửa, quý khách vẫn có thể mua sắm trực tiếp tại chi nhánh Lawrenceville của chúng tôi, chỉ cách đây mười lăm phút lái xe."]],"qs":[{"n":71,"q":"Where is the announcement most likely being made?","qvi":"Thông báo này nhiều khả năng được phát ở đâu?","opts":["At a clothing shop","At a bookstore","At a hardware store","At an auto dealership"],"vi":["Ở cửa hàng quần áo","Ở hiệu sách","Ở cửa hàng đồ kim khí","Ở đại lý ô tô"],"ans":"B","xp":"Người nói: \"all of our hardcover books are being deeply discounted\" và \"all paperbacks will be 50 percent off\" → bán sách bìa cứng, bìa mềm → hiệu sách → (B)."},{"n":72,"q":"What does the speaker say is happening this week?","qvi":"Người nói cho biết điều gì đang diễn ra trong tuần này?","opts":["Discounts are being offered.","An area is being remodeled.","New merchandise is arriving.","Interviews are being conducted."],"vi":["Đang có chương trình giảm giá.","Một khu vực đang được sửa sang lại.","Hàng mới đang về.","Đang tiến hành phỏng vấn."],"ans":"A","xp":"Người nói: \"From now until the end of the week, they will be sold at an 80 percent discount\" và \"all paperbacks will be 50 percent off this week\" → tuần này đang giảm giá → (A)."},{"n":73,"q":"What does the speaker remind the listeners about?","qvi":"Người nói nhắc người nghe về điều gì?","opts":["A return policy","A rewards program","An updated Web site","An additional location"],"vi":["Chính sách đổi trả","Chương trình tích điểm thưởng","Trang web được cập nhật","Một chi nhánh khác"],"ans":"D","xp":"Người nói: \"please remember—... you will still be able to shop in person at our Lawrenceville location\" → nhắc về một chi nhánh khác của cửa hàng → (D)."}],"a":"E24-T09-71-73.mp3"},{"ns":[74,76],"script":[["","Before we wrap up this meeting, I wanted to discuss the picnic our department has been planning for next Saturday. I've already purchased most of the decorations, and Lorenzo has volunteered to bring a cake.","Trước khi kết thúc cuộc họp này, tôi muốn bàn về buổi dã ngoại mà phòng chúng ta đang lên kế hoạch cho thứ Bảy tuần sau. Tôi đã mua gần hết đồ trang trí, và Lorenzo đã tình nguyện mang bánh kem đến."],["","Actually, Lorenzo, there's a great bakery not far from the park that you could order from. It's cash only, but there's a bank across the street.","À Lorenzo này, có một tiệm bánh rất ngon cách công viên không xa mà anh có thể đặt bánh. Tiệm chỉ nhận tiền mặt, nhưng có một ngân hàng ở bên kia đường."],["","We still need other food and supplies, though. I've posted a list of what we still need in the break room, so write your name next to the item you'll bring.","Tuy vậy, chúng ta vẫn cần thêm đồ ăn và vật dụng khác. Tôi đã dán danh sách những thứ còn thiếu ở phòng nghỉ, vì vậy mọi người hãy ghi tên mình bên cạnh món đồ mình sẽ mang."]],"qs":[{"n":74,"q":"What is the speaker discussing?","qvi":"Người nói đang bàn về điều gì?","opts":["A vacation schedule","A professional-development opportunity","A department's social event","A marketing campaign"],"vi":["Lịch nghỉ phép","Một cơ hội phát triển chuyên môn","Một sự kiện giao lưu của phòng ban","Một chiến dịch marketing"],"ans":"C","xp":"Người nói: \"I wanted to discuss the picnic our department has been planning for next Saturday\" → buổi dã ngoại của phòng = sự kiện giao lưu của phòng ban → (C)."},{"n":75,"q":"Why does the speaker say, \"there's a bank across the street\"?","qvi":"Tại sao người nói nói \"có một ngân hàng ở bên kia đường\"?","opts":["To request assistance","To make a suggestion","To provide driving directions","To complain about a location"],"vi":["Để nhờ giúp đỡ","Để đưa ra một gợi ý","Để chỉ đường lái xe","Để phàn nàn về một địa điểm"],"ans":"B","xp":"Câu hỏi hàm ý. Người nói gợi ý Lorenzo đặt bánh ở tiệm gần công viên: \"It's cash only, but there's a bank across the street\" → tiệm chỉ nhận tiền mặt nhưng có ngân hàng gần đó để rút tiền → vẫn nên đặt ở đó; đây là lời gợi ý → (B)."},{"n":76,"q":"What does the speaker ask the listeners to do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Fill out a sign-up sheet","E-mail agenda items","Attend an additional meeting","Complete an evaluation form"],"vi":["Điền vào phiếu đăng ký","Gửi e-mail các mục cho chương trình họp","Tham dự thêm một cuộc họp","Hoàn thành phiếu đánh giá"],"ans":"A","xp":"Người nói: \"I've posted a list of what we still need in the break room, so write your name next to the item you'll bring\" → ghi tên vào danh sách = điền phiếu đăng ký (sign-up sheet) → (A)."}],"a":"E24-T09-74-76.mp3"},{"ns":[77,79],"script":[["","In local news, Malton Supermarket is throwing a party today to celebrate its one-year anniversary. I spoke with owner Antonella Lambert about the store's success. She told me that Malton strives to offer products from all over the world to meet the needs of the city's diverse population. And customers have responded with enthusiasm, happy to find familiar products from their countries of origin.","Tin tức địa phương: Siêu thị Malton hôm nay tổ chức tiệc để kỷ niệm một năm thành lập. Tôi đã trò chuyện với chủ siêu thị, bà Antonella Lambert, về thành công của cửa hàng. Bà cho biết Malton luôn cố gắng cung cấp sản phẩm từ khắp nơi trên thế giới để đáp ứng nhu cầu của cộng đồng dân cư đa dạng trong thành phố. Và khách hàng đã hưởng ứng rất nhiệt tình, vui mừng khi tìm thấy những sản phẩm quen thuộc từ quê hương của họ."],["","As for her vision for the future, Lambert said she's already started raising money from investors so that she can open more Malton Supermarkets in adjacent towns.","Về tầm nhìn tương lai, bà Lambert cho biết bà đã bắt đầu huy động vốn từ các nhà đầu tư để có thể mở thêm các siêu thị Malton ở những thị trấn lân cận."]],"qs":[{"n":77,"q":"Why is Malton Supermarket hosting a party?","qvi":"Tại sao siêu thị Malton tổ chức tiệc?","opts":["To welcome a new manager","To celebrate an anniversary","To thank local suppliers","To promote new products"],"vi":["Để chào đón quản lý mới","Để kỷ niệm ngày thành lập","Để cảm ơn các nhà cung cấp địa phương","Để quảng bá sản phẩm mới"],"ans":"B","xp":"Người nói: \"Malton Supermarket is throwing a party today to celebrate its one-year anniversary\" → kỷ niệm một năm thành lập → (B)."},{"n":78,"q":"According to Antonella Lambert, why is Malton Supermarket successful?","qvi":"Theo bà Antonella Lambert, tại sao siêu thị Malton thành công?","opts":["It is open 24 hours a day.","It is near public transportation.","It offers international products.","It provides friendly service."],"vi":["Nó mở cửa 24 giờ mỗi ngày.","Nó ở gần phương tiện công cộng.","Nó bán các sản phẩm quốc tế.","Nó phục vụ thân thiện."],"ans":"C","xp":"Khi nói về thành công của cửa hàng: \"Malton strives to offer products from all over the world\" → sản phẩm từ khắp thế giới = sản phẩm quốc tế (international products) → (C)."},{"n":79,"q":"Why is Antonella Lambert raising funds?","qvi":"Tại sao bà Antonella Lambert huy động vốn?","opts":["To open additional locations","To remodel a space","To increase advertising","To support a charity"],"vi":["Để mở thêm chi nhánh","Để sửa sang lại một không gian","Để tăng cường quảng cáo","Để ủng hộ một tổ chức từ thiện"],"ans":"A","xp":"Người nói: \"she's already started raising money from investors so that she can open more Malton Supermarkets in adjacent towns\" → mở thêm siêu thị = mở thêm chi nhánh → (A)."}],"a":"E24-T09-77-79.mp3"},{"ns":[80,82],"script":[["","Hi, everyone. I'd just like to say that I'm aware of the issues you're experiencing with Internet speed and connectivity in the office. I realize how difficult it is to get your work done with the interruptions. We're fixing it as fast as we can—a technician is coming in an hour or two.","Chào mọi người. Tôi chỉ muốn nói rằng tôi biết các vấn đề mà mọi người đang gặp phải với tốc độ và kết nối Internet trong văn phòng. Tôi hiểu việc hoàn thành công việc khó khăn thế nào khi cứ bị gián đoạn. Chúng tôi đang khắc phục nhanh nhất có thể — một kỹ thuật viên sẽ đến trong một hai tiếng nữa."],["","I know the sales reports are due on Wednesday, but I've talked to your team leads about the issue. As always, thanks for your hard work.","Tôi biết hạn nộp báo cáo doanh số là thứ Tư, nhưng tôi đã nói chuyện với các trưởng nhóm của mọi người về vấn đề này rồi. Như mọi khi, cảm ơn mọi người đã làm việc chăm chỉ."]],"qs":[{"n":80,"q":"What is not working properly?","qvi":"Cái gì đang không hoạt động bình thường?","opts":["The lighting","The plumbing","A payment portal","An Internet connection"],"vi":["Hệ thống chiếu sáng","Hệ thống ống nước","Cổng thanh toán","Kết nối Internet"],"ans":"D","xp":"Người nói: \"I'm aware of the issues you're experiencing with Internet speed and connectivity in the office\" → kết nối Internet có vấn đề → (D)."},{"n":81,"q":"According to the speaker, what will happen in the next few hours?","qvi":"Theo người nói, điều gì sẽ xảy ra trong vài giờ tới?","opts":["A technician will come in.","A complaint will be filed.","A Web site will be updated.","An office will close."],"vi":["Một kỹ thuật viên sẽ đến.","Một đơn khiếu nại sẽ được nộp.","Một trang web sẽ được cập nhật.","Một văn phòng sẽ đóng cửa."],"ans":"A","xp":"Người nói: \"a technician is coming in an hour or two\" → trong một hai tiếng nữa kỹ thuật viên sẽ đến → (A)."},{"n":82,"q":"What does the speaker mean when he says, \"I've talked to your team leads about the issue\"?","qvi":"Người nói có ý gì khi nói \"Tôi đã nói chuyện với các trưởng nhóm của mọi người về vấn đề này\"?","opts":["The team leads will take over a project.","A deadline will be adjusted.","New teams will be formed.","An extra expense will be approved."],"vi":["Các trưởng nhóm sẽ tiếp quản một dự án.","Một thời hạn sẽ được điều chỉnh.","Các nhóm mới sẽ được thành lập.","Một khoản chi thêm sẽ được duyệt."],"ans":"B","xp":"Câu hỏi hàm ý. Ngay trước đó người nói nhắc: \"I know the sales reports are due on Wednesday, but...\" → mạng hỏng làm chậm việc, và ông đã nói với các trưởng nhóm → ngụ ý hạn nộp báo cáo sẽ được điều chỉnh (lùi lại) → (B)."}],"a":"E24-T09-80-82.mp3"},{"ns":[83,85],"script":[["","Hi, Ling. I just received a call from a group asking to reserve the tearoom for tomorrow. They would like us to decide on the entire menu for the tea party, from the tea selection to the food options. I'd like you to handle the preparations.","Chào Ling. Tôi vừa nhận được cuộc gọi của một nhóm khách muốn đặt phòng trà cho ngày mai. Họ muốn chúng ta quyết định toàn bộ thực đơn cho buổi tiệc trà, từ việc chọn trà đến các món ăn. Tôi muốn em phụ trách việc chuẩn bị."],["","I know you've never been in charge of a tea party before, but you've worked here for five months now. By the way, there will be children at the party. Please make sure some low tables and chairs are set up for them. You'll find them in the back room.","Chị biết em chưa từng phụ trách một buổi tiệc trà nào, nhưng em đã làm ở đây năm tháng rồi. À, nhân tiện, sẽ có trẻ em dự tiệc. Em nhớ kê một số bàn ghế thấp cho các bé nhé. Em sẽ tìm thấy chúng ở phòng phía sau."]],"qs":[{"n":83,"q":"What type of business does the speaker own?","qvi":"Người nói sở hữu loại hình kinh doanh nào?","opts":["A tea shop","A childcare center","A pottery studio","A party supply store"],"vi":["Quán trà","Trung tâm giữ trẻ","Xưởng làm gốm","Cửa hàng đồ dùng tiệc"],"ans":"A","xp":"Người nói: \"I just received a call from a group asking to reserve the tearoom for tomorrow\" và nhắc đến 'tea party', 'tea selection' → cô ấy sở hữu quán trà → (A)."},{"n":84,"q":"What does the speaker imply when she says, \"you've worked here for five months now\"?","qvi":"Người nói ngụ ý gì khi nói \"em đã làm ở đây năm tháng rồi\"?","opts":["The listener is capable of doing a task.","The listener should apply for a promotion.","The speaker is ready to retire.","A training period is too short."],"vi":["Người nghe có đủ khả năng làm một việc.","Người nghe nên xin thăng chức.","Người nói đã sẵn sàng nghỉ hưu.","Thời gian đào tạo quá ngắn."],"ans":"A","xp":"Câu hỏi hàm ý. Trước đó: \"I'd like you to handle the preparations. I know you've never been in charge of a tea party before, but...\" → dù chưa từng phụ trách nhưng đã làm 5 tháng → ý là em đủ khả năng làm việc này → (A)."},{"n":85,"q":"What does the speaker say is located in the back room?","qvi":"Người nói cho biết cái gì ở phòng phía sau?","opts":["Some decorations","A video projector","Some furniture","Some dishes"],"vi":["Một số đồ trang trí","Một máy chiếu video","Một số đồ nội thất","Một số bát đĩa"],"ans":"C","xp":"Người nói: \"Please make sure some low tables and chairs are set up for them. You'll find them in the back room\" → bàn ghế (tables and chairs) = đồ nội thất (furniture) → (C)."}],"a":"E24-T09-83-85.mp3"},{"ns":[86,88],"script":[["","Peak travel season is almost here. And, as everyone knows, we don't have enough baggage handlers, ground crew, or ticketing agents to handle the demand. Passengers are experiencing longer lines and flight delays. Therefore, hiring more staff is our top priority.","Mùa du lịch cao điểm sắp đến rồi. Và như mọi người đều biết, chúng ta không có đủ nhân viên bốc xếp hành lý, nhân viên mặt đất hay nhân viên bán vé để đáp ứng nhu cầu. Hành khách đang phải xếp hàng lâu hơn và gặp tình trạng chuyến bay bị hoãn. Vì vậy, tuyển thêm nhân viên là ưu tiên hàng đầu của chúng ta."],["","Now, we already have an incentive program for employees to refer friends for open positions. Please continue referring your friends to apply to work for us. And, for our current staff, we're now going to start offering complimentary meals in all employee lounges starting this month. We want you to know that you're valued and appreciated.","Hiện chúng ta đã có chương trình khuyến khích nhân viên giới thiệu bạn bè vào các vị trí đang tuyển. Mọi người hãy tiếp tục giới thiệu bạn bè ứng tuyển làm việc cho chúng ta nhé. Ngoài ra, đối với nhân viên hiện tại, bắt đầu từ tháng này chúng ta sẽ cung cấp bữa ăn miễn phí tại tất cả các phòng nghỉ nhân viên. Chúng tôi muốn mọi người biết rằng mọi người luôn được trân trọng và ghi nhận."]],"qs":[{"n":86,"q":"What industry does the speaker most likely work in?","qvi":"Người nói nhiều khả năng làm việc trong ngành nào?","opts":["Transportation","Health care","Hospitality","Entertainment"],"vi":["Vận tải","Y tế","Nhà hàng – khách sạn","Giải trí"],"ans":"A","xp":"Người nói nhắc đến \"baggage handlers, ground crew, or ticketing agents\" và \"Passengers are experiencing longer lines and flight delays\" → hãng hàng không/sân bay → ngành vận tải → (A)."},{"n":87,"q":"What does the speaker say is a priority?","qvi":"Người nói cho biết điều gì là ưu tiên?","opts":["Upgrading some equipment","Promoting an industry event","Hiring more staff","Increasing inventory"],"vi":["Nâng cấp một số thiết bị","Quảng bá một sự kiện của ngành","Tuyển thêm nhân viên","Tăng lượng hàng tồn kho"],"ans":"C","xp":"Người nói: \"Therefore, hiring more staff is our top priority\" → (C)."},{"n":88,"q":"What change does the speaker mention?","qvi":"Người nói đề cập đến thay đổi gì?","opts":["A shuttle bus will be provided.","Free meals will be available.","A work schedule will be reduced.","An additional branch has opened."],"vi":["Sẽ có xe buýt đưa đón.","Sẽ có bữa ăn miễn phí.","Lịch làm việc sẽ được rút ngắn.","Một chi nhánh mới đã khai trương."],"ans":"B","xp":"Người nói: \"we're now going to start offering complimentary meals in all employee lounges starting this month\" → 'complimentary meals' = bữa ăn miễn phí (free meals) → (B)."}],"a":"E24-T09-86-88.mp3"},{"ns":[89,91],"script":[["","Some quick announcements before we start the assembly-line machines for the day. First, I need to tell you about a new safety standard for everyone working on the factory floor. Starting immediately, rings, earrings, and jewelry of any kind will not be allowed on the floor during your shift. Sorry—I know some of you will find this regulation inconvenient.","Có vài thông báo nhanh trước khi chúng ta khởi động máy móc dây chuyền lắp ráp hôm nay. Trước tiên, tôi cần thông báo về một tiêu chuẩn an toàn mới cho tất cả những ai làm việc trong xưởng sản xuất. Kể từ bây giờ, nhẫn, hoa tai và trang sức dưới bất kỳ hình thức nào sẽ không được phép mang vào xưởng trong ca làm việc. Xin lỗi — tôi biết một số bạn sẽ thấy quy định này bất tiện."],["","As a reminder, keep your belongings safe during your shift. I recommend you put a lock on your designated locker in the break room. If you need one, I have a few in my office.","Xin nhắc lại, hãy giữ đồ đạc cá nhân của các bạn an toàn trong ca làm việc. Tôi khuyên các bạn nên khóa tủ đồ được chỉ định cho mình trong phòng nghỉ. Nếu bạn cần ổ khóa, tôi có vài cái trong văn phòng."]],"qs":[{"n":89,"q":"Where do the listeners most likely work?","qvi":"Người nghe nhiều khả năng làm việc ở đâu?","opts":["At a jewelry store","At a security company","At a factory","At a university"],"vi":["Ở cửa hàng trang sức","Ở công ty bảo vệ an ninh","Ở nhà máy","Ở trường đại học"],"ans":"C","xp":"Người nói: \"before we start the assembly-line machines for the day\" và \"everyone working on the factory floor\" → dây chuyền lắp ráp, xưởng sản xuất → nhà máy → (C). (A) là bẫy vì bài có nhắc 'jewelry'."},{"n":90,"q":"Why does the speaker apologize?","qvi":"Tại sao người nói xin lỗi?","opts":["A wait time increased.","A hiring was delayed.","A new rule may be unpopular.","Some items cannot be stored on-site."],"vi":["Thời gian chờ đợi tăng lên.","Việc tuyển dụng bị trì hoãn.","Một quy định mới có thể không được ưa chuộng.","Một số đồ không thể cất giữ tại chỗ."],"ans":"C","xp":"Người nói: \"Sorry—I know some of you will find this regulation inconvenient\" → xin lỗi vì quy định mới (cấm đeo trang sức) có thể khiến mọi người không thích → (C)."},{"n":91,"q":"What are the listeners reminded to do?","qvi":"Người nghe được nhắc làm gì?","opts":["Secure their belongings","Verify their appointment time","Provide detailed information","Arrive early"],"vi":["Giữ an toàn cho đồ đạc cá nhân","Xác nhận giờ hẹn","Cung cấp thông tin chi tiết","Đến sớm"],"ans":"A","xp":"Người nói: \"As a reminder, keep your belongings safe during your shift\" → 'keep... safe' = 'secure' (giữ an toàn) → (A)."}],"a":"E24-T09-89-91.mp3"},{"ns":[92,94],"script":[["","Good morning, all. I have a quick announcement about some staff shifts. Starting next week, everybody will see their evening hours adjusted. Since summer is ending and people are having dinner earlier, we're going to be closing at eight instead of ten P.M. on weekdays.","Chào buổi sáng mọi người. Tôi có một thông báo ngắn về ca làm việc của nhân viên. Bắt đầu từ tuần sau, giờ làm buổi tối của mọi người sẽ được điều chỉnh. Vì mùa hè sắp kết thúc và mọi người ăn tối sớm hơn, chúng ta sẽ đóng cửa lúc 8 giờ thay vì 10 giờ tối vào các ngày trong tuần."],["","It doesn't make financial sense for our kitchen to stay open late. This is a seasonal adjustment that we make every year. There's no reason for you to worry. We still have plenty of customers in the winter.","Việc bếp của chúng ta mở cửa muộn không hợp lý về mặt tài chính. Đây là sự điều chỉnh theo mùa mà năm nào chúng ta cũng làm. Mọi người không cần phải lo lắng. Vào mùa đông chúng ta vẫn có rất nhiều khách."]],"qs":[{"n":92,"q":"What is the speaker announcing?","qvi":"Người nói đang thông báo điều gì?","opts":["A security update","A menu adjustment","A mandatory uniform","A schedule change"],"vi":["Cập nhật về an ninh","Điều chỉnh thực đơn","Đồng phục bắt buộc","Thay đổi lịch làm việc"],"ans":"D","xp":"Người nói: \"Starting next week, everybody will see their evening hours adjusted\" → giờ làm buổi tối được điều chỉnh = thay đổi lịch → (D)."},{"n":93,"q":"Where do the listeners most likely work?","qvi":"Người nghe nhiều khả năng làm việc ở đâu?","opts":["At a farm","At a restaurant","At a public park","At an electronics store"],"vi":["Ở nông trại","Ở nhà hàng","Ở công viên công cộng","Ở cửa hàng điện tử"],"ans":"B","xp":"Người nói: \"people are having dinner earlier\" và \"It doesn't make financial sense for our kitchen to stay open late\" → có bếp, phục vụ bữa tối → nhà hàng → (B)."},{"n":94,"q":"What does the speaker reassure the listeners about?","qvi":"Người nói trấn an người nghe về điều gì?","opts":["They will be paid overtime.","They will receive annual bonuses.","Their paycheck mistake will be corrected.","There will still be work available."],"vi":["Họ sẽ được trả tiền làm thêm giờ.","Họ sẽ nhận thưởng hằng năm.","Lỗi trong phiếu lương của họ sẽ được sửa.","Vẫn sẽ có việc để làm."],"ans":"D","xp":"Người nói: \"There's no reason for you to worry. We still have plenty of customers in the winter.\" → mùa đông vẫn đông khách nên mọi người vẫn có việc làm → (D)."}],"a":"E24-T09-92-94.mp3"},{"ns":[95,97],"script":[["","You've reached Hayberry Farm in Millville. We're excited to announce that we're now under new management. Even with the management change, the farm will still be offering a full schedule of summer activities.","Quý khách đã gọi đến Nông trại Hayberry ở Millville. Chúng tôi rất vui được thông báo rằng nông trại hiện đã có ban quản lý mới. Dù thay đổi ban quản lý, nông trại vẫn sẽ tổ chức đầy đủ lịch hoạt động mùa hè."],["","We're now accepting registrations for our popular cooking class! This class focuses on making delicious meals with fresh ingredients. You can find more information on our Web site. Also, be aware that our Western Road entrance is closed until the end of June because of road construction. Visitors should use our entrance on Anderson Road.","Hiện chúng tôi đang nhận đăng ký cho lớp nấu ăn rất được yêu thích! Lớp học tập trung vào việc nấu những bữa ăn ngon từ nguyên liệu tươi. Quý khách có thể xem thêm thông tin trên trang web của chúng tôi. Ngoài ra, xin lưu ý rằng lối vào đường Western sẽ đóng cửa đến cuối tháng Sáu do thi công đường. Khách tham quan vui lòng sử dụng lối vào trên đường Anderson."]],"qs":[{"n":95,"q":"According to the speaker, what has changed at the farm?","qvi":"Theo người nói, điều gì đã thay đổi ở nông trại?","opts":["The prices","The type of crops","The management","The hours of operation"],"vi":["Giá cả","Loại cây trồng","Ban quản lý","Giờ hoạt động"],"ans":"C","xp":"Người nói: \"We're excited to announce that we're now under new management\" → ban quản lý đã thay đổi → (C)."},{"n":96,"q":"Look at the graphic. When does the mentioned activity take place?","qvi":"Hãy nhìn bảng. Hoạt động được nhắc đến diễn ra khi nào?","opts":["On June 2","On June 9","On June 16","On June 23"],"vi":["Vào ngày 2 tháng 6","Vào ngày 9 tháng 6","Vào ngày 16 tháng 6","Vào ngày 23 tháng 6"],"ans":"A","xp":"Người nói: \"We're now accepting registrations for our popular cooking class!\" → hoạt động được nhắc là lớp nấu ăn; trong bảng, Cooking Class diễn ra ngày June 2 → (A)."},{"n":97,"q":"What are visitors to the business advised to do?","qvi":"Khách đến nông trại được khuyên làm gì?","opts":["Come on weekdays","Park in a designated area","Bring reusable containers","Use an alternate entrance"],"vi":["Đến vào ngày thường","Đỗ xe ở khu vực quy định","Mang theo hộp đựng tái sử dụng","Sử dụng lối vào thay thế"],"ans":"D","xp":"Người nói: \"our Western Road entrance is closed... Visitors should use our entrance on Anderson Road\" → dùng lối vào khác thay cho lối bị đóng = 'alternate entrance' → (D)."}],"a":"E24-T09-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","This is Yun Kang with local information for Greenville residents. Your taxes have increased significantly this year—I know you've noticed, and you want to know what your money's being spent on! The city is going ahead with four major projects to improve your library, parkland, firehouse, and streets. Work on the firehouse is currently in progress, while the other projects will be started in coming months.","Tôi là Yun Kang với bản tin địa phương dành cho cư dân Greenville. Năm nay thuế của quý vị đã tăng đáng kể — tôi biết quý vị đã nhận ra, và quý vị muốn biết tiền của mình đang được chi vào việc gì! Thành phố đang tiến hành bốn dự án lớn để cải thiện thư viện, công viên, trạm cứu hỏa và đường phố. Công trình ở trạm cứu hỏa hiện đang được thực hiện, còn các dự án khác sẽ bắt đầu trong những tháng tới."],["","Remember: the election for mayor is approaching, and your vote affects what projects become future priorities in the community. The candidates are holding a debate in our studios this Wednesday, and you're all encouraged to attend.","Xin nhớ rằng: cuộc bầu cử thị trưởng đang đến gần, và lá phiếu của quý vị ảnh hưởng đến việc dự án nào sẽ trở thành ưu tiên của cộng đồng trong tương lai. Các ứng cử viên sẽ tổ chức một cuộc tranh luận tại trường quay của chúng tôi vào thứ Tư này, và mời tất cả quý vị đến tham dự."]],"qs":[{"n":98,"q":"What does the speaker say residents have noticed?","qvi":"Người nói cho biết cư dân đã nhận thấy điều gì?","opts":["Rising fuel prices","Limited housing options","Traffic congestion","Increased taxes"],"vi":["Giá nhiên liệu tăng","Ít lựa chọn nhà ở","Tắc nghẽn giao thông","Thuế tăng"],"ans":"D","xp":"Người nói: \"Your taxes have increased significantly this year—I know you've noticed\" → cư dân đã nhận thấy thuế tăng → (D)."},{"n":99,"q":"Look at the graphic. What is the cost of the project currently being worked on?","qvi":"Hãy nhìn bản đồ. Dự án đang được thực hiện có chi phí bao nhiêu?","opts":["$425,000","$375,000","$328,000","$460,000"],"vi":["425.000 đô la","375.000 đô la","328.000 đô la","460.000 đô la"],"ans":"C","xp":"Người nói: \"Work on the firehouse is currently in progress\" → dự án đang làm là trạm cứu hỏa; trên bản đồ, Firehouse Upgrades có chi phí $328,000 → (C)."},{"n":100,"q":"What is scheduled for Wednesday?","qvi":"Sự kiện gì được lên lịch vào thứ Tư?","opts":["A fund-raiser","A festival","An election","A debate"],"vi":["Buổi gây quỹ","Lễ hội","Cuộc bầu cử","Cuộc tranh luận"],"ans":"D","xp":"Người nói: \"The candidates are holding a debate in our studios this Wednesday\" → thứ Tư có cuộc tranh luận → (D). (C) là bẫy: bầu cử chỉ 'đang đến gần', không phải vào thứ Tư."}],"a":"E24-T09-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Mr. Liu is known for negotiating employee disputes -------.","opts":["calm","calmly","calmest","calmness"],"ans":"B","xp":"Từ loại: câu đã đầy đủ 'negotiating employee disputes' (động từ + tân ngữ) → chỗ trống cần trạng từ bổ nghĩa cho động từ 'negotiating'. (B) calmly = một cách bình tĩnh → chọn (B). (A) calm là tính từ/động từ, (C) calmest là tính từ so sánh nhất, (D) calmness là danh từ.\nDịch: Ông Liu được biết đến với việc đàm phán các tranh chấp của nhân viên một cách bình tĩnh."},{"n":102,"q":"The city is accepting proposals for the redesign of Oshida Public Park ------- January 25.","opts":["when","until","a few","whether"],"ans":"B","xp":"Giới từ: sau chỗ trống là mốc thời gian 'January 25' (danh từ) → cần giới từ. 'until January 25' = cho đến ngày 25 tháng 1 (việc nhận đề xuất kéo dài đến hạn đó) → chọn (B). (A) when và (D) whether là liên từ, cần theo sau là mệnh đề; (C) a few = một vài, đi với danh từ số nhiều.\nDịch: Thành phố đang nhận các đề xuất thiết kế lại Công viên Công cộng Oshida cho đến ngày 25 tháng 1."},{"n":103,"q":"Sales ------- maintain client files and provide logistical support.","opts":["assists","assisted","assisting","assistants"],"ans":"D","xp":"Từ loại: 'maintain' và 'provide' là động từ chính → 'Sales -------' là chủ ngữ, cần danh từ. 'Sales assistants' = nhân viên hỗ trợ bán hàng (danh từ ghép, số nhiều hợp với động từ 'maintain') → chọn (D). (A) assists là động từ chia số ít, (B) assisted là quá khứ/phân từ II, (C) assisting là V-ing.\nDịch: Các nhân viên hỗ trợ bán hàng quản lý hồ sơ khách hàng và cung cấp hỗ trợ hậu cần."},{"n":104,"q":"Tonight at Harbor Falls Library, writer Delroy Greene will be ------- stories from his childhood in Jamaica.","opts":["dividing","sharing","using","awarding"],"ans":"B","xp":"Từ vựng: tân ngữ là 'stories from his childhood' (những câu chuyện thời thơ ấu) → 'sharing stories' = chia sẻ câu chuyện là kết hợp tự nhiên → chọn (B). (A) dividing = chia ra, (C) using = sử dụng, (D) awarding = trao thưởng – không hợp nghĩa.\nDịch: Tối nay tại Thư viện Harbor Falls, nhà văn Delroy Greene sẽ chia sẻ những câu chuyện thời thơ ấu của ông ở Jamaica."},{"n":105,"q":"Mr. Kam has invited all staff members to attend ------- retirement party.","opts":["he","his","him","himself"],"ans":"B","xp":"Đại từ: sau chỗ trống là cụm danh từ 'retirement party' → cần tính từ sở hữu 'his' (của ông ấy) → chọn (B). (A) he là đại từ chủ ngữ, (C) him là đại từ tân ngữ, (D) himself là đại từ phản thân – không đứng trước danh từ.\nDịch: Ông Kam đã mời tất cả nhân viên đến dự tiệc nghỉ hưu của ông."},{"n":106,"q":"Stanley Point Theater in downtown Detroit will produce four plays and three ------- next season.","opts":["actors","audiences","tickets","musicals"],"ans":"D","xp":"Từ vựng: nhà hát sẽ 'produce' (dàn dựng) 'four plays and three -------' → cần một loại tác phẩm sân khấu song song với 'plays' (kịch). (D) musicals = vở nhạc kịch → chọn (D). (A) actors = diễn viên, (B) audiences = khán giả, (C) tickets = vé – không thể 'dàn dựng'.\nDịch: Nhà hát Stanley Point ở trung tâm Detroit sẽ dàn dựng bốn vở kịch và ba vở nhạc kịch vào mùa diễn tới."},{"n":107,"q":"There is enough money ------- in the budget to cover travel expenses.","opts":["remains","remainder","remained","remaining"],"ans":"D","xp":"Từ loại/rút gọn mệnh đề: câu đã có động từ chính 'is' → chỗ trống bổ nghĩa cho 'money'. 'money remaining' = tiền còn lại (rút gọn của 'money that remains', dùng V-ing vì mang nghĩa chủ động) → chọn (D). (A) remains là động từ chia, (B) remainder là danh từ, (C) remained là quá khứ/phân từ II – 'remain' là nội động từ nên không dùng dạng bị động.\nDịch: Ngân sách còn đủ tiền để chi trả chi phí đi lại."},{"n":108,"q":"Romm Industries staff trained nine new associates who were hired ------- the same day.","opts":["as","into","on","once"],"ans":"C","xp":"Giới từ: trước 'day' (ngày) dùng giới từ 'on' → 'on the same day' = vào cùng một ngày → chọn (C). (A) as = như/khi, (B) into = vào trong, (D) once = một lần/ngay khi – không đi với 'the same day'.\nDịch: Nhân viên của Romm Industries đã đào tạo chín nhân viên mới được tuyển vào cùng một ngày."},{"n":109,"q":"Taylor Kanagawa wrote several books on effective team management ------- his 40-year career at Sapp Publishers Ltd.","opts":["between","while","beside","during"],"ans":"D","xp":"Giới từ/liên từ: sau chỗ trống là cụm danh từ 'his 40-year career' (khoảng thời gian) → cần giới từ chỉ thời gian 'during' = trong suốt → chọn (D). (B) while là liên từ, phải theo sau là mệnh đề; (A) between = giữa (hai thứ); (C) beside = bên cạnh (vị trí).\nDịch: Taylor Kanagawa đã viết vài cuốn sách về quản lý nhóm hiệu quả trong suốt 40 năm sự nghiệp tại Sapp Publishers Ltd."},{"n":110,"q":"The community clinic project is designed to improve health ------- in isolated areas.","opts":["outcomes","reasons","corrections","grades"],"ans":"A","xp":"Từ vựng: 'improve health -------' = cải thiện ... sức khỏe. 'health outcomes' = kết quả/tình trạng sức khỏe (cụm thường gặp) → chọn (A). (B) reasons = lý do, (C) corrections = sự sửa chữa, (D) grades = điểm số/cấp bậc – không hợp nghĩa.\nDịch: Dự án phòng khám cộng đồng được thiết kế nhằm cải thiện tình trạng sức khỏe ở những vùng hẻo lánh."},{"n":111,"q":"Jingshen Airlines announced that it will be hiring 200 ------- employees next year.","opts":["add","adding","additional","additionally"],"ans":"C","xp":"Từ loại: chỗ trống đứng giữa số lượng '200' và danh từ 'employees' → cần tính từ. (C) additional = thêm, bổ sung → chọn (C). (A) add là động từ, (B) adding là V-ing, (D) additionally là trạng từ.\nDịch: Hãng hàng không Jingshen thông báo sẽ tuyển thêm 200 nhân viên vào năm tới."},{"n":112,"q":"The customer was impressed by how ------- Mr. Schmid operated the complicated machinery.","opts":["skillfully","primarily","obviously","richly"],"ans":"A","xp":"Từ vựng (trạng từ): 'how ------- Mr. Schmid operated the complicated machinery' = ông Schmid vận hành cỗ máy phức tạp ... như thế nào. Khách hàng 'impressed' (ấn tượng) → (A) skillfully = một cách khéo léo, thành thạo → chọn (A). (B) primarily = chủ yếu, (C) obviously = rõ ràng, (D) richly = phong phú, giàu có.\nDịch: Khách hàng rất ấn tượng với việc ông Schmid vận hành cỗ máy phức tạp một cách thành thạo."},{"n":113,"q":"Staff are invited to participate in a ------- of social events during the first week of May.","opts":["series","status","theory","guest"],"ans":"A","xp":"Từ vựng: cấu trúc 'a series of + danh từ số nhiều' = một loạt ... → 'a series of social events' = một loạt sự kiện giao lưu → chọn (A). (B) status = tình trạng, (C) theory = lý thuyết, (D) guest = khách – không hợp nghĩa.\nDịch: Nhân viên được mời tham gia một loạt sự kiện giao lưu trong tuần đầu tiên của tháng Năm."},{"n":114,"q":"The contract states that Solcus Corporation will be ------- for any costs resulting from work delays.","opts":["accountable","manageable","knowledgeable","flexible"],"ans":"A","xp":"Từ vựng: cấu trúc 'be accountable for something' = chịu trách nhiệm về điều gì → công ty chịu trách nhiệm về mọi chi phí phát sinh do chậm trễ công việc → chọn (A). (B) manageable = có thể quản lý được, (C) knowledgeable = am hiểu, (D) flexible = linh hoạt.\nDịch: Hợp đồng quy định rằng Tập đoàn Solcus sẽ chịu trách nhiệm cho mọi chi phí phát sinh do chậm trễ công việc."},{"n":115,"q":"Author Minh Phan's latest novel was ------- influenced by Vietnamese folk stories.","opts":["heavy","heavily","heaviest","heavier"],"ans":"B","xp":"Từ loại: chỗ trống nằm giữa 'was' và phân từ II 'influenced' (câu bị động) → cần trạng từ bổ nghĩa cho động từ. (B) heavily = nhiều, sâu sắc → chọn (B). (A) heavy là tính từ, (C) heaviest và (D) heavier là tính từ so sánh.\nDịch: Cuốn tiểu thuyết mới nhất của tác giả Minh Phan chịu ảnh hưởng sâu sắc từ truyện dân gian Việt Nam."},{"n":116,"q":"Tourists are expected to flock to the Sorachi Discovery Museum when it opens ------- in Mikasa, Hokkaido.","opts":["soon","as","almost","initial"],"ans":"A","xp":"Trạng từ: 'when it opens -------' → cần trạng từ bổ nghĩa cho động từ 'opens'. (A) soon = sắp, sớm → 'khi bảo tàng sắp khai trương' → chọn (A). (B) as là liên từ/giới từ, (C) almost = gần như (thường đứng trước động từ/tính từ, không hợp nghĩa), (D) initial là tính từ.\nDịch: Du khách được dự đoán sẽ đổ về Bảo tàng Khám phá Sorachi khi bảo tàng sắp khai trương ở Mikasa, Hokkaido."},{"n":117,"q":"The factory floor is divided into four ------- sections: one for each stage of product assembly.","opts":["previous","eligible","distinct","installed"],"ans":"C","xp":"Từ vựng (tính từ): xưởng được chia thành bốn khu '-------', mỗi khu cho một công đoạn lắp ráp → (C) distinct = riêng biệt, tách biệt → chọn (C). (A) previous = trước đó, (B) eligible = đủ điều kiện, (D) installed = được lắp đặt – không hợp nghĩa.\nDịch: Xưởng sản xuất được chia thành bốn khu riêng biệt: mỗi khu dành cho một công đoạn lắp ráp sản phẩm."},{"n":118,"q":"Handouts for the afternoon seminar must be prepared ------- the lunch break.","opts":["down","beside","before","off"],"ans":"C","xp":"Giới từ: tài liệu cho buổi hội thảo buổi chiều phải được chuẩn bị ... giờ nghỉ trưa → về thời gian hợp lý là 'before' = trước → chọn (C). (A) down = xuống, (B) beside = bên cạnh, (D) off = rời khỏi – không chỉ thời gian.\nDịch: Tài liệu phát tay cho buổi hội thảo chiều nay phải được chuẩn bị trước giờ nghỉ trưa."},{"n":119,"q":"Chat Mobile will determine, based on end-of-the-year sales numbers, ------- the company will open any additional stores.","opts":["whether","who","since","that"],"ans":"A","xp":"Liên từ: chỗ trống mở đầu mệnh đề danh từ làm tân ngữ của 'determine' (quyết định). Nghĩa 'quyết định xem có mở thêm cửa hàng nào hay không' → (A) whether = liệu ... hay không → chọn (A). Từ 'any' cũng gợi ý câu mang nghĩa nghi vấn. (B) who cần mệnh đề thiếu chủ ngữ, (C) since = vì/từ khi, (D) that không mang nghĩa 'có ... hay không'.\nDịch: Dựa trên số liệu doanh số cuối năm, Chat Mobile sẽ quyết định liệu công ty có mở thêm cửa hàng nào hay không."},{"n":120,"q":"The red line will ------- only express stops from Finn Street to Boone Street on weekends.","opts":["made","makes","make","making"],"ans":"C","xp":"Dạng động từ: sau động từ khuyết thiếu 'will' luôn dùng động từ nguyên mẫu → (C) make → chọn (C). 'make stops' = dừng đỗ. (A) made, (B) makes, (D) making đều không đứng sau 'will'.\nDịch: Vào cuối tuần, tuyến đỏ sẽ chỉ dừng ở các trạm tốc hành từ phố Finn đến phố Boone."},{"n":121,"q":"The company's latest video game, Hunting for Treasure, has been praised ------- by reviewers.","opts":["enthusiastically","enthusiastic","enthusiasm","enthusiast"],"ans":"A","xp":"Từ loại: câu bị động 'has been praised' đã đủ → chỗ trống cần trạng từ bổ nghĩa cho động từ 'praised'. (A) enthusiastically = một cách nhiệt tình → chọn (A). (B) enthusiastic là tính từ, (C) enthusiasm và (D) enthusiast là danh từ.\nDịch: Trò chơi điện tử mới nhất của công ty, Hunting for Treasure, đã được các nhà phê bình khen ngợi nhiệt liệt."},{"n":122,"q":"During the off-season, the Great Mountain Amusement Park operates on ------- hours.","opts":["reduced","employed","slow","busy"],"ans":"A","xp":"Từ vựng: vào mùa thấp điểm, công viên giải trí hoạt động theo giờ ... → 'reduced hours' = giờ hoạt động rút ngắn → chọn (A). (B) employed = được thuê, (C) slow = chậm, (D) busy = bận rộn (trái nghĩa với mùa thấp điểm).\nDịch: Vào mùa thấp điểm, Công viên Giải trí Great Mountain hoạt động với số giờ rút ngắn."},{"n":123,"q":"The construction project will ------- 30 residential units and 10 commercial spaces.","opts":["overall","first","about","include"],"ans":"D","xp":"Từ loại: sau 'will' cần động từ nguyên mẫu, và phía sau có tân ngữ '30 residential units...' → (D) include = bao gồm → chọn (D). (A) overall là tính từ/trạng từ, (B) first là số thứ tự/trạng từ, (C) about là giới từ/trạng từ.\nDịch: Dự án xây dựng sẽ bao gồm 30 căn hộ để ở và 10 mặt bằng thương mại."},{"n":124,"q":"Ms. Pham's employment contract cannot be finalized ------- her starting salary is still being negotiated.","opts":["once","because","after","until"],"ans":"B","xp":"Liên từ: hai mệnh đề có quan hệ nguyên nhân – kết quả: hợp đồng chưa thể hoàn tất VÌ mức lương khởi điểm vẫn đang được đàm phán → (B) because → chọn (B). (A) once = một khi, (C) after = sau khi, (D) until = cho đến khi – không hợp với 'is still being negotiated'.\nDịch: Hợp đồng lao động của cô Pham chưa thể hoàn tất vì mức lương khởi điểm của cô vẫn đang được đàm phán."},{"n":125,"q":"Office supplies are available in our resources cabinet for ------- who needs them.","opts":["anyone","whichever","such","more"],"ans":"A","xp":"Đại từ: sau giới từ 'for' cần đại từ chỉ người, và theo sau là 'who needs' (động từ số ít) → (A) anyone = bất kỳ ai → chọn (A). (B) whichever = bất cứ cái nào (chỉ vật, lựa chọn), (C) such = như vậy, (D) more = nhiều hơn.\nDịch: Văn phòng phẩm có sẵn trong tủ tài nguyên của chúng tôi cho bất kỳ ai cần dùng."},{"n":126,"q":"Through its network of local agents, new housing start-up Philocenia intends to ------- the rental sector.","opts":["exercise","indicate","participate","revolutionize"],"ans":"D","xp":"Từ vựng: công ty khởi nghiệp mới định ... lĩnh vực cho thuê nhà → (D) revolutionize = cách mạng hóa, làm thay đổi hoàn toàn → chọn (D). (A) exercise = rèn luyện/thực hiện (quyền), (B) indicate = chỉ ra, (C) participate là nội động từ, phải dùng 'participate in'.\nDịch: Thông qua mạng lưới đại lý địa phương, công ty khởi nghiệp nhà ở mới Philocenia dự định cách mạng hóa lĩnh vực cho thuê."},{"n":127,"q":"Rapid Books has the payroll solutions every company needs, allowing users ------- invoices in three easy steps.","opts":["sent","have sent","sending","to send"],"ans":"D","xp":"Cấu trúc: 'allow somebody to do something' = cho phép ai làm gì → 'allowing users to send invoices' → chọn (D). (A) sent, (B) have sent, (C) sending không đúng cấu trúc sau 'allow + tân ngữ'.\nDịch: Rapid Books có các giải pháp tính lương mà mọi công ty cần, cho phép người dùng gửi hóa đơn chỉ với ba bước đơn giản."},{"n":128,"q":"Epky Electronics will open eight additional retail stores ------- the next two years.","opts":["above","behind","about","within"],"ans":"D","xp":"Giới từ: trước khoảng thời gian 'the next two years' dùng 'within' = trong vòng → chọn (D). (A) above = phía trên, (B) behind = phía sau, (C) about = về/khoảng – không hợp nghĩa.\nDịch: Epky Electronics sẽ mở thêm tám cửa hàng bán lẻ trong vòng hai năm tới."},{"n":129,"q":"The three-day workshop focuses on the public speaking ------- that are central to delivering memorable presentations.","opts":["strategies","strategized","strategically","strategic"],"ans":"A","xp":"Từ loại: sau 'the public speaking' cần danh từ làm trung tâm (danh từ ghép 'public speaking strategies'); động từ 'are' số nhiều cho thấy danh từ số nhiều → (A) strategies = các chiến lược → chọn (A). (B) strategized là động từ quá khứ, (C) strategically là trạng từ, (D) strategic là tính từ.\nDịch: Buổi hội thảo ba ngày tập trung vào các chiến lược nói trước công chúng – điều cốt lõi để có những bài thuyết trình đáng nhớ."},{"n":130,"q":"Critics agree that the movie An Unusual Introduction ------- combines computer-generated images and live action.","opts":["seamlessly","collectively","factually","distantly"],"ans":"A","xp":"Từ vựng (trạng từ): bộ phim ... kết hợp hình ảnh do máy tính tạo ra và cảnh quay người thật → (A) seamlessly = một cách liền mạch, mượt mà → chọn (A). (B) collectively = cùng nhau, tập thể; (C) factually = đúng sự thật; (D) distantly = xa cách.\nDịch: Các nhà phê bình đồng ý rằng bộ phim An Unusual Introduction kết hợp một cách liền mạch hình ảnh kỹ xảo máy tính và cảnh quay người thật."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following notice.","passage":"<h3>Sky Air First Pass</h3><p>Thank you for flying Sky Air First with <span class=\"blank\" data-n=\"131\">-------</span>. We hope you enjoy your flight.</p><p>You can take advantage of our best prices on future flights <span class=\"blank\" data-n=\"132\">-------</span> purchasing a Sky Air First Pass.</p><p>For a <span class=\"blank\" data-n=\"133\">-------</span> annual fee, you will get special discounts, seat upgrades, and the use of our exclusive travelers' lounge. <span class=\"blank\" data-n=\"134\">-------</span>. Ask your flight attendant for more information and an application.</p>","vi":"Thẻ Sky Air First Pass\n\nCảm ơn quý khách đã bay cùng chúng tôi – Sky Air First. Chúng tôi hy vọng quý khách tận hưởng chuyến bay.\n\nQuý khách có thể tận dụng mức giá tốt nhất của chúng tôi cho các chuyến bay sau này bằng cách mua thẻ Sky Air First Pass.\n\nVới mức phí thường niên thấp, quý khách sẽ được giảm giá đặc biệt, nâng hạng ghế và sử dụng phòng chờ dành riêng cho hành khách của chúng tôi. Quý khách cũng sẽ được lên máy bay ưu tiên. Hãy hỏi tiếp viên để biết thêm thông tin và nhận đơn đăng ký.","qs":[{"n":131,"opts":["them","theirs","us","ours"],"ans":"C","xp":"Đại từ: sau giới từ 'with' cần đại từ tân ngữ. Thông báo do hãng Sky Air First viết ('We hope you enjoy your flight') → 'flying ... with us' = bay cùng chúng tôi → chọn (C). (A) them = họ (tân ngữ) – sai người; (B) theirs và (D) ours là đại từ sở hữu (của họ / của chúng tôi), không hợp nghĩa.\nDịch: Cảm ơn quý khách đã bay cùng chúng tôi – Sky Air First."},{"n":132,"opts":["at","on","by","to"],"ans":"C","xp":"Giới từ: 'by + V-ing' = bằng cách làm gì → 'by purchasing a Sky Air First Pass' = bằng cách mua thẻ → chọn (C). (A) at, (B) on, (D) to không diễn tả phương thức/cách thức trong ngữ cảnh này.\nDịch: Quý khách có thể tận dụng mức giá tốt nhất cho các chuyến bay sau này bằng cách mua thẻ Sky Air First Pass."},{"n":133,"opts":["lowers","low","lowly","lowest"],"ans":"B","xp":"Từ loại: chỗ trống nằm giữa mạo từ 'a' và cụm danh từ 'annual fee' → cần tính từ. (B) low = thấp → 'a low annual fee' = mức phí hằng năm thấp → chọn (B). (A) lowers là động từ; (C) lowly = thấp kém, hèn mọn (nghĩa không hợp); (D) lowest là so sánh nhất, phải đi với 'the', không đi với 'a'.\nDịch: Với mức phí thường niên thấp, quý khách sẽ được giảm giá đặc biệt, nâng hạng ghế…"},{"n":134,"opts":["We hope you will fly Sky Air First again.","You will also get priority boarding.","Please find your seat immediately.","The flight delay will be minimal."],"ans":"B","xp":"Điền câu: câu trước liệt kê quyền lợi của thẻ: 'special discounts, seat upgrades, and the use of our exclusive travelers' lounge'. Câu (B) 'Quý khách cũng sẽ được lên máy bay ưu tiên' dùng 'also' để bổ sung thêm một quyền lợi nữa → nối tiếp tự nhiên, rồi câu sau mời hỏi tiếp viên để biết thêm thông tin. (A) là lời chào kết, không hợp vị trí giữa đoạn; (C) và (D) không liên quan đến thẻ thành viên.\n(A) Chúng tôi hy vọng quý khách sẽ lại bay cùng Sky Air First.\n(B) Quý khách cũng sẽ được lên máy bay ưu tiên.\n(C) Vui lòng tìm chỗ ngồi của quý khách ngay.\n(D) Chuyến bay sẽ chỉ bị trễ rất ít."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following article.","passage":"<h3>CJOK Radio Show Welcomes New Staff</h3><p>QUEENSVILLE (7 July)—Local radio station CJOK announced Katherine Dees as the new producer of the popular show <i>Out and About in Queensville</i>. Ms. Dees is now <span class=\"blank\" data-n=\"135\">-------</span> for coordinating schedules, booking guests for the show, and managing media relations.</p><p><span class=\"blank\" data-n=\"136\">-------</span>, the station hired sound editor Virginia Thacker and production assistant Reggie Dietrich to support Ms. Dees in her new role. <span class=\"blank\" data-n=\"137\">-------</span>.</p><p><i>Out and About in Queensville</i>, which has been airing for 30 years, is performed live weekly from September to May in the Orpheum Theater in downtown Queensville. The show <span class=\"blank\" data-n=\"138\">-------</span> musical guests, writers, and storytellers for an hour of weekly programming.</p>","vi":"Chương trình phát thanh CJOK chào đón nhân sự mới\n\nQUEENSVILLE (7 tháng 7) – Đài phát thanh địa phương CJOK đã công bố Katherine Dees là nhà sản xuất mới của chương trình nổi tiếng Out and About in Queensville. Cô Dees hiện chịu trách nhiệm điều phối lịch trình, mời khách cho chương trình và quản lý quan hệ truyền thông.\n\nNgoài ra, đài đã tuyển biên tập viên âm thanh Virginia Thacker và trợ lý sản xuất Reggie Dietrich để hỗ trợ cô Dees trong vai trò mới. Những nhân sự mới này được tuyển sau khi nhà sản xuất Ed Evans nghỉ hưu.\n\nOut and About in Queensville, chương trình đã phát sóng được 30 năm, được biểu diễn trực tiếp hằng tuần từ tháng Chín đến tháng Năm tại Nhà hát Orpheum ở trung tâm Queensville. Chương trình có sự góp mặt của các khách mời âm nhạc, nhà văn và người kể chuyện trong một giờ phát sóng mỗi tuần.","qs":[{"n":135,"opts":["responsive","responsibly","responding","responsible"],"ans":"D","xp":"Từ loại/cấu trúc: sau 'is now' cần tính từ làm bổ ngữ, và theo sau là 'for' → cấu trúc 'be responsible for + V-ing' = chịu trách nhiệm về việc gì → chọn (D). (A) responsive = phản hồi nhanh (đi với 'to'), (B) responsibly là trạng từ, (C) responding là V-ing ('responding for' sai).\nDịch: Cô Dees hiện chịu trách nhiệm điều phối lịch trình, mời khách cho chương trình và quản lý quan hệ truyền thông."},{"n":136,"opts":["Even so","In fact","For example","In addition"],"ans":"D","xp":"Trạng từ liên kết: đoạn 1 nói đài bổ nhiệm nhà sản xuất mới; câu này nói đài còn tuyển thêm biên tập viên âm thanh và trợ lý sản xuất → thông tin bổ sung → (D) In addition = Ngoài ra → chọn (D). (A) Even so = Dù vậy (tương phản), (B) In fact = Thực tế là (nhấn mạnh/làm rõ), (C) For example = Ví dụ – không hợp quan hệ ý.\nDịch: Ngoài ra, đài đã tuyển biên tập viên âm thanh Virginia Thacker và trợ lý sản xuất Reggie Dietrich để hỗ trợ cô Dees trong vai trò mới."},{"n":137,"opts":["CJOK was founded 60 years ago.","These recent hires follow the retirement of producer Ed Evans.","Ms. Dees was born and raised in Cedarburg.","CJOK has more than one popular show in its lineup."],"ans":"B","xp":"Điền câu: câu trước vừa nhắc đến các nhân sự mới (Katherine Dees, Virginia Thacker, Reggie Dietrich). Câu (B) dùng 'These recent hires' (những người mới được tuyển này) để chỉ lại họ và giải thích lý do tuyển: nhà sản xuất cũ Ed Evans nghỉ hưu → liên kết chặt chẽ. (A) nói về năm thành lập đài, (C) nói về quê của cô Dees, (D) nói về các chương trình khác – đều lạc khỏi ý đoạn về nhân sự mới.\n(A) CJOK được thành lập cách đây 60 năm.\n(B) Những nhân sự mới này được tuyển sau khi nhà sản xuất Ed Evans nghỉ hưu.\n(C) Cô Dees sinh ra và lớn lên ở Cedarburg.\n(D) CJOK có nhiều hơn một chương trình nổi tiếng trong lịch phát sóng."},{"n":138,"opts":["gives","marks","features","holds"],"ans":"C","xp":"Từ vựng: chủ ngữ 'The show', tân ngữ 'musical guests, writers, and storytellers' → 'feature' = có sự góp mặt/giới thiệu (khách mời, nghệ sĩ) → chọn (C). (A) gives = cho, đưa; (B) marks = đánh dấu; (D) holds = tổ chức/cầm, giữ – không đi với 'khách mời' theo nghĩa này.\nDịch: Chương trình có sự góp mặt của các khách mời âm nhạc, nhà văn và người kể chuyện trong một giờ phát sóng mỗi tuần."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Sandra Barga &lt;sbarga97@hjmail.ca&gt;</p><p><b>From:</b> Artie Romanche &lt;service@northwestbags.ca&gt;</p><p><b>Date:</b> 12 July</p><p><b>Subject:</b> Order number 71280</p></div><p>Dear Ms. Barga:</p><p>We received your recent order asking for your name to be stitched on a Klamath Kool handbag. We are, <span class=\"blank\" data-n=\"139\">-------</span>, eager to complete your order. Unfortunately, our seamstress who fulfills personalisation requirements will be on leave for the next three days. We wanted to let you know that her <span class=\"blank\" data-n=\"140\">-------</span> will cause a delay in shipping your bag.</p><p><span class=\"blank\" data-n=\"141\">-------</span> for the wait, we would like to offer you a 10 percent discount on your current order. Or, if you prefer, you can opt for free personalisation on your next order. <span class=\"blank\" data-n=\"142\">-------</span>. At Northwest Bags, we strive for 100 percent customer satisfaction!</p><p>Sincerely,<br>Artie Romanche<br>Customer Service Representative, Northwest Bags</p>","vi":"Người nhận: Sandra Barga <sbarga97@hjmail.ca>\nNgười gửi: Artie Romanche <service@northwestbags.ca>\nNgày: 12 tháng 7\nTiêu đề: Đơn hàng số 71280\n\nKính gửi cô Barga,\n\nChúng tôi đã nhận được đơn hàng gần đây của cô yêu cầu thêu tên cô lên một chiếc túi xách Klamath Kool. Tất nhiên, chúng tôi rất mong muốn hoàn thành đơn hàng của cô. Tuy nhiên, rất tiếc là thợ may phụ trách các yêu cầu cá nhân hóa của chúng tôi sẽ nghỉ phép trong ba ngày tới. Chúng tôi muốn thông báo để cô biết rằng sự vắng mặt của cô ấy sẽ khiến việc giao túi bị chậm trễ.\n\nĐể bù đắp cho việc phải chờ đợi, chúng tôi xin tặng cô mức giảm giá 10% cho đơn hàng hiện tại. Hoặc, nếu muốn, cô có thể chọn được cá nhân hóa miễn phí cho đơn hàng tiếp theo. Quyền lựa chọn là của cô. Tại Northwest Bags, chúng tôi luôn nỗ lực để khách hàng hài lòng 100%!\n\nTrân trọng,\nArtie Romanche\nNhân viên Chăm sóc Khách hàng, Northwest Bags","qs":[{"n":139,"opts":["still","besides","of course","nevertheless"],"ans":"C","xp":"Trạng từ liên kết: 'We are, -------, eager to complete your order' – câu khẳng định thiện chí của cửa hàng sau khi nhận đơn → (C) of course = tất nhiên → chọn (C). (A) still = vẫn (không đặt giữa hai dấu phẩy theo cách này với nghĩa hợp lý), (B) besides = ngoài ra, (D) nevertheless = tuy nhiên – không có ý tương phản/bổ sung với câu trước.\nDịch: Tất nhiên, chúng tôi rất mong muốn hoàn thành đơn hàng của cô."},{"n":140,"opts":["absence","arrival","request","investigation"],"ans":"A","xp":"Từ vựng: câu trước nói thợ may 'will be on leave for the next three days' (nghỉ phép ba ngày) → 'her absence' = sự vắng mặt của cô ấy sẽ làm chậm việc giao túi → chọn (A). (B) arrival = sự đến nơi, (C) request = yêu cầu, (D) investigation = cuộc điều tra – không hợp ngữ cảnh.\nDịch: Chúng tôi muốn thông báo để cô biết rằng sự vắng mặt của cô ấy sẽ khiến việc giao túi bị chậm trễ."},{"n":141,"opts":["Compensated","To compensate","For compensating","It is compensation"],"ans":"B","xp":"Cấu trúc: đầu câu, trước mệnh đề chính 'we would like to offer you...', cần cụm chỉ mục đích → 'To + V' = để làm gì → 'To compensate for the wait' = Để bù đắp cho việc chờ đợi → chọn (B). (A) Compensated mang nghĩa bị động (được bù đắp) – sai chủ thể; (C) 'For compensating' không dùng để chỉ mục đích đầu câu như vậy; (D) 'It is compensation' là một mệnh đề, tạo ra câu sai ngữ pháp.\nDịch: Để bù đắp cho việc phải chờ đợi, chúng tôi xin tặng cô mức giảm giá 10% cho đơn hàng hiện tại."},{"n":142,"opts":["The choice is yours.","We appreciate your review.","The bag will look great with your initials on it.","We are the only local retailer offering custom services."],"ans":"A","xp":"Điền câu: hai câu trước đưa ra hai lựa chọn: giảm 10% cho đơn hiện tại 'Or, if you prefer' cá nhân hóa miễn phí cho đơn sau → (A) 'Quyền lựa chọn là của cô' kết luận tự nhiên cho việc đưa ra hai phương án. (B) khách chưa viết đánh giá; (C) khách yêu cầu thêu tên (name), không phải chữ viết tắt, và không liên quan đến ý bồi thường; (D) không ăn nhập với ý đoạn.\n(A) Quyền lựa chọn là của cô.\n(B) Chúng tôi trân trọng bài đánh giá của cô.\n(C) Chiếc túi sẽ trông rất đẹp với chữ viết tắt tên của cô trên đó.\n(D) Chúng tôi là nhà bán lẻ địa phương duy nhất cung cấp dịch vụ làm theo yêu cầu."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following article.","passage":"<h3>Sehelec Announces Wind-Solar Hybrid Project</h3><p>MUMBAI (15 March)—Sehelec Ltd. announced it will begin construction on a 500-megawatt wind-solar hybrid power <span class=\"blank\" data-n=\"143\">-------</span> outside of Bangalore, India. <span class=\"blank\" data-n=\"144\">-------</span>. Sehelec expects to begin operations within 24 months, and it will sell the power to Indian energy giant Novaseon Industries.</p><p>\"Our contract with Novaseon to provide <span class=\"blank\" data-n=\"145\">-------</span> power moves us closer to our long-term corporate goal,\" said Sumit Varma, CEO of Sehelec. \"Our objective is to achieve a capacity of 20 gigawatts within five years. Doing so will make us one of India's largest green power companies. And that, in turn, will help the country <span class=\"blank\" data-n=\"146\">-------</span> its carbon-reduction target.\"</p>","vi":"Sehelec công bố dự án điện lai gió – mặt trời\n\nMUMBAI (15 tháng 3) – Công ty Sehelec Ltd. thông báo sẽ bắt đầu xây dựng một nhà máy điện lai gió – mặt trời công suất 500 megawatt ở ngoại ô Bangalore, Ấn Độ. Cơ sở này sẽ bao gồm kết hợp các tấm pin mặt trời và tua-bin gió. Sehelec dự kiến bắt đầu vận hành trong vòng 24 tháng và sẽ bán điện cho tập đoàn năng lượng khổng lồ của Ấn Độ là Novaseon Industries.\n\n\"Hợp đồng cung cấp điện tái tạo với Novaseon đưa chúng tôi đến gần hơn mục tiêu dài hạn của công ty,\" ông Sumit Varma, Giám đốc điều hành của Sehelec, cho biết. \"Mục tiêu của chúng tôi là đạt công suất 20 gigawatt trong vòng năm năm. Làm được điều đó sẽ đưa chúng tôi trở thành một trong những công ty điện xanh lớn nhất Ấn Độ. Và đến lượt mình, điều đó sẽ giúp đất nước đạt được mục tiêu giảm phát thải carbon.\"","qs":[{"n":143,"opts":["plant","planter","planting","planted"],"ans":"A","xp":"Từ vựng/từ loại: sau 'a 500-megawatt wind-solar hybrid power' cần danh từ đếm được số ít → 'power plant' = nhà máy điện → chọn (A). (B) planter = chậu cây/người trồng cây, (C) planting = việc trồng cây, (D) planted là quá khứ/phân từ II.\nDịch: Sehelec Ltd. thông báo sẽ bắt đầu xây dựng một nhà máy điện lai gió – mặt trời công suất 500 megawatt ở ngoại ô Bangalore, Ấn Độ."},{"n":144,"opts":["Windy conditions can cause damage to tall buildings.","The facility will consist of a mix of solar panels and wind turbines.","Electric vehicles have fewer emissions than other vehicles have.","The pace of upgrades to India's power grid slowed slightly this year."],"ans":"B","xp":"Điền câu: câu trước giới thiệu 'a ... wind-solar hybrid power plant' (nhà máy điện lai gió – mặt trời). Câu (B) dùng 'The facility' (cơ sở này) để chỉ lại nhà máy và giải thích 'hybrid' nghĩa là kết hợp tấm pin mặt trời và tua-bin gió → liên kết hợp lý. (A) nói về thiệt hại do gió, (C) về xe điện, (D) về tiến độ nâng cấp lưới điện – đều lạc đề.\n(A) Điều kiện gió mạnh có thể gây hư hại cho các tòa nhà cao tầng.\n(B) Cơ sở này sẽ gồm kết hợp các tấm pin mặt trời và tua-bin gió.\n(C) Xe điện thải ra ít khí thải hơn các loại xe khác.\n(D) Tốc độ nâng cấp lưới điện của Ấn Độ chậm lại một chút trong năm nay."},{"n":145,"opts":["renew","renewers","renewable","to renew"],"ans":"C","xp":"Từ loại: chỗ trống đứng trước danh từ 'power' → cần tính từ. (C) renewable = tái tạo → 'renewable power' = điện/năng lượng tái tạo, phù hợp với dự án điện gió – mặt trời → chọn (C). (A) renew và (D) to renew là động từ, (B) renewers là danh từ chỉ người.\nDịch: \"Hợp đồng cung cấp điện tái tạo với Novaseon đưa chúng tôi đến gần hơn mục tiêu dài hạn của công ty.\""},{"n":146,"opts":["understand","explain","block","reach"],"ans":"D","xp":"Từ vựng: 'help the country ------- its carbon-reduction target' → đi với 'target' (mục tiêu) dùng 'reach' = đạt được → chọn (D). Cấu trúc 'help + O + V nguyên mẫu'. (A) understand = hiểu, (B) explain = giải thích, (C) block = ngăn chặn – không hợp nghĩa.\nDịch: Và đến lượt mình, điều đó sẽ giúp đất nước đạt được mục tiêu giảm phát thải carbon."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following menu.","passages":["<h3>Carina's Café Lunch Specials</h3><p><b>Monday through Friday from 11:00 A.M. to 3:00 P.M.</b></p><p>For only $8, combine the soup of the day with one of the following items:</p><p><b>Turkey Sandwich</b> – Turkey, avocado, tomato, lettuce, and mayonnaise on wheat bread</p><p><b>Vegetable Panini</b> – Sourdough bread filled with tomato, cucumber, spinach, and mayonnaise, then grilled</p><p><b>Mushroom Chicken Cavatappi</b> – Chicken in a mushroom, celery, and onion sauce, served over S-shaped pasta</p><p><b>Vegetable Wrap</b> – Fresh tomato, cucumber, and carrots with hummus (made with our secret recipe) on flatbread</p>"],"vi":"Món đặc biệt bữa trưa của Carina's Café\n\nTừ thứ Hai đến thứ Sáu, từ 11:00 sáng đến 3:00 chiều\n\nChỉ với 8 đô la, kết hợp súp của ngày với một trong các món sau:\n\nBánh mì kẹp gà tây – Gà tây, bơ, cà chua, xà lách và sốt mayonnaise trên bánh mì lúa mì\n\nPanini rau củ – Bánh mì bột chua kẹp cà chua, dưa leo, rau bina và sốt mayonnaise, sau đó nướng\n\nNui xoắn gà sốt nấm – Thịt gà trong sốt nấm, cần tây và hành, ăn kèm nui hình chữ S\n\nBánh cuộn rau củ – Cà chua tươi, dưa leo và cà rốt cùng sốt hummus (làm theo công thức bí mật của chúng tôi) cuộn trong bánh mì dẹt","qs":[{"n":147,"q":"What does each lunch special include?","qvi":"Mỗi suất trưa đặc biệt bao gồm gì?","opts":["A soup","Carrots","Tomatoes","A beverage"],"ans":"A","xp":"Câu hỏi chi tiết. \"For only $8, combine the soup of the day with one of the following items\" → mọi suất đều có súp của ngày kèm một món → (A). (B) cà rốt chỉ có trong Vegetable Wrap; (C) cà chua không có trong món Mushroom Chicken Cavatappi; (D) đồ uống không được nhắc đến.\n(A) Một phần súp\n(B) Cà rốt\n(C) Cà chua\n(D) Một đồ uống"},{"n":148,"q":"What item contains an ingredient that is only available from Carina's Café?","qvi":"Món nào có một nguyên liệu chỉ có ở Carina's Café?","opts":["Turkey sandwich","Vegetable panini","Mushroom chicken cavatappi","Vegetable wrap"],"ans":"D","xp":"Câu hỏi suy luận. Vegetable Wrap có \"hummus (made with our secret recipe)\" → sốt hummus làm theo công thức bí mật của quán, nên chỉ có ở Carina's Café → (D). Các món khác chỉ dùng nguyên liệu thông thường.\n(A) Bánh mì kẹp gà tây\n(B) Panini rau củ\n(C) Nui xoắn gà sốt nấm\n(D) Bánh cuộn rau củ"}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following advertisement.","passages":["<h3>Certified Aqua Instructor Workshop</h3><p>This workshop helps fitness professionals become certified aqua instructors by demonstrating how to design challenging and effective aquatic classes. Join instructor Deshonte Smith for a full-day course to learn a sequence of pool-based workouts that will motivate your students. Mr. Smith started his journey to instructor certification by taking classes at Valley Floor Fitness. He is also a professor at Wilkinson University.</p><p>The workshop costs $99 and will be held at Valley Floor Fitness in Missoula on August 27 from 9 a.m. to 5 p.m. For more information and to register, e-mail Maya Cramer at certification@valleyfloorfitness.com.</p>"],"vi":"Hội thảo Huấn luyện viên Thể dục dưới nước có Chứng chỉ\n\nHội thảo này giúp các chuyên gia thể hình trở thành huấn luyện viên thể dục dưới nước có chứng chỉ bằng cách hướng dẫn cách thiết kế các lớp học dưới nước vừa thử thách vừa hiệu quả. Hãy tham gia cùng huấn luyện viên Deshonte Smith trong khóa học kéo dài cả ngày để học một chuỗi bài tập dưới hồ bơi giúp tạo động lực cho học viên của bạn. Ông Smith bắt đầu hành trình lấy chứng chỉ huấn luyện viên bằng việc tham gia các lớp học tại Valley Floor Fitness. Ông cũng là giáo sư tại Đại học Wilkinson.\n\nHội thảo có giá 99 đô la và sẽ được tổ chức tại Valley Floor Fitness ở Missoula vào ngày 27 tháng 8 từ 9 giờ sáng đến 5 giờ chiều. Để biết thêm thông tin và đăng ký, hãy gửi e-mail cho Maya Cramer theo địa chỉ certification@valleyfloorfitness.com.","qs":[{"n":149,"q":"The word \"design\" in paragraph 1, line 2, is closest in meaning to","qvi":"Từ \"design\" ở đoạn 1, dòng 2 gần nghĩa nhất với","opts":["find","create","draw","name"],"ans":"B","xp":"Câu hỏi đồng nghĩa. \"how to design challenging and effective aquatic classes\" = cách thiết kế/xây dựng các lớp học dưới nước → design ở đây nghĩa là tạo ra, xây dựng → create (B). (C) draw là \"vẽ\" (nghĩa đen của thiết kế hình ảnh) không hợp với \"classes\".\n(A) tìm thấy\n(B) tạo ra, xây dựng\n(C) vẽ\n(D) đặt tên"},{"n":150,"q":"What is indicated about the workshop?","qvi":"Điều gì được nêu về hội thảo?","opts":["It will be held at a pool at Wilkinson University.","It is being offered on two different dates.","It is available at a discounted rate in August.","It will be taught by a former student of Valley Floor Fitness."],"ans":"D","xp":"Câu hỏi chi tiết. \"Mr. Smith started his journey to instructor certification by taking classes at Valley Floor Fitness\" → người dạy từng là học viên của Valley Floor Fitness → (D). (A) sai: tổ chức \"at Valley Floor Fitness in Missoula\"; (B) sai: chỉ một ngày \"August 27\"; (C) không nhắc đến giảm giá, chỉ nói \"costs $99\".\n(A) Hội thảo sẽ được tổ chức tại một hồ bơi ở Đại học Wilkinson.\n(B) Hội thảo được tổ chức vào hai ngày khác nhau.\n(C) Hội thảo có giá ưu đãi trong tháng 8.\n(D) Hội thảo sẽ do một cựu học viên của Valley Floor Fitness giảng dạy."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Hyun-Jun Cho (3:27 P.M.)</b></p><p>I'm scheduled to work the front desk on Saturday from 7 A.M. to 3 P.M. A friend of mine is coming to town then, and he's only going to be here for one day. I was wondering if I could switch shifts with you. I can work on Sunday.</p></div><div class=\"msg\"><p><b>Stephanie Duchemin (3:29 P.M.)</b></p><p>Saturday is good for me. I hope you don't have a Sunday like last week. It was so busy. All the doctors attending the medical conference were checking in at the front desk.</p></div><div class=\"msg\"><p><b>Hyun-Jun Cho (3:31 P.M.)</b></p><p>And I heard that all the accountants from the other conference were also at the front desk reviewing their room charges at the same time!</p></div><div class=\"msg\"><p><b>Stephanie Duchemin (3:32 P.M.)</b></p><p>The lobby was certainly bustling.</p></div><div class=\"msg\"><p><b>Hyun-Jun Cho (3:34 P.M.)</b></p><p>Thank you for helping me out. I haven't seen my friend Kai since we graduated from university.</p></div>"],"vi":"Hyun-Jun Cho (3:27 chiều): Mình có lịch trực quầy lễ tân vào thứ Bảy từ 7 giờ sáng đến 3 giờ chiều. Một người bạn của mình sẽ đến thành phố lúc đó, và cậu ấy chỉ ở đây một ngày. Mình đang tự hỏi liệu mình có thể đổi ca với bạn không. Mình có thể làm vào Chủ nhật.\n\nStephanie Duchemin (3:29 chiều): Thứ Bảy thì mình làm được. Hy vọng bạn không gặp một ngày Chủ nhật như tuần trước. Hôm đó bận kinh khủng. Tất cả các bác sĩ tham dự hội nghị y khoa đều làm thủ tục nhận phòng ở quầy lễ tân.\n\nHyun-Jun Cho (3:31 chiều): Và mình nghe nói tất cả các kế toán viên từ hội nghị kia cũng có mặt ở quầy lễ tân để kiểm tra tiền phòng của họ cùng lúc!\n\nStephanie Duchemin (3:32 chiều): Sảnh chắc chắn là nhộn nhịp lắm.\n\nHyun-Jun Cho (3:34 chiều): Cảm ơn bạn đã giúp mình. Mình chưa gặp lại bạn Kai kể từ khi tụi mình tốt nghiệp đại học.","qs":[{"n":151,"q":"At 3:29 P.M., what does Ms. Duchemin most likely mean when she writes, \"Saturday is good for me\"?","qvi":"Lúc 3:29 chiều, khi cô Duchemin viết \"Saturday is good for me\", nhiều khả năng cô ấy muốn nói gì?","opts":["She prefers to work morning shifts.","She is able to do a favor for Mr. Cho.","She will attend a conference.","She would like to meet Mr. Cho's friend."],"ans":"B","xp":"Câu hỏi hàm ý. Anh Cho hỏi \"I was wondering if I could switch shifts with you. I can work on Sunday.\" → cô Duchemin trả lời \"Saturday is good for me\" nghĩa là cô đồng ý làm thay ca thứ Bảy, tức là giúp anh Cho → (B). Anh Cho cũng cảm ơn: \"Thank you for helping me out.\"\n(A) Cô ấy thích làm ca sáng hơn.\n(B) Cô ấy có thể giúp anh Cho một việc.\n(C) Cô ấy sẽ tham dự một hội nghị.\n(D) Cô ấy muốn gặp bạn của anh Cho."},{"n":152,"q":"Where most likely do Mr. Cho and Ms. Duchemin work?","qvi":"Anh Cho và cô Duchemin nhiều khả năng làm việc ở đâu?","opts":["At a hotel","At a university","At a medical center","At an accounting firm"],"ans":"A","xp":"Câu hỏi suy luận. \"work the front desk\" (trực quầy lễ tân), khách dự hội nghị \"checking in at the front desk\" (làm thủ tục nhận phòng), \"reviewing their room charges\" (kiểm tra tiền phòng), \"The lobby\" (sảnh) → nơi làm việc là khách sạn → (A). Bác sĩ và kế toán là khách dự hội nghị, không phải nơi họ làm.\n(A) Ở một khách sạn\n(B) Ở một trường đại học\n(C) Ở một trung tâm y tế\n(D) Ở một công ty kế toán"}]},{"ns":[153,154],"head":"Questions 153-154 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Madalena Navas &lt;mnavas@cordovacreations.com&gt;</p><p><b>From:</b> Hugo Jones &lt;hkjones@sunmail.com&gt;</p><p><b>Date:</b> April 2</p><p><b>Subject:</b> Thank you</p></div><p>Dear Ms. Navas,</p><p>I enjoyed speaking with you about the associate manager position last week, and as I mentioned, I am very excited about the possibility of working with you at Cordova Creations. I wanted to let you know that I have received a job offer from another company, and I have to respond to that hiring manager soon. I realize it has only been a few days since my interview, but if it is at all possible for you to update me on the status of my application before the end of the week, that would be very helpful. I have long admired Cordova Creations and would really like to be a part of it. I am hoping to hear positive news from you.</p><p>Thank you,</p><p>Hugo Jones</p>"],"vi":"Người nhận: Madalena Navas <mnavas@cordovacreations.com>\nNgười gửi: Hugo Jones <hkjones@sunmail.com>\nNgày: 2 tháng 4\nTiêu đề: Cảm ơn\n\nKính gửi cô Navas,\n\nTôi rất vui khi được trao đổi với cô về vị trí phó quản lý vào tuần trước, và như tôi đã nói, tôi rất hào hứng với khả năng được làm việc cùng cô tại Cordova Creations. Tôi muốn báo để cô biết rằng tôi đã nhận được lời mời làm việc từ một công ty khác, và tôi phải sớm trả lời người quản lý tuyển dụng bên đó. Tôi hiểu rằng mới chỉ vài ngày trôi qua kể từ buổi phỏng vấn của tôi, nhưng nếu có thể, cô vui lòng cập nhật cho tôi về tình trạng hồ sơ ứng tuyển của tôi trước cuối tuần này thì sẽ rất hữu ích. Tôi đã ngưỡng mộ Cordova Creations từ lâu và thực sự muốn trở thành một phần của công ty. Tôi mong nhận được tin vui từ cô.\n\nXin cảm ơn,\n\nHugo Jones","qs":[{"n":153,"q":"What does Mr. Jones indicate in his e-mail?","qvi":"Anh Jones cho biết điều gì trong e-mail?","opts":["He used to work with Ms. Navas.","He is an associate manager.","Another company wishes to hire him.","His interview has been scheduled for next week."],"ans":"C","xp":"Câu hỏi chi tiết. \"I have received a job offer from another company\" → một công ty khác muốn tuyển anh ấy → (C). (A) sai: anh chỉ mong \"the possibility of working with you\"; (B) sai: anh đang ứng tuyển vào vị trí \"associate manager\", chưa phải là phó quản lý; (D) sai: buổi phỏng vấn đã diễn ra (\"it has only been a few days since my interview\").\n(A) Anh ấy từng làm việc với cô Navas.\n(B) Anh ấy là phó quản lý.\n(C) Một công ty khác muốn tuyển anh ấy.\n(D) Buổi phỏng vấn của anh ấy được lên lịch vào tuần sau."},{"n":154,"q":"What does Mr. Jones want to know by the end of the week?","qvi":"Anh Jones muốn biết điều gì trước cuối tuần?","opts":["Whether an important decision has been made yet","Whether Ms. Navas is available for a meeting","Whether Ms. Navas would like to apply for a new position","Whether the company will expand its product offerings"],"ans":"A","xp":"Câu hỏi chi tiết. \"if it is at all possible for you to update me on the status of my application before the end of the week\" → anh muốn biết tình trạng hồ sơ, tức là công ty đã quyết định tuyển hay chưa → (A). \"the status of my application\" được diễn đạt lại thành \"an important decision\".\n(A) Liệu một quyết định quan trọng đã được đưa ra chưa\n(B) Liệu cô Navas có rảnh để gặp mặt không\n(C) Liệu cô Navas có muốn ứng tuyển vào một vị trí mới không\n(D) Liệu công ty có mở rộng các dòng sản phẩm không"}]},{"ns":[155,157],"head":"Questions 155-157 refer to the following article.","passages":["<h3>Hibiscus Supply to Run Its Own Container Ship</h3><p>BUSAN (15 October)—As international shipping continues to increase, companies that transport goods between continents have found themselves competing for expensive space on container ships. <span class=\"pos\">[1]</span> Delays in getting goods to factories and into stores have become more common. <span class=\"pos\">[2]</span></p><p>As one of the biggest exporters of home building supplies in the country, Hibiscus Supply is particularly vulnerable to these issues. <span class=\"pos\">[3]</span> To avoid potential shipping problems, Hibiscus Supply has decided to operate its own container ship to export products overseas. <span class=\"pos\">[4]</span></p><p>According to Hibiscus Supply president James Koh, operating the company's own ship should improve efficiency at ports and decrease overall shipping costs. Says Mr. Koh, \"The cost to ship with freight companies has doubled in the past year. By shipping our products ourselves, we'll be able to avoid passing shipping-related price increases on to our customers.\"</p>"],"vi":"Hibiscus Supply sẽ vận hành tàu container riêng\n\nBUSAN (15 tháng 10) — Khi vận tải biển quốc tế tiếp tục gia tăng, các công ty vận chuyển hàng hóa giữa các châu lục phải cạnh tranh để giành chỗ trên tàu container vốn rất đắt đỏ. Việc chậm trễ trong đưa hàng đến nhà máy và vào cửa hàng đã trở nên phổ biến hơn.\n\nLà một trong những nhà xuất khẩu vật liệu xây nhà lớn nhất cả nước, Hibiscus Supply đặc biệt dễ bị ảnh hưởng bởi những vấn đề này. Để tránh các rắc rối vận chuyển có thể xảy ra, Hibiscus Supply đã quyết định vận hành tàu container riêng để xuất khẩu sản phẩm ra nước ngoài.\n\nTheo chủ tịch Hibiscus Supply, ông James Koh, việc vận hành tàu riêng của công ty sẽ giúp cải thiện hiệu quả tại các cảng và giảm tổng chi phí vận chuyển. Ông Koh nói: \"Chi phí vận chuyển qua các công ty vận tải hàng hóa đã tăng gấp đôi trong năm qua. Bằng cách tự vận chuyển sản phẩm, chúng tôi sẽ tránh được việc đẩy các khoản tăng giá liên quan đến vận chuyển sang cho khách hàng.\"","qs":[{"n":155,"q":"What products does Hibiscus Supply most likely sell?","qvi":"Hibiscus Supply nhiều khả năng bán sản phẩm gì?","opts":["Construction materials","Pillows and sheets","Wholesale food items","Spare automobile parts"],"ans":"A","xp":"Câu hỏi suy luận. \"one of the biggest exporters of home building supplies\" → vật tư xây nhà = vật liệu xây dựng → (A). \"home building supplies\" được diễn đạt lại thành \"construction materials\".\n(A) Vật liệu xây dựng\n(B) Gối và ga trải giường\n(C) Thực phẩm bán sỉ\n(D) Phụ tùng ô tô"},{"n":156,"q":"Why does Hibiscus Supply want to operate its own container ship?","qvi":"Tại sao Hibiscus Supply muốn vận hành tàu container riêng?","opts":["To provide shipping services to other companies","To ship its products quickly and cheaply","To deliver its products to unusual locations","To ship more goods than most freight companies can handle"],"ans":"B","xp":"Câu hỏi chi tiết. \"operating the company's own ship should improve efficiency at ports and decrease overall shipping costs\" và mục đích \"To avoid potential shipping problems\" (tránh chậm trễ) → vận chuyển nhanh hơn và rẻ hơn → (B). \"improve efficiency\" ≈ quickly, \"decrease costs\" ≈ cheaply.\n(A) Để cung cấp dịch vụ vận chuyển cho các công ty khác\n(B) Để vận chuyển sản phẩm của mình nhanh và rẻ\n(C) Để giao sản phẩm đến những nơi khác thường\n(D) Để vận chuyển nhiều hàng hơn mức hầu hết công ty vận tải có thể đảm nhận"},{"n":157,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"The newly acquired ship is scheduled to begin running later this month.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Con tàu mới mua dự kiến sẽ bắt đầu hoạt động vào cuối tháng này.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"D","xp":"Câu hỏi điền câu. Câu cần điền nói về \"The newly acquired ship\" (con tàu mới mua) → phải đứng sau câu đầu tiên nhắc đến con tàu: \"Hibiscus Supply has decided to operate its own container ship to export products overseas.\" Vị trí [4] ngay sau câu này → (D). Ở [1], [2], [3] chưa hề nhắc đến việc công ty có tàu riêng.\n(A) Vị trí [1]\n(B) Vị trí [2]\n(C) Vị trí [3]\n(D) Vị trí [4]"}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following memo.","passages":["<h3>MEMO</h3><div class=\"hdr\"><p><b>To:</b> All Accounting Staff</p><p><b>From:</b> Jennifer Snow, Senior Manager</p><p><b>Date:</b> January 8</p><p><b>Subject:</b> Pedro Allende</p></div><p>Please join me in congratulating Pedro Allende as he prepares to enter his new role as a full-time administrative assistant in our accounting department. Mr. Allende, a part-time clerk in our mail room, completed a certificate program in computer support at Lander Vocational Institute last month. He was first hired by our company as a delivery driver, a role he held for two years before transferring to the mail room.</p><p>Mr. Allende's first day in the accounting department will be Monday, January 11. We all wish him well!</p>"],"vi":"BẢN GHI NHỚ\n\nGửi: Toàn thể nhân viên phòng Kế toán\nTừ: Jennifer Snow, Quản lý cấp cao\nNgày: 8 tháng 1\nTiêu đề: Pedro Allende\n\nMời mọi người cùng tôi chúc mừng anh Pedro Allende khi anh chuẩn bị đảm nhận vai trò mới là trợ lý hành chính toàn thời gian tại phòng kế toán của chúng ta. Anh Allende, một nhân viên bán thời gian ở phòng thư tín của chúng ta, đã hoàn thành chương trình chứng chỉ về hỗ trợ máy tính tại Học viện Dạy nghề Lander vào tháng trước. Ban đầu anh được công ty tuyển làm tài xế giao hàng, vị trí anh đảm nhận trong hai năm trước khi chuyển sang phòng thư tín.\n\nNgày làm việc đầu tiên của anh Allende tại phòng kế toán sẽ là thứ Hai, ngày 11 tháng 1. Tất cả chúng ta chúc anh mọi điều tốt đẹp!","qs":[{"n":158,"q":"Why did Ms. Snow send the memo?","qvi":"Tại sao cô Snow gửi bản ghi nhớ?","opts":["To invite employees to an office party","To announce a change to an employee's job","To inform employees about a reduction in work hours","To request employee feedback on a departmental policy"],"ans":"B","xp":"Câu hỏi mục đích. \"Please join me in congratulating Pedro Allende as he prepares to enter his new role as a full-time administrative assistant in our accounting department\" → thông báo anh Allende chuyển sang công việc mới → (B).\n(A) Để mời nhân viên dự tiệc văn phòng\n(B) Để thông báo sự thay đổi công việc của một nhân viên\n(C) Để thông báo cho nhân viên về việc giảm giờ làm\n(D) Để xin ý kiến nhân viên về một chính sách của phòng ban"},{"n":159,"q":"The word \"prepares\" in paragraph 1, line 1, is closest in meaning to","qvi":"Từ \"prepares\" ở đoạn 1, dòng 1 gần nghĩa nhất với","opts":["assembles","returns","reaches out","gets ready"],"ans":"D","xp":"Câu hỏi đồng nghĩa. \"as he prepares to enter his new role\" = khi anh ấy chuẩn bị bước vào vai trò mới → prepares to = gets ready to (sẵn sàng/chuẩn bị) → (D). (A) assembles là \"lắp ráp, tập hợp\" – không hợp ngữ cảnh.\n(A) lắp ráp, tập hợp\n(B) quay lại\n(C) liên hệ, tiếp cận\n(D) sẵn sàng, chuẩn bị"},{"n":160,"q":"What is indicated about Mr. Allende?","qvi":"Điều gì được nêu về anh Allende?","opts":["He currently works as a delivery driver.","He recently completed a training program.","He previously assisted Ms. Snow in a different department.","He will begin working part-time next week."],"ans":"B","xp":"Câu hỏi chi tiết. \"completed a certificate program in computer support at Lander Vocational Institute last month\" → vừa hoàn thành một chương trình đào tạo → (B). (A) sai: anh từng làm tài xế giao hàng, hiện là \"a part-time clerk in our mail room\"; (C) không nhắc đến; (D) sai: anh sẽ làm \"full-time\" (toàn thời gian).\n(A) Anh ấy hiện đang làm tài xế giao hàng.\n(B) Anh ấy gần đây đã hoàn thành một chương trình đào tạo.\n(C) Anh ấy trước đây từng hỗ trợ cô Snow ở một phòng ban khác.\n(D) Anh ấy sẽ bắt đầu làm bán thời gian vào tuần tới."}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following advertisement.","passages":["<h3>Help Wanted: Machinist</h3><p>Camerley Corp. of Napier, New Zealand, has an opening for an experienced machinist to work in our 15,000-square-metre fabrication plant, which produces custom tools and machine parts for a variety of industries. Requirements for the position include:</p><ul><li>Ability to collaborate with engineers to fabricate tools and machine parts</li><li>Familiarity with specialised equipment</li><li>Skill with doing precision work based on technical drawings</li><li>Comfort working with metal and various other materials, such as wood and plastics</li><li>Ability to work both independently and as part of a team</li></ul><p>To apply, please send CV and two references to jobs@camerleycorp.co.nz.</p>"],"vi":"Tuyển dụng: Thợ cơ khí\n\nCông ty Camerley Corp. ở Napier, New Zealand, đang tuyển một thợ cơ khí có kinh nghiệm làm việc tại xưởng chế tạo rộng 15.000 mét vuông của chúng tôi, nơi sản xuất dụng cụ và linh kiện máy theo yêu cầu cho nhiều ngành công nghiệp. Yêu cầu cho vị trí này gồm:\n\n• Có khả năng phối hợp với kỹ sư để chế tạo dụng cụ và linh kiện máy\n• Quen thuộc với thiết bị chuyên dụng\n• Có kỹ năng làm các công việc đòi hỏi độ chính xác dựa trên bản vẽ kỹ thuật\n• Thoải mái khi làm việc với kim loại và nhiều vật liệu khác như gỗ và nhựa\n• Có khả năng làm việc độc lập lẫn làm việc nhóm\n\nĐể ứng tuyển, vui lòng gửi CV và hai thư giới thiệu đến jobs@camerleycorp.co.nz.","qs":[{"n":161,"q":"What type of business placed the advertisement?","qvi":"Loại hình doanh nghiệp nào đã đăng quảng cáo?","opts":["A land developer","A car-repair shop","A factory","A hardware store"],"ans":"C","xp":"Câu hỏi suy luận. \"our 15,000-square-metre fabrication plant, which produces custom tools and machine parts\" → xưởng/nhà máy sản xuất dụng cụ và linh kiện máy → (C). \"fabrication plant\" được diễn đạt lại thành \"a factory\".\n(A) Một công ty phát triển đất đai\n(B) Một tiệm sửa xe ô tô\n(C) Một nhà máy\n(D) Một cửa hàng đồ kim khí"},{"n":162,"q":"What material is NOT specified in the advertisement?","qvi":"Vật liệu nào KHÔNG được nêu trong quảng cáo?","opts":["Metal","Glass","Wood","Plastic"],"ans":"B","xp":"Câu hỏi NOT. \"Comfort working with metal and various other materials, such as wood and plastics\" → có metal (A), wood (C), plastics (D). Glass (thủy tinh) không được nhắc đến → (B).\n(A) Kim loại\n(B) Thủy tinh\n(C) Gỗ\n(D) Nhựa"},{"n":163,"q":"What is listed as a requirement for the job?","qvi":"Điều gì được liệt kê là yêu cầu của công việc?","opts":["Training in business-to-business sales","A university degree in engineering","Experience creating technical drawings","The ability to work alone and with others"],"ans":"D","xp":"Câu hỏi chi tiết. \"Ability to work both independently and as part of a team\" → làm việc một mình (independently = alone) và với người khác (as part of a team = with others) → (D). (B) chỉ nói \"collaborate with engineers\", không yêu cầu bằng kỹ sư; (C) chỉ yêu cầu làm việc \"based on technical drawings\" (dựa trên bản vẽ), không phải tạo ra bản vẽ.\n(A) Được đào tạo về bán hàng giữa doanh nghiệp với doanh nghiệp\n(B) Bằng đại học ngành kỹ thuật\n(C) Kinh nghiệm tạo bản vẽ kỹ thuật\n(D) Khả năng làm việc một mình và với người khác"}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Lanie McGinnis (7:16 A.M.)</b></p><p>Good morning, Kelly and Matthieu. I removed the Funfair preregistration signs from the park entrances, but I think I forgot one at the north gate. Could one of you check to see if it is still there?</p></div><div class=\"msg\"><p><b>Kelly Sen (7:18 A.M.)</b></p><p>Hi, Lanie. I rode my bike to the park earlier this morning to help put pamphlets and other materials on the welcome table in the main tent. But I could head over to that entrance now since there are other volunteers here who can finish up.</p></div><div class=\"msg\"><p><b>Lanie McGinnis (7:19 A.M.)</b></p><p>That would be great, since I'm going to be on the other side of the park at the south entrance for a while. I'm meeting some representatives from the city parks department.</p></div><div class=\"msg\"><p><b>Matthieu Herman (7:21 A.M.)</b></p><p>I've got it, Kelly. I just arrived at the north entrance and will take down the sign we hung here. Lanie, what would you like me to do with it?</p></div><div class=\"msg\"><p><b>Lanie McGinnis (7:22 A.M.)</b></p><p>Perfect! Can you put it with the others behind the welcome table in the main tent? I will pick them up later today. We can change the dates and use them again next year.</p></div><div class=\"msg\"><p><b>Matthieu Herman (7:23 A.M.)</b></p><p>Will do. Here's to a successful fair!</p></div>"],"vi":"Lanie McGinnis (7:16 sáng): Chào buổi sáng Kelly và Matthieu. Mình đã gỡ các biển báo đăng ký trước của Funfair ở các lối vào công viên, nhưng hình như mình quên một cái ở cổng phía bắc. Một trong hai bạn có thể kiểm tra xem nó còn ở đó không?\n\nKelly Sen (7:18 sáng): Chào Lanie. Sáng sớm nay mình đã đạp xe đến công viên để giúp đặt tờ rơi và các tài liệu khác lên bàn đón tiếp trong lều chính. Nhưng mình có thể qua lối vào đó ngay bây giờ vì ở đây có các tình nguyện viên khác có thể làm nốt.\n\nLanie McGinnis (7:19 sáng): Vậy thì tốt quá, vì mình sẽ ở phía bên kia công viên, tại lối vào phía nam một lúc. Mình sẽ gặp vài đại diện từ sở công viên thành phố.\n\nMatthieu Herman (7:21 sáng): Để mình lo, Kelly. Mình vừa đến lối vào phía bắc và sẽ gỡ tấm biển tụi mình treo ở đây. Lanie, bạn muốn mình làm gì với nó?\n\nLanie McGinnis (7:22 sáng): Tuyệt! Bạn có thể để nó cùng với mấy cái kia phía sau bàn đón tiếp trong lều chính được không? Mình sẽ lấy chúng sau trong hôm nay. Tụi mình có thể đổi ngày và dùng lại vào năm sau.\n\nMatthieu Herman (7:23 sáng): Được. Chúc hội chợ thành công!","qs":[{"n":164,"q":"What is probably true about the writers?","qvi":"Điều gì có lẽ đúng về những người nhắn tin?","opts":["They are registering people for a bike-to-work program.","They are coordinating a public event.","They work for a city parks department.","They are members of a club that walks in a park."],"ans":"B","xp":"Câu hỏi suy luận. Họ gỡ \"the Funfair preregistration signs\", chuẩn bị \"the welcome table in the main tent\", nhắc đến \"other volunteers\" và kết thúc bằng \"Here's to a successful fair!\" → họ đang tổ chức/điều phối một hội chợ công cộng → (B). (C) sai: họ chỉ gặp \"representatives from the city parks department\"; (A) chỉ có chi tiết Kelly đạp xe đến công viên.\n(A) Họ đang đăng ký cho mọi người tham gia chương trình đạp xe đi làm.\n(B) Họ đang điều phối một sự kiện công cộng.\n(C) Họ làm việc cho sở công viên thành phố.\n(D) Họ là thành viên của một câu lạc bộ đi bộ trong công viên."},{"n":165,"q":"What was Ms. Sen doing?","qvi":"Cô Sen đã đang làm gì?","opts":["Erecting a tent","Designing pamphlets","Placing items on the welcome table","Attaching signs to the park entrance"],"ans":"C","xp":"Câu hỏi chi tiết. \"I rode my bike to the park earlier this morning to help put pamphlets and other materials on the welcome table in the main tent\" → đặt đồ lên bàn đón tiếp → (C). \"put pamphlets and other materials\" = \"placing items\". (B) sai: cô đặt tờ rơi chứ không thiết kế.\n(A) Dựng lều\n(B) Thiết kế tờ rơi\n(C) Đặt đồ lên bàn đón tiếp\n(D) Gắn biển báo ở lối vào công viên"},{"n":166,"q":"At 7:21 A.M., what does Mr. Herman mean when he writes, \"I've got it, Kelly\"?","qvi":"Lúc 7:21 sáng, khi anh Herman viết \"I've got it, Kelly\", anh ấy muốn nói gì?","opts":["He has already taken down a sign.","He will perform a task requested by Ms. McGinnis.","He will return unused materials to the office.","He realizes that Ms. Sen does not need help."],"ans":"B","xp":"Câu hỏi hàm ý. Cô McGinnis nhờ \"Could one of you check to see if it is still there?\" (biển ở cổng bắc); Kelly định đi. Anh Herman nói \"I've got it, Kelly. I just arrived at the north entrance and will take down the sign\" → ý là \"để tôi lo việc đó\", anh sẽ làm việc cô McGinnis nhờ thay cho Kelly → (B). (A) sai: anh \"will take down\" (sẽ gỡ), chưa gỡ.\n(A) Anh ấy đã gỡ một tấm biển rồi.\n(B) Anh ấy sẽ làm một việc mà cô McGinnis yêu cầu.\n(C) Anh ấy sẽ mang tài liệu chưa dùng về văn phòng.\n(D) Anh ấy nhận ra cô Sen không cần giúp đỡ."},{"n":167,"q":"What does Ms. McGinnis instruct Mr. Herman to do?","qvi":"Cô McGinnis hướng dẫn anh Herman làm gì?","opts":["Help her locate the main tent","Meet her at the south entrance","Write down participants' information","Leave an object behind the welcome table"],"ans":"D","xp":"Câu hỏi chi tiết. \"Can you put it with the others behind the welcome table in the main tent?\" → để tấm biển (an object) phía sau bàn đón tiếp → (D).\n(A) Giúp cô ấy tìm lều chính\n(B) Gặp cô ấy ở lối vào phía nam\n(C) Ghi lại thông tin người tham gia\n(D) Để một đồ vật phía sau bàn đón tiếp"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following fact sheet.","passages":["<h3>Zealandia Airlines Fact Sheet for Fiscal Year Ending 30 June</h3><p><b>Service Levels and Capacity:</b> Zealandia Airlines provides regional service among four cities. In each case, average flight capacity exceeded the company goal of 85 percent.</p><p><b>On-Time Performance (OTP):</b> For the purpose of measuring OTP, flights are considered “on time” when they reach their destination within fifteen minutes of the scheduled arrival time. Regional airlines are subject to fines when OTP drops below 50 percent. The following chart shows Zealandia's commendable OTP rates for the recent fiscal year.</p><table><tr><th>City</th><th>OTP</th></tr><tr><td>Kelton Falls</td><td>52%</td></tr><tr><td>Grangerton</td><td>68%</td></tr><tr><td>Satcherville</td><td>79%</td></tr><tr><td>Barbour City</td><td>64%</td></tr></table><p><b>Proposed Expansion:</b> Zealandia Airlines provides regional passenger air service and is seeking to expand its fleet to begin providing commercial airfreight delivery. Establishing this service is a component of the airline's growth plan and corporate vision. The airline is currently in negotiations with aviation authorities to explore options.</p><p><b>Terminal and Service Improvements:</b> Zealandia Airlines is participating in discussions with airport management about comprehensive renovations to its passenger lounge and café and has offered to commit $5 million from its budget to the project. Company executives have also finalized a plan and committed funds to overhaul its rewards program. The initiative supports the aim to be a leading service provider among similar airlines and capture an increasing percentage of the market share.</p>"],"vi":"Bảng thông tin của Hãng hàng không Zealandia cho năm tài chính kết thúc ngày 30 tháng 6\n\nMức độ dịch vụ và công suất: Hãng hàng không Zealandia cung cấp dịch vụ bay khu vực giữa bốn thành phố. Ở mọi tuyến, công suất chuyến bay trung bình đều vượt mục tiêu 85% của công ty.\n\nTỷ lệ đúng giờ (OTP): Để đo OTP, chuyến bay được xem là \"đúng giờ\" khi đến nơi trong vòng mười lăm phút so với giờ đến dự kiến. Các hãng hàng không khu vực sẽ bị phạt khi OTP giảm xuống dưới 50%. Bảng sau cho thấy tỷ lệ OTP đáng khen ngợi của Zealandia trong năm tài chính vừa qua.\n\nThành phố – OTP\nKelton Falls – 52%\nGrangerton – 68%\nSatcherville – 79%\nBarbour City – 64%\n\nKế hoạch mở rộng: Hãng hàng không Zealandia cung cấp dịch vụ bay chở khách khu vực và đang tìm cách mở rộng đội bay để bắt đầu cung cấp dịch vụ vận chuyển hàng hóa thương mại bằng đường hàng không. Việc thiết lập dịch vụ này là một phần trong kế hoạch tăng trưởng và tầm nhìn doanh nghiệp của hãng. Hãng hiện đang đàm phán với các cơ quan quản lý hàng không để tìm hiểu các phương án.\n\nCải thiện nhà ga và dịch vụ: Hãng hàng không Zealandia đang tham gia thảo luận với ban quản lý sân bay về việc cải tạo toàn diện phòng chờ hành khách và quán cà phê của hãng, và đã đề nghị cam kết chi 5 triệu đô la từ ngân sách cho dự án. Ban điều hành công ty cũng đã hoàn tất kế hoạch và cam kết ngân sách để cải tổ chương trình khách hàng thân thiết. Sáng kiến này hỗ trợ mục tiêu trở thành nhà cung cấp dịch vụ hàng đầu trong số các hãng hàng không tương tự và giành được tỷ lệ thị phần ngày càng tăng.","qs":[{"n":168,"q":"The word \"exceeded\" in paragraph 1, line 2, is closest in meaning to","qvi":"Từ \"exceeded\" ở đoạn 1, dòng 2 gần nghĩa nhất với","opts":["surpassed","excelled","perfected","decided"],"ans":"A","xp":"Câu hỏi đồng nghĩa. \"average flight capacity exceeded the company goal of 85 percent\" = công suất vượt quá mục tiêu 85% → exceeded = surpassed (vượt qua) → (A). (B) excelled (xuất sắc, giỏi) thường dùng \"excel at/in\", không đi trực tiếp với \"goal\".\n(A) vượt qua\n(B) xuất sắc, trội hơn\n(C) hoàn thiện\n(D) quyết định"},{"n":169,"q":"According to the fact sheet, what is true about Zealandia Airlines?","qvi":"Theo bảng thông tin, điều gì đúng về Hãng hàng không Zealandia?","opts":["Executives aim to improve its flight capacity.","Most of its flights arrive at their destinations on time.","It is larger than 85 percent of regional airlines.","It has received a fine from aviation authorities."],"ans":"B","xp":"Câu hỏi chi tiết. Bảng OTP cho thấy tỷ lệ đúng giờ ở cả bốn thành phố đều trên 50% (52%, 68%, 79%, 64%) → phần lớn chuyến bay đến đúng giờ → (B). (A) sai: công suất đã vượt mục tiêu; (C) sai: 85% là mục tiêu công suất, không phải quy mô; (D) sai: chỉ bị phạt khi OTP dưới 50%, mà OTP của hãng đều trên 50%.\n(A) Ban điều hành đặt mục tiêu cải thiện công suất chuyến bay.\n(B) Phần lớn chuyến bay của hãng đến nơi đúng giờ.\n(C) Hãng lớn hơn 85% các hãng hàng không khu vực.\n(D) Hãng đã bị cơ quan hàng không phạt."},{"n":170,"q":"What does Zealandia Airlines want to provide in the future?","qvi":"Hãng hàng không Zealandia muốn cung cấp gì trong tương lai?","opts":["Private charter flights","Luxury travel tours","Commercial shipping","Aircraft leasing"],"ans":"C","xp":"Câu hỏi chi tiết. \"seeking to expand its fleet to begin providing commercial airfreight delivery\" → vận chuyển hàng hóa thương mại → (C). \"commercial airfreight delivery\" được diễn đạt lại thành \"commercial shipping\".\n(A) Chuyến bay thuê riêng\n(B) Tour du lịch hạng sang\n(C) Vận chuyển hàng hóa thương mại\n(D) Cho thuê máy bay"},{"n":171,"q":"How does Zealandia Airlines hope to improve service for passengers?","qvi":"Hãng hàng không Zealandia hy vọng cải thiện dịch vụ cho hành khách bằng cách nào?","opts":["By remodeling the passenger waiting area","By moving to a new location within the terminal","By upgrading the seating inside the aircraft","By offering improved meal service on all flights"],"ans":"A","xp":"Câu hỏi chi tiết. \"comprehensive renovations to its passenger lounge and café\" → cải tạo phòng chờ hành khách → (A). \"renovations\" = \"remodeling\", \"passenger lounge\" = \"passenger waiting area\". (D) sai: \"café\" là quán cà phê ở nhà ga, không phải bữa ăn trên máy bay.\n(A) Bằng cách cải tạo khu vực chờ của hành khách\n(B) Bằng cách chuyển đến vị trí mới trong nhà ga\n(C) Bằng cách nâng cấp ghế ngồi trên máy bay\n(D) Bằng cách cung cấp suất ăn tốt hơn trên mọi chuyến bay"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following press release.","passages":["<h3>New Fleet for Northeast Railways</h3><p>Northeast Railways expects to spend $5.6 billion to replace its fleet of 65 passenger trains, many of which are more than 40 years old. <span class=\"pos\">[1]</span></p><p>The company has entered into a contract with Logiens Transport for a new fleet of trains that will operate on electrified tracks when those track systems are available and on diesel fuel at all other times. <span class=\"pos\">[2]</span> The trains will be capable of traveling at speeds of up to 130 kilometers per hour and will produce far less pollution than the current fleet does.</p><p>Logiens also promises an enhanced passenger experience. The train cars will have panoramic windows, improved ventilation, and wider aisles. <span class=\"pos\">[3]</span></p><p>Northeast's contract with Logiens also includes equipment and replacement parts and provides a long-term service agreement. <span class=\"pos\">[4]</span></p>"],"vi":"Đội tàu mới cho Northeast Railways\n\nNortheast Railways dự kiến chi 5,6 tỷ đô la để thay thế đội 65 đoàn tàu chở khách, nhiều đoàn trong số đó đã hơn 40 năm tuổi.\n\nCông ty đã ký hợp đồng với Logiens Transport cho một đội tàu mới sẽ chạy trên đường ray điện khí hóa khi có những hệ thống đường ray đó và chạy bằng nhiên liệu diesel vào mọi lúc khác. Các đoàn tàu sẽ có khả năng chạy với tốc độ lên tới 130 km/giờ và sẽ thải ra ít ô nhiễm hơn nhiều so với đội tàu hiện tại.\n\nLogiens cũng hứa hẹn mang lại trải nghiệm tốt hơn cho hành khách. Các toa tàu sẽ có cửa sổ toàn cảnh, hệ thống thông gió được cải thiện và lối đi rộng hơn.\n\nHợp đồng của Northeast với Logiens cũng bao gồm thiết bị và phụ tùng thay thế, đồng thời cung cấp một thỏa thuận bảo dưỡng dài hạn.","qs":[{"n":172,"q":"What is Logiens Transport's role?","qvi":"Vai trò của Logiens Transport là gì?","opts":["To recommend ways to reduce pollution","To acquire financing for a purchase","To familiarize train engineers with new technology","To manufacture and service the replacement fleet"],"ans":"D","xp":"Câu hỏi chi tiết. \"entered into a contract with Logiens Transport for a new fleet of trains\" (cung cấp đội tàu mới) và \"includes equipment and replacement parts and provides a long-term service agreement\" (bảo dưỡng dài hạn) → Logiens sản xuất và bảo dưỡng đội tàu thay thế → (D).\n(A) Đề xuất cách giảm ô nhiễm\n(B) Huy động vốn cho một giao dịch mua\n(C) Giúp các lái tàu làm quen với công nghệ mới\n(D) Sản xuất và bảo dưỡng đội tàu thay thế"},{"n":173,"q":"What information is included in the press release?","qvi":"Thông tin nào có trong thông cáo báo chí?","opts":["The date on which the trains will be delivered","The budget for replacing the current trains","The annual cost for parts and service","The number of passenger seats in each train car"],"ans":"B","xp":"Câu hỏi chi tiết. \"Northeast Railways expects to spend $5.6 billion to replace its fleet of 65 passenger trains\" → ngân sách thay thế đội tàu hiện tại → (B). (A), (C), (D) không được nêu trong bài.\n(A) Ngày giao các đoàn tàu\n(B) Ngân sách thay thế các đoàn tàu hiện tại\n(C) Chi phí hằng năm cho phụ tùng và bảo dưỡng\n(D) Số ghế hành khách trên mỗi toa tàu"},{"n":174,"q":"What is suggested about the tracks that Northeast Railways uses?","qvi":"Điều gì được ngụ ý về các đường ray mà Northeast Railways sử dụng?","opts":["They are owned by the government.","They are not shared with freight trains.","Most are in urgent need of repair.","Some are not electrified."],"ans":"D","xp":"Câu hỏi suy luận. Tàu mới \"will operate on electrified tracks when those track systems are available and on diesel fuel at all other times\" → không phải chỗ nào cũng có đường ray điện, nên một số đoạn ray chưa được điện khí hóa → (D). (A), (B), (C) không được nhắc đến.\n(A) Chúng thuộc sở hữu của chính phủ.\n(B) Chúng không dùng chung với tàu chở hàng.\n(C) Phần lớn cần sửa chữa gấp.\n(D) Một số đường ray chưa được điện khí hóa."},{"n":175,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Each reclinable seat will have an individual power supply and USB port.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong các vị trí [1], [2], [3], [4]?\n\"Mỗi ghế ngả được sẽ có nguồn điện riêng và cổng USB.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Câu hỏi điền câu. Câu cần điền mô tả thêm tiện nghi trên toa tàu (ghế có nguồn điện, cổng USB) → hợp với đoạn nói về \"an enhanced passenger experience. The train cars will have panoramic windows, improved ventilation, and wider aisles.\" Vị trí [3] ngay sau danh sách tiện nghi này → (C).\n(A) Vị trí [1]\n(B) Vị trí [2]\n(C) Vị trí [3]\n(D) Vị trí [4]"}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mail and form.","passages":["<div class=\"hdr\"><p><b>To:</b> headquartersstaff@seonwulawfirm.com</p><p><b>From:</b> iqalandar@seonwulawfirm.com</p><p><b>Date:</b> October 1, 9:39 A.M.</p><p><b>Subject:</b> Remote work setup</p><p><b>Attachment:</b> Equipment request form</p></div><p>Dear Associates,</p><p>On December 3, our headquarters will close for a month for renovation. As all of you normally work out of these offices in San Francisco, please plan to work off-site and collect everything you may need (your laptop, files, etc.) before December 1. Entry to the building will be restricted after that date.</p><p>If you would like a temporary space at our San Jose offices, please e-mail me, and I will reserve one for you. If you plan to work from home and need additional equipment (such as a printer), fill out the attached form from our technology department and return it to me. A representative of that department will mail the equipment to your home address.</p><p>We realize this work on the building is a disruption, but timing it with our slow season should make the situation easier. We think you will be happy with the changes when the building reopens on January 5. If you have any questions, please reach out to me.</p><p>Best,</p><p>Ian Qalandar, Manager<br>Seonwu Law Firm<br>(415) 555-0177</p>","<h4>Seonwu Law Firm—Equipment Request Form</h4><table><tr><td><b>Employee name:</b></td><td>Jason Kang</td></tr><tr><td><b>Employee ID:</b></td><td>102899</td></tr><tr><td><b>E-mail:</b></td><td>jkang@seonwulawfirm.com</td></tr><tr><td><b>Date to receive:</b></td><td>November 30</td></tr><tr><td><b>Equipment:</b></td><td>desktop monitor, printer</td></tr></table><p>(This section is to be completed by the technology department.)</p><table><tr><td><b>Request completed:</b></td><td>✓ Yes &nbsp;&nbsp; No</td></tr><tr><td><b>Request filled by:</b></td><td>Aubrey Smith</td></tr><tr><td><b>Equipment serial numbers:</b></td><td>VN3902556, MXE96400</td></tr><tr><td><b>Date sent:</b></td><td>November 27 via overnight mail</td></tr></table>"],"vi":"Người nhận: headquartersstaff@seonwulawfirm.com\nNgười gửi: iqalandar@seonwulawfirm.com\nNgày: 1 tháng 10, 9:39 sáng\nTiêu đề: Thiết lập làm việc từ xa\nTệp đính kèm: Mẫu yêu cầu thiết bị\n\nGửi các đồng nghiệp,\n\nVào ngày 3 tháng 12, trụ sở chính của chúng ta sẽ đóng cửa một tháng để cải tạo. Vì tất cả các bạn thường làm việc tại các văn phòng này ở San Francisco, xin hãy lên kế hoạch làm việc bên ngoài và mang theo mọi thứ các bạn có thể cần (máy tính xách tay, hồ sơ, v.v.) trước ngày 1 tháng 12. Việc ra vào tòa nhà sẽ bị hạn chế sau ngày đó.\n\nNếu bạn muốn có một chỗ làm việc tạm thời tại văn phòng San Jose của chúng ta, hãy e-mail cho tôi và tôi sẽ đặt chỗ cho bạn. Nếu bạn định làm việc tại nhà và cần thêm thiết bị (chẳng hạn như máy in), hãy điền vào mẫu đính kèm của phòng công nghệ và gửi lại cho tôi. Một nhân viên của phòng đó sẽ gửi thiết bị qua bưu điện đến địa chỉ nhà bạn.\n\nChúng tôi hiểu rằng việc sửa chữa tòa nhà này gây gián đoạn, nhưng việc sắp xếp nó trùng với mùa thấp điểm của chúng ta sẽ giúp tình hình dễ dàng hơn. Chúng tôi nghĩ các bạn sẽ hài lòng với những thay đổi khi tòa nhà mở cửa trở lại vào ngày 5 tháng 1. Nếu có câu hỏi nào, xin hãy liên hệ với tôi.\n\nThân mến,\n\nIan Qalandar, Quản lý\nCông ty Luật Seonwu\n(415) 555-0177\n\n---\n\nCông ty Luật Seonwu — Mẫu yêu cầu thiết bị\n\nTên nhân viên: Jason Kang\nMã nhân viên: 102899\nE-mail: jkang@seonwulawfirm.com\nNgày nhận: 30 tháng 11\nThiết bị: màn hình máy tính để bàn, máy in\n\n(Phần này do phòng công nghệ điền.)\nYêu cầu đã hoàn tất: ✓ Có   Không\nNgười thực hiện yêu cầu: Aubrey Smith\nSố sê-ri thiết bị: VN3902556, MXE96400\nNgày gửi: 27 tháng 11, bằng chuyển phát qua đêm","qs":[{"n":176,"q":"What is indicated about Seonwu Law Firm?","qvi":"Điều gì được nêu về Công ty Luật Seonwu?","opts":["It focuses on real estate law.","It has a large advertising budget.","It serves clients across the country.","It is headquartered in San Francisco."],"ans":"D","xp":"Câu hỏi chi tiết. E-mail: \"our headquarters will close for a month... As all of you normally work out of these offices in San Francisco\" → trụ sở chính (headquarters) của công ty nằm ở San Francisco → (D). Luật bất động sản, ngân sách quảng cáo, khách hàng khắp cả nước đều không được nhắc tới.\n(A) Công ty tập trung vào luật bất động sản.\n(B) Công ty có ngân sách quảng cáo lớn.\n(C) Công ty phục vụ khách hàng trên khắp cả nước.\n(D) Công ty có trụ sở chính ở San Francisco."},{"n":177,"q":"According to the e-mail, what will the technology department do?","qvi":"Theo e-mail, phòng công nghệ sẽ làm gì?","opts":["Install updates on employee laptops","Send office equipment to employees","Train employees to use new software","Place equipment in renovated offices"],"ans":"B","xp":"Câu hỏi chi tiết. \"fill out the attached form from our technology department... A representative of that department will mail the equipment to your home address.\" → nhân viên phòng công nghệ sẽ gửi thiết bị đến nhà nhân viên. \"mail the equipment\" = \"Send office equipment\" → (B).\n(A) Cài đặt bản cập nhật trên máy tính xách tay của nhân viên\n(B) Gửi thiết bị văn phòng cho nhân viên\n(C) Đào tạo nhân viên sử dụng phần mềm mới\n(D) Đặt thiết bị trong các văn phòng đã cải tạo"},{"n":178,"q":"What is suggested in the e-mail about Seonwu Law Firm?","qvi":"E-mail ngụ ý điều gì về Công ty Luật Seonwu?","opts":["It plans to expand its operations.","It mostly employs remote workers.","It is usually not busy in December.","It handles many high-profile cases."],"ans":"C","xp":"Câu hỏi suy luận. Trụ sở đóng cửa từ \"December 3\" đến \"January 5\", và e-mail viết: \"timing it with our slow season should make the situation easier\" → khoảng thời gian tháng 12 là mùa thấp điểm (slow season) của công ty → tháng 12 thường không bận → (C). (B) sai vì nhân viên \"normally work out of these offices\" (thường làm việc tại văn phòng).\n(A) Công ty dự định mở rộng hoạt động.\n(B) Công ty chủ yếu thuê nhân viên làm việc từ xa.\n(C) Công ty thường không bận vào tháng 12.\n(D) Công ty xử lý nhiều vụ án nổi tiếng."},{"n":179,"q":"What can be concluded about Mr. Kang?","qvi":"Có thể kết luận điều gì về ông Kang?","opts":["He chose not to work in the San Jose office.","He is a senior partner at the Seonwu Law Firm.","He will be on vacation after November.","He has requested a larger office."],"ans":"A","xp":"Câu hỏi suy luận (kết hợp 2 văn bản). E-mail cho 2 lựa chọn: đặt chỗ tạm ở văn phòng San Jose, hoặc \"If you plan to work from home and need additional equipment... fill out the attached form\". Ông Jason Kang đã điền mẫu yêu cầu thiết bị (\"desktop monitor, printer\") → ông chọn làm việc tại nhà, tức là không làm ở văn phòng San Jose → (A).\n(A) Ông ấy đã chọn không làm việc ở văn phòng San Jose.\n(B) Ông ấy là luật sư thành viên cấp cao của Công ty Luật Seonwu.\n(C) Ông ấy sẽ đi nghỉ sau tháng 11.\n(D) Ông ấy đã yêu cầu một văn phòng lớn hơn."},{"n":180,"q":"What most likely is Ms. Smith's occupation?","qvi":"Nghề nghiệp của cô Smith nhiều khả năng là gì?","opts":["Lawyer","Office manager","Technical support staff","Administrative assistant"],"ans":"C","xp":"Câu hỏi suy luận (kết hợp 2 văn bản). Trên mẫu: \"(This section is to be completed by the technology department.)\" và \"Request filled by: Aubrey Smith\" → cô Smith thuộc phòng công nghệ, người gửi thiết bị cho nhân viên → nhân viên hỗ trợ kỹ thuật → (C). Người quản lý (Office manager) là Ian Qalandar.\n(A) Luật sư\n(B) Quản lý văn phòng\n(C) Nhân viên hỗ trợ kỹ thuật\n(D) Trợ lý hành chính"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following article and e-mail.","passages":["<h3>Planning a Tour of Your Facility</h3><p><i>by Didiane Lessard</i></p><p>Plant tours are commonplace in many factories, but not all tours are as effective as they could be. Too many companies make the mistake of adopting a one-size-fits-all approach rather than tailoring tours to maximize their usefulness. A potential investor and a casual tourist will probably not be impressed by the same things, so it is best to be clear about the tour's purpose early on. Here are some guidelines to make each tour as effective as possible.</p><p><b>Be selective.</b> Unless your tour is for a safety inspection, your guests do not need (or want) to see every part of your factory. Choose a few sections that will interest your guests and give them a better sense of your product. For example, journalists will want to create a story about your plant, so show them the parts of the plant that have historical significance, such as a room with the company's original production equipment.</p><p><b>Timing is everything.</b> Always be mindful of the physical demands of the tour. Even the hardiest guest will tire of standing or walking for long periods. It is a good idea to schedule breaks in tours lasting longer than an hour. The time spent in a single section matters also. If you allow guests only five minutes in an area, they will soon forget it. On the other hand, even the most impressive room gets boring after half an hour.</p><p><b>Personality is NOT everything.</b> While having a personable and friendly tour guide is essential, your guests are coming to see what goes into making your product. Tour guides get asked a variety of questions, some unexpected, so a comprehensive knowledge of the production processes is important (and absolutely vital during inspections). You also want someone who will keep the tour moving—visitors will appreciate a tour that begins and ends on time.</p>","<div class=\"hdr\"><p><b>To:</b> Masumi Toda &lt;mt978@vidatechsystems.com&gt;</p><p><b>From:</b> Ana Miftaroski &lt;am680@vidatechsystems.com&gt;</p><p><b>Date:</b> May 1</p><p><b>Subject:</b> Upcoming plant tour</p><p><b>Attachment:</b> Lessard_article</p></div><p>Hi, Masumi,</p><p>I have attached an April 15 article by Didiane Lessard to help you plan the tour we will be giving later this month. I especially agree with the section on timing. Since the tour, by necessity, will have to cover the entire plant, it must be conducted as efficiently as possible. As for a guide, I would have recommended Nathan Zarate, but he will be traveling on May 21. Perhaps Maja Clausen could do it. She has also worked here for several years; she is very knowledgeable about our facility, processes, policies, and procedures. I am confident that she will be able to handle any questions the visitors might ask.</p><p>Ana Miftaroski, Vice President of Operations</p>"],"vi":"Lên kế hoạch cho chuyến tham quan cơ sở của bạn\nTác giả: Didiane Lessard\n\nTham quan nhà máy là việc phổ biến ở nhiều nhà máy, nhưng không phải chuyến tham quan nào cũng hiệu quả như mong muốn. Quá nhiều công ty mắc sai lầm khi áp dụng một cách làm \"một kiểu cho tất cả\" thay vì điều chỉnh chuyến tham quan cho phù hợp để tối đa hóa tính hữu ích. Một nhà đầu tư tiềm năng và một du khách bình thường có lẽ sẽ không ấn tượng bởi cùng những thứ giống nhau, vì vậy tốt nhất là nên xác định rõ mục đích của chuyến tham quan ngay từ đầu. Dưới đây là một số hướng dẫn để mỗi chuyến tham quan đạt hiệu quả cao nhất.\n\nHãy chọn lọc. Trừ khi chuyến tham quan là để kiểm tra an toàn, khách của bạn không cần (hoặc không muốn) xem mọi khu vực của nhà máy. Hãy chọn một vài khu vực khiến khách quan tâm và giúp họ hiểu rõ hơn về sản phẩm của bạn. Ví dụ, các nhà báo sẽ muốn viết một câu chuyện về nhà máy của bạn, vì vậy hãy cho họ xem những khu vực có ý nghĩa lịch sử, chẳng hạn như một căn phòng chứa thiết bị sản xuất ban đầu của công ty.\n\nThời gian là tất cả. Hãy luôn lưu ý đến yêu cầu về thể lực của chuyến tham quan. Ngay cả vị khách khỏe nhất cũng sẽ mệt khi phải đứng hoặc đi bộ trong thời gian dài. Nên sắp xếp giờ nghỉ cho những chuyến tham quan kéo dài hơn một tiếng. Thời gian dành cho từng khu vực cũng quan trọng. Nếu bạn chỉ cho khách năm phút ở một khu vực, họ sẽ sớm quên nó. Mặt khác, ngay cả căn phòng ấn tượng nhất cũng trở nên nhàm chán sau nửa tiếng.\n\nTính cách KHÔNG phải là tất cả. Mặc dù có một hướng dẫn viên dễ mến và thân thiện là điều cần thiết, khách đến là để xem quá trình làm ra sản phẩm của bạn. Hướng dẫn viên được hỏi nhiều loại câu hỏi, có những câu bất ngờ, nên kiến thức toàn diện về quy trình sản xuất là quan trọng (và cực kỳ thiết yếu trong các đợt kiểm tra). Bạn cũng cần một người giữ cho chuyến tham quan diễn ra đúng tiến độ — khách sẽ đánh giá cao một chuyến tham quan bắt đầu và kết thúc đúng giờ.\n\n---\n\nNgười nhận: Masumi Toda <mt978@vidatechsystems.com>\nNgười gửi: Ana Miftaroski <am680@vidatechsystems.com>\nNgày: 1 tháng 5\nTiêu đề: Chuyến tham quan nhà máy sắp tới\nTệp đính kèm: Lessard_article\n\nChào Masumi,\n\nTôi đã đính kèm một bài báo ngày 15 tháng 4 của Didiane Lessard để giúp anh lên kế hoạch cho chuyến tham quan mà chúng ta sẽ tổ chức vào cuối tháng này. Tôi đặc biệt đồng ý với phần nói về thời gian. Vì chuyến tham quan, do yêu cầu bắt buộc, sẽ phải đi qua toàn bộ nhà máy, nên nó phải được tiến hành hiệu quả nhất có thể. Về hướng dẫn viên, lẽ ra tôi sẽ đề xuất Nathan Zarate, nhưng anh ấy sẽ đi công tác vào ngày 21 tháng 5. Có lẽ Maja Clausen có thể đảm nhận. Cô ấy cũng đã làm việc ở đây vài năm; cô ấy rất am hiểu về cơ sở, quy trình, chính sách và thủ tục của chúng ta. Tôi tin rằng cô ấy sẽ xử lý được mọi câu hỏi mà khách có thể đặt ra.\n\nAna Miftaroski, Phó chủ tịch phụ trách vận hành","qs":[{"n":181,"q":"What is one problem mentioned about factory tours in the article?","qvi":"Một vấn đề được đề cập về các chuyến tham quan nhà máy trong bài báo là gì?","opts":["They are often rescheduled at the last minute.","They give the same information to all types of visitors.","They fail to supply protective gear that fits everyone.","They allow groups that are too large."],"ans":"B","xp":"Câu hỏi chi tiết. \"Too many companies make the mistake of adopting a one-size-fits-all approach rather than tailoring tours... A potential investor and a casual tourist will probably not be impressed by the same things\" → vấn đề là dùng một kiểu tham quan cho mọi đối tượng khách → (B). \"one-size-fits-all\" được diễn đạt lại thành \"give the same information to all types of visitors\".\n(A) Chúng thường bị dời lịch vào phút chót.\n(B) Chúng cung cấp cùng một thông tin cho mọi loại khách.\n(C) Chúng không cung cấp đồ bảo hộ vừa với mọi người.\n(D) Chúng cho phép các nhóm quá đông."},{"n":182,"q":"According to the article, what is the maximum amount of time that a tour should stay in one area?","qvi":"Theo bài báo, thời gian tối đa một chuyến tham quan nên dừng ở một khu vực là bao lâu?","opts":["10 minutes","20 minutes","30 minutes","60 minutes"],"ans":"C","xp":"Câu hỏi chi tiết. \"On the other hand, even the most impressive room gets boring after half an hour.\" → không nên ở một khu vực quá nửa tiếng = 30 phút → (C). (\"five minutes\" là quá ít; \"an hour\" là mốc nên có giờ nghỉ cho cả chuyến.)\n(A) 10 phút\n(B) 20 phút\n(C) 30 phút\n(D) 60 phút"},{"n":183,"q":"What is NOT indicated in the article as a characteristic of a good tour guide?","qvi":"Điều gì KHÔNG được bài báo nêu là đặc điểm của một hướng dẫn viên giỏi?","opts":["A friendly personality","The ability to stand for long periods","A deep knowledge of processes","The ability to pay close attention to time"],"ans":"B","xp":"Câu hỏi NOT. (A) có: \"having a personable and friendly tour guide is essential\". (C) có: \"a comprehensive knowledge of the production processes is important\". (D) có: \"someone who will keep the tour moving—visitors will appreciate a tour that begins and ends on time\". (B) không có: việc mệt vì đứng lâu (\"tire of standing or walking for long periods\") nói về khách, không phải yêu cầu đối với hướng dẫn viên → chọn (B).\n(A) Tính cách thân thiện\n(B) Khả năng đứng trong thời gian dài\n(C) Kiến thức sâu về các quy trình\n(D) Khả năng chú ý kỹ đến thời gian"},{"n":184,"q":"For whom is Mr. Toda most likely planning a tour?","qvi":"Ông Toda nhiều khả năng đang lên kế hoạch tham quan cho ai?","opts":["Casual tourists","New employees","Potential investors","Safety inspectors"],"ans":"D","xp":"Câu hỏi suy luận (kết hợp 2 văn bản). E-mail: \"the tour, by necessity, will have to cover the entire plant\" (bắt buộc phải đi qua toàn bộ nhà máy). Bài báo: \"Unless your tour is for a safety inspection, your guests do not need (or want) to see every part of your factory\" → chỉ đoàn kiểm tra an toàn mới cần xem mọi khu vực → khách là thanh tra an toàn → (D).\n(A) Du khách bình thường\n(B) Nhân viên mới\n(C) Nhà đầu tư tiềm năng\n(D) Thanh tra an toàn"},{"n":185,"q":"When is the tour scheduled to take place?","qvi":"Chuyến tham quan được lên lịch diễn ra khi nào?","opts":["On April 15","On April 21","On May 1","On May 21"],"ans":"D","xp":"Câu hỏi suy luận. E-mail (ngày 1/5) nói chuyến tham quan diễn ra \"later this month\" và \"I would have recommended Nathan Zarate, but he will be traveling on May 21\" → Nathan không thể dẫn đoàn vì đi công tác ngày 21/5, nghĩa là chuyến tham quan diễn ra vào ngày 21 tháng 5 → (D). April 15 là ngày đăng bài báo, May 1 là ngày gửi e-mail.\n(A) Vào ngày 15 tháng 4\n(B) Vào ngày 21 tháng 4\n(C) Vào ngày 1 tháng 5\n(D) Vào ngày 21 tháng 5"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following Web page, schedule, and testimonial.","passages":["<p>https://www.zonecatering.com/home</p><p><b>Home</b> | Menus | Testimonials | Contact Us</p><p>Zone Catering provides food trucks at film and television production sites throughout California. Just let us know where you need a food truck and how many people you need to feed. We can serve your entire cast and crew. Our trucks also move with you and your team if you are shooting scenes in various locations.</p><p>At Zone Catering, we offer a wide variety of cuisines. All the fruits and vegetables we use in our menus are grown here in California. Our menus are easily adapted to accommodate dietary restrictions. For convenience, our food trucks offer both full meals and individual items. We can serve meals buffet-style, or people can order directly from the truck.</p><p>Let us take care of the catering for your production. You will find our food delicious, and you will find our service friendly and convenient. We even offer 24-hour support in case any issues arise while we are at your location. We hope to serve you soon!</p>","<h3>Zone Catering Food Trucks</h3><p><b>Schedule Date:</b> June 10</p><table><tr><th>Film</th><th>Shooting Location</th><th>Contact Person</th></tr><tr><td><i>Trappings</i></td><td>Harpin Lot</td><td>Erin Begg</td></tr><tr><td><i>Make the Meeting</i></td><td>192 Laredo Street</td><td>Mark Lillo</td></tr><tr><td><i>Tutors and Tuxedos</i></td><td>Tandor Fields</td><td>Jun-Seo Kil</td></tr><tr><td><i>Jatem and the Storm</i></td><td>Spectrum Hall</td><td>Donna Gawason</td></tr></table>","<p>https://www.zonecatering.com/testimonials</p><p>Home | Menus | <b>Testimonials</b> | Contact Us</p><p>June 10—I have been in the acting business for over 25 years and am sometimes disappointed by the food trucks on film production sites. That was not the case today when we were filming <i>Make the Meeting</i>. The food truck had excellent coffee, and the strawberries in the large fruit salad were so fresh and tasty! Even though there was a long line of customers on an extremely hot and uncomfortable day, the server was able to get everyone's food ready quickly. She was friendly and easygoing, too! Even the food truck was pleasant-looking—the mural painted on the side of the truck was beautiful! I hope to see Zone Catering food trucks at future film shooting locations.</p><p>—Robert Chiodo</p>"],"vi":"https://www.zonecatering.com/home\nTrang chủ | Thực đơn | Cảm nhận khách hàng | Liên hệ\n\nZone Catering cung cấp xe bán đồ ăn tại các địa điểm sản xuất phim điện ảnh và truyền hình trên khắp California. Bạn chỉ cần cho chúng tôi biết bạn cần xe đồ ăn ở đâu và cần phục vụ bao nhiêu người. Chúng tôi có thể phục vụ toàn bộ diễn viên và đoàn làm phim của bạn. Xe của chúng tôi cũng di chuyển cùng bạn và ê-kíp nếu bạn quay các cảnh ở nhiều địa điểm khác nhau.\n\nTại Zone Catering, chúng tôi cung cấp nhiều món ăn đa dạng. Tất cả trái cây và rau củ dùng trong thực đơn của chúng tôi đều được trồng ngay tại California. Thực đơn của chúng tôi dễ dàng điều chỉnh để phù hợp với các chế độ ăn kiêng. Để thuận tiện, xe đồ ăn của chúng tôi cung cấp cả suất ăn đầy đủ lẫn món lẻ. Chúng tôi có thể phục vụ theo kiểu buffet, hoặc mọi người có thể gọi món trực tiếp tại xe.\n\nHãy để chúng tôi lo phần ăn uống cho đoàn phim của bạn. Bạn sẽ thấy đồ ăn của chúng tôi rất ngon, và dịch vụ của chúng tôi thân thiện, tiện lợi. Chúng tôi thậm chí còn hỗ trợ 24 giờ phòng khi có bất kỳ sự cố nào xảy ra khi chúng tôi đang ở địa điểm của bạn. Mong sớm được phục vụ bạn!\n\n---\n\nXe đồ ăn Zone Catering\nNgày theo lịch: 10 tháng 6\n\nPhim | Địa điểm quay | Người liên hệ\nTrappings | Harpin Lot | Erin Begg\nMake the Meeting | 192 phố Laredo | Mark Lillo\nTutors and Tuxedos | Tandor Fields | Jun-Seo Kil\nJatem and the Storm | Spectrum Hall | Donna Gawason\n\n---\n\nhttps://www.zonecatering.com/testimonials\nTrang chủ | Thực đơn | Cảm nhận khách hàng | Liên hệ\n\nNgày 10 tháng 6 — Tôi đã làm nghề diễn viên hơn 25 năm và đôi khi thất vọng với các xe đồ ăn tại phim trường. Hôm nay khi chúng tôi quay phim Make the Meeting thì không như vậy. Xe đồ ăn có cà phê tuyệt hảo, và dâu tây trong đĩa salad trái cây cỡ lớn thì rất tươi và ngon! Mặc dù có một hàng dài khách vào một ngày cực kỳ nóng bức và khó chịu, cô nhân viên phục vụ vẫn chuẩn bị đồ ăn cho mọi người rất nhanh. Cô ấy cũng thân thiện và dễ chịu nữa! Ngay cả chiếc xe cũng trông rất đẹp — bức tranh tường vẽ bên hông xe thật tuyệt! Tôi hy vọng sẽ gặp lại xe đồ ăn Zone Catering tại các địa điểm quay phim sau này.\n\n— Robert Chiodo","qs":[{"n":186,"q":"What does the Web page indicate about Zone Catering?","qvi":"Trang web cho biết điều gì về Zone Catering?","opts":["It specializes in providing food at music concerts.","It has lower prices than its competitors.","It recently moved its corporate office to California.","It provides customer support 24 hours a day."],"ans":"D","xp":"Câu hỏi chi tiết. \"We even offer 24-hour support in case any issues arise\" → hỗ trợ khách hàng 24 giờ mỗi ngày → (D). (A) sai: công ty phục vụ phim trường (\"film and television production sites\"), không phải buổi hòa nhạc. (B), (C) không được nhắc tới.\n(A) Công ty chuyên cung cấp đồ ăn tại các buổi hòa nhạc.\n(B) Công ty có giá thấp hơn đối thủ.\n(C) Công ty vừa chuyển văn phòng chính đến California.\n(D) Công ty hỗ trợ khách hàng 24 giờ một ngày."},{"n":187,"q":"According to the schedule, who was the contact person for the filming of Trappings on June 10?","qvi":"Theo lịch, ai là người liên hệ cho buổi quay phim Trappings ngày 10 tháng 6?","opts":["Erin Begg","Mark Lillo","Jun-Seo Kil","Donna Gawason"],"ans":"A","xp":"Câu hỏi chi tiết. Trong bảng lịch: \"Trappings | Harpin Lot | Erin Begg\" → người liên hệ là Erin Begg → (A).\n(A) Erin Begg\n(B) Mark Lillo\n(C) Jun-Seo Kil\n(D) Donna Gawason"},{"n":188,"q":"Where was the food truck that Mr. Chiodo visited?","qvi":"Chiếc xe đồ ăn mà ông Chiodo ghé đến ở đâu?","opts":["At Harpin Lot","At 192 Laredo Street","At Tandor Fields","At Spectrum Hall"],"ans":"B","xp":"Câu hỏi kết hợp 2 văn bản. Lời cảm nhận (June 10): \"today when we were filming Make the Meeting\". Lịch ngày 10/6: \"Make the Meeting | 192 Laredo Street\" → xe đồ ăn ở số 192 phố Laredo → (B).\n(A) Ở Harpin Lot\n(B) Ở số 192 phố Laredo\n(C) Ở Tandor Fields\n(D) Ở Spectrum Hall"},{"n":189,"q":"What is probably true about the salad Mr. Chiodo ordered?","qvi":"Điều gì có lẽ đúng về món salad ông Chiodo đã gọi?","opts":["It had an unusual taste.","It was too big for him to finish.","It included several types of berries.","It contained fruit grown in California."],"ans":"D","xp":"Câu hỏi suy luận (kết hợp 2 văn bản). Lời cảm nhận: \"the strawberries in the large fruit salad were so fresh and tasty\". Trang web: \"All the fruits and vegetables we use in our menus are grown here in California.\" → dâu tây trong salad là trái cây trồng ở California → (D). (C) sai vì chỉ nhắc đến dâu tây; (B) \"large\" chỉ là cỡ lớn, không nói ăn không hết.\n(A) Nó có vị lạ.\n(B) Nó quá nhiều nên ông ăn không hết.\n(C) Nó có nhiều loại quả mọng.\n(D) Nó có trái cây trồng ở California."},{"n":190,"q":"What is indicated about the food truck server in the testimonial?","qvi":"Lời cảm nhận cho biết điều gì về cô nhân viên phục vụ trên xe đồ ăn?","opts":["She had difficulty working in the heat.","She paints murals in her spare time.","She prepares orders quickly.","She has worked in her industry for 25 years."],"ans":"C","xp":"Câu hỏi chi tiết. \"Even though there was a long line... the server was able to get everyone's food ready quickly.\" → cô ấy chuẩn bị đồ ăn nhanh → (C). (A) sai: trời nóng nhưng cô vẫn làm tốt. (B): bức tranh tường trên xe không nói do cô vẽ. (D): 25 năm là kinh nghiệm diễn xuất của ông Chiodo.\n(A) Cô ấy gặp khó khăn khi làm việc trong trời nóng.\n(B) Cô ấy vẽ tranh tường lúc rảnh rỗi.\n(C) Cô ấy chuẩn bị các đơn hàng nhanh chóng.\n(D) Cô ấy đã làm trong ngành được 25 năm."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following e-mails and list.","passages":["<div class=\"hdr\"><p><b>To:</b> Hae-won Jeong</p><p><b>From:</b> Julia Laurent</p><p><b>Date:</b> July 28</p><p><b>Subject:</b> Dallas hotels</p><p><b>Attachment:</b> List of downtown accommodations</p></div><p>Dear Hae-won,</p><p>I plan to attend the National Digital Marketing Conference in October. I know you have traveled to this conference in Dallas many times. This will be my first time attending, and I'm not sure which hotel to book. I have attached a list of accommodations that are near the convention center. Right now, I am leaning toward the Bonita Suites Hotel, but I would like to know which property you would recommend.</p><p>I hope you have settled into your new position with the digital marketing department. I am looking forward to the conference and hope to see you again there.</p><p>Kind regards,</p><p>Julia Laurent<br>E-mail Marketing Specialist<br>The 3R Marketing Firm</p>","<p>List of Downtown Accommodations (from www.topbusinesshotels.com/search/Dallashotels)</p><table><tr><th>Hotel</th><th>Rate</th><th>Description</th></tr><tr><td>The Oaktree Hotel</td><td>$204/night</td><td>Luxury hotel in the heart of downtown<br>Close to the convention center<br>Outdoor pool, three on-site restaurants<br>Close to shopping</td></tr><tr><td>Alessi Dallas Hotel</td><td>$155/night</td><td>Quaint boutique hotel in downtown Dallas<br>Lobby restaurant for breakfast and dinner<br>Near convention center and history museum</td></tr><tr><td>Bonita Suites Hotel</td><td>$125/night</td><td>New hotel in downtown convention center area<br>Office and kitchen in each suite<br>Computer center with printers located in lobby<br>Meeting space available for groups<br>Free on-site parking available</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Julia Laurent</p><p><b>From:</b> Hae-won Jeong</p><p><b>Date:</b> July 29</p><p><b>Subject:</b> RE: Dallas hotels</p></div><p>Dear Julia,</p><p>I will be attending the National Digital Marketing Conference this year as well! I love traveling to Dallas every year for this conference because it is a great networking opportunity. Since this is your first time attending, I recommend you go to the newcomers' reception on the first night. The conference executive planning committee is putting it on, and it could be an excellent occasion to socialize with other conference goers.</p><p>I will be staying at the Alessi Dallas Hotel. It is the closest to the convention center, and the rooms are comfortable. For you, I would suggest the one you already seem to prefer. It so happens that the newcomers' reception will be held in one of the event rooms there. It is a little farther away but still convenient. As a friendly reminder, we are advised not to book hotels with rates that exceed our company's limit of $175/night.</p><p>I look forward to seeing you in October. It will be lovely to catch up.</p><p>Best,</p><p>Hae-won Jeong<br>Digital Marketing Director<br>The 3R Marketing Firm</p>"],"vi":"Người nhận: Hae-won Jeong\nNgười gửi: Julia Laurent\nNgày: 28 tháng 7\nTiêu đề: Khách sạn ở Dallas\nTệp đính kèm: Danh sách chỗ ở khu trung tâm\n\nHae-won thân mến,\n\nTôi dự định tham dự Hội nghị Tiếp thị Kỹ thuật số Quốc gia vào tháng 10. Tôi biết chị đã đến hội nghị này ở Dallas nhiều lần. Đây sẽ là lần đầu tôi tham dự, và tôi không chắc nên đặt khách sạn nào. Tôi đã đính kèm danh sách các chỗ ở gần trung tâm hội nghị. Hiện tại tôi đang nghiêng về khách sạn Bonita Suites, nhưng tôi muốn biết chị sẽ gợi ý chỗ nào.\n\nTôi hy vọng chị đã ổn định ở vị trí mới tại phòng tiếp thị kỹ thuật số. Tôi rất mong chờ hội nghị và hy vọng sẽ gặp lại chị ở đó.\n\nTrân trọng,\n\nJulia Laurent\nChuyên viên Tiếp thị qua E-mail\nCông ty Tiếp thị 3R\n\n---\n\nDanh sách chỗ ở khu trung tâm (từ www.topbusinesshotels.com/search/Dallashotels)\n\nKhách sạn | Giá | Mô tả\nThe Oaktree Hotel | 204 đô/đêm | Khách sạn sang trọng ngay trung tâm thành phố; Gần trung tâm hội nghị; Hồ bơi ngoài trời, ba nhà hàng trong khuôn viên; Gần khu mua sắm\nAlessi Dallas Hotel | 155 đô/đêm | Khách sạn boutique xinh xắn ở trung tâm Dallas; Nhà hàng ở sảnh phục vụ bữa sáng và bữa tối; Gần trung tâm hội nghị và bảo tàng lịch sử\nBonita Suites Hotel | 125 đô/đêm | Khách sạn mới ở khu trung tâm hội nghị; Có văn phòng và bếp trong mỗi phòng suite; Trung tâm máy tính có máy in ở sảnh; Có không gian họp cho các nhóm; Có bãi đỗ xe miễn phí trong khuôn viên\n\n---\n\nNgười nhận: Julia Laurent\nNgười gửi: Hae-won Jeong\nNgày: 29 tháng 7\nTiêu đề: Trả lời: Khách sạn ở Dallas\n\nJulia thân mến,\n\nNăm nay tôi cũng sẽ tham dự Hội nghị Tiếp thị Kỹ thuật số Quốc gia! Tôi thích đến Dallas mỗi năm để dự hội nghị này vì đây là cơ hội tuyệt vời để mở rộng quan hệ. Vì đây là lần đầu bạn tham dự, tôi khuyên bạn nên đến buổi tiệc chào mừng người mới vào tối đầu tiên. Ủy ban điều hành tổ chức hội nghị đứng ra tổ chức buổi tiệc này, và đó có thể là dịp tuyệt vời để giao lưu với những người tham dự khác.\n\nTôi sẽ ở khách sạn Alessi Dallas. Đó là khách sạn gần trung tâm hội nghị nhất, và phòng ở thoải mái. Với bạn, tôi gợi ý khách sạn mà bạn có vẻ đã thích sẵn. Thật tình cờ là buổi tiệc chào mừng người mới sẽ được tổ chức tại một trong các phòng sự kiện ở đó. Nó xa hơn một chút nhưng vẫn thuận tiện. Xin nhắc nhẹ, chúng ta được khuyên không đặt khách sạn có giá vượt quá mức giới hạn 175 đô/đêm của công ty.\n\nMong gặp bạn vào tháng 10. Được gặp lại trò chuyện sẽ thật tuyệt.\n\nThân mến,\n\nHae-won Jeong\nGiám đốc Tiếp thị Kỹ thuật số\nCông ty Tiếp thị 3R","qs":[{"n":191,"q":"What is the purpose of the first e-mail?","qvi":"Mục đích của e-mail thứ nhất là gì?","opts":["To schedule a meeting with a client","To ask for assistance with a project","To seek a suggestion from a colleague","To congratulate a colleague who was promoted"],"ans":"C","xp":"Câu hỏi mục đích. \"I'm not sure which hotel to book... I would like to know which property you would recommend.\" → cô Laurent hỏi ý kiến đồng nghiệp (cùng công ty 3R) nên chọn khách sạn nào → xin gợi ý từ đồng nghiệp → (C). (D) sai: câu \"I hope you have settled into your new position\" chỉ là lời hỏi thăm, không phải mục đích chính.\n(A) Để lên lịch họp với khách hàng\n(B) Để nhờ giúp đỡ một dự án\n(C) Để xin gợi ý từ một đồng nghiệp\n(D) Để chúc mừng một đồng nghiệp được thăng chức"},{"n":192,"q":"According to the list, what is suggested about the Bonita Suites Hotel?","qvi":"Theo danh sách, điều gì được ngụ ý về khách sạn Bonita Suites?","opts":["It is located in a historic building.","It features resources for business travelers.","It is near many downtown tourist attractions.","It charges a daily fee for parking."],"ans":"B","xp":"Câu hỏi suy luận. Mô tả Bonita Suites: \"Office and kitchen in each suite\", \"Computer center with printers located in lobby\", \"Meeting space available for groups\" → có văn phòng, máy tính, máy in, phòng họp = tiện ích cho khách đi công tác → (B). (A) sai: đây là \"New hotel\". (D) sai: \"Free on-site parking\". (C) không được nhắc tới (bảo tàng lịch sử gần Alessi).\n(A) Khách sạn nằm trong một tòa nhà lịch sử.\n(B) Khách sạn có các tiện ích dành cho khách đi công tác.\n(C) Khách sạn gần nhiều điểm du lịch ở trung tâm.\n(D) Khách sạn thu phí đỗ xe theo ngày."},{"n":193,"q":"What is true about Ms. Jeong?","qvi":"Điều gì đúng về cô Jeong?","opts":["She has not attended a marketing conference before.","She prefers the Alessi Dallas Hotel for its restaurant.","She thinks Ms. Laurent should stay at the Bonita Suites Hotel.","She works for a different company than Ms. Laurent."],"ans":"C","xp":"Câu hỏi kết hợp. E-mail 2: \"For you, I would suggest the one you already seem to prefer.\" E-mail 1: \"I am leaning toward the Bonita Suites Hotel\" → cô Jeong gợi ý cô Laurent ở khách sạn Bonita Suites → (C). (A) sai: cô đi hội nghị này mỗi năm. (B) sai: cô chọn Alessi vì gần nhất và phòng thoải mái, không nhắc nhà hàng. (D) sai: cả hai đều làm ở The 3R Marketing Firm.\n(A) Cô ấy chưa từng tham dự hội nghị tiếp thị nào.\n(B) Cô ấy thích khách sạn Alessi Dallas vì nhà hàng của nó.\n(C) Cô ấy nghĩ cô Laurent nên ở khách sạn Bonita Suites.\n(D) Cô ấy làm việc cho một công ty khác với cô Laurent."},{"n":194,"q":"Why would Ms. Jeong most likely suggest that Ms. Laurent avoid the Oaktree Hotel?","qvi":"Vì sao cô Jeong nhiều khả năng khuyên cô Laurent tránh khách sạn Oaktree?","opts":["It does not have an on-site restaurant.","Its room rate exceeds the company's limit.","Its clients are mostly noisy tourists.","It is too far from the conference location."],"ans":"B","xp":"Câu hỏi suy luận (kết hợp). E-mail 2: \"we are advised not to book hotels with rates that exceed our company's limit of $175/night\". Danh sách: The Oaktree Hotel \"$204/night\" → giá phòng vượt mức giới hạn của công ty → (B). (A) sai: Oaktree có \"three on-site restaurants\". (D) sai: \"Close to the convention center\".\n(A) Khách sạn không có nhà hàng trong khuôn viên.\n(B) Giá phòng của khách sạn vượt quá mức giới hạn của công ty.\n(C) Khách của khách sạn chủ yếu là du khách ồn ào.\n(D) Khách sạn quá xa địa điểm hội nghị."},{"n":195,"q":"What does the second e-mail indicate about the National Digital Marketing Conference?","qvi":"E-mail thứ hai cho biết điều gì về Hội nghị Tiếp thị Kỹ thuật số Quốc gia?","opts":["Its location changes to a different city each year.","Last year it was held at the Alessi Dallas Hotel.","Ms. Jeong is on its executive planning committee.","It includes an event for first-time attendees."],"ans":"D","xp":"Câu hỏi chi tiết. \"Since this is your first time attending, I recommend you go to the newcomers' reception on the first night.\" → hội nghị có buổi tiệc chào mừng người mới = sự kiện cho người tham dự lần đầu → (D). (A) sai: cô Jeong đến \"Dallas every year\". (C) sai: ủy ban tổ chức tiệc, nhưng không nói cô Jeong là thành viên. (B) không được nhắc tới.\n(A) Địa điểm hội nghị đổi sang thành phố khác mỗi năm.\n(B) Năm ngoái hội nghị được tổ chức tại khách sạn Alessi Dallas.\n(C) Cô Jeong là thành viên ủy ban điều hành tổ chức hội nghị.\n(D) Hội nghị có một sự kiện dành cho người tham dự lần đầu."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following letter and e-mails.","passages":["<p>Dover Water Supply<br>7400 Rodney Boulevard, Dover, DE 19904</p><p>March 12</p><p>Ms. Na-Ri Cam<br>361 Farming Avenue<br>Dover, DE 19902</p><p>Dear Ms. Cam,</p><p>This letter is to confirm that Dover Water Supply will begin service at your address on Wednesday, April 6. Your customer account number, which is the same as your water meter number, is DWS4289.</p><p>Billing is monthly, and payment is due on the fifteenth of each month. Bills can be paid by mailing a check to our main address or by entering your account number and payment information on our secure page at www.doverwatersupply.com/billing.</p><p>We will be performing a system flush of the pipes in your area on Monday, April 4. Customers may temporarily see discoloration or sediment in their water around that time. Please visit our Web site for more information. You can also contact Customer Support at questions@doverwatersupply.com or call us at (302) 555-0135.</p><p>Sincerely,</p><p><i>Matthew Ensign</i><br>Matthew Ensign<br>Account Representative, Dover Water Supply</p>","<div class=\"hdr\"><p><b>To:</b> questions@doverwatersupply.com</p><p><b>From:</b> Na-Ri Cam &lt;n.cam@mailcurrent.com&gt;</p><p><b>Date:</b> March 17</p><p><b>Subject:</b> Account number DWS4289</p></div><p>Hello,</p><p>I am in the process of moving to my new home in Dover. I received a letter stating that my water service will start on April 6. It also said something about pipes being flushed on April 4. Should I expect to see discoloration when I start using my water? Are there any steps I should take?</p><p>Also, I tried to use your secure page, but it gave me an error message saying that my account number was not valid. I will need your help in getting online access by the May 15 due date.</p><p>Thank you for any information you can provide.</p><p>Na-Ri Cam</p>","<div class=\"hdr\"><p><b>To:</b> Na-Ri Cam &lt;n.cam@mailcurrent.com&gt;</p><p><b>From:</b> Customer Support &lt;questions@doverwatersupply.com&gt;</p><p><b>Date:</b> March 18</p><p><b>Subject:</b> RE: Account number DWS4289</p></div><p>Dear Ms. Cam,</p><p>Thank you for your message. Your water might look cloudy on April 6 when you first turn on your faucets. We recommend that you keep the water running until it is clear before you use it. I assure you that the water is not harmful in any way. The minerals that cause the discoloration occur naturally, and our latest water analysis showed very high quality.</p><p>I apologize for the problem you described. I have fixed it, so you should not have any further trouble.</p><p>If you have any other questions, please don't hesitate to reach out to us again.</p><p>Best regards,</p><p>Ramona Hizon<br>Customer Support, Dover Water Supply</p>"],"vi":"Công ty Cấp nước Dover\n7400 đại lộ Rodney, Dover, DE 19904\n\nNgày 12 tháng 3\n\nBà Na-Ri Cam\n361 đại lộ Farming\nDover, DE 19902\n\nKính gửi bà Cam,\n\nThư này xác nhận rằng Công ty Cấp nước Dover sẽ bắt đầu cung cấp dịch vụ tại địa chỉ của bà vào thứ Tư, ngày 6 tháng 4. Số tài khoản khách hàng của bà, cũng chính là số đồng hồ nước của bà, là DWS4289.\n\nHóa đơn được tính hằng tháng, và hạn thanh toán là ngày 15 mỗi tháng. Hóa đơn có thể được thanh toán bằng cách gửi séc qua bưu điện đến địa chỉ chính của chúng tôi hoặc nhập số tài khoản và thông tin thanh toán trên trang bảo mật của chúng tôi tại www.doverwatersupply.com/billing.\n\nChúng tôi sẽ tiến hành súc rửa hệ thống đường ống trong khu vực của bà vào thứ Hai, ngày 4 tháng 4. Khách hàng có thể tạm thời thấy nước đổi màu hoặc có cặn vào khoảng thời gian đó. Vui lòng truy cập trang web của chúng tôi để biết thêm thông tin. Bà cũng có thể liên hệ Bộ phận Hỗ trợ Khách hàng qua questions@doverwatersupply.com hoặc gọi cho chúng tôi theo số (302) 555-0135.\n\nTrân trọng,\n\nMatthew Ensign\nNhân viên phụ trách tài khoản, Công ty Cấp nước Dover\n\n---\n\nNgười nhận: questions@doverwatersupply.com\nNgười gửi: Na-Ri Cam <n.cam@mailcurrent.com>\nNgày: 17 tháng 3\nTiêu đề: Số tài khoản DWS4289\n\nXin chào,\n\nTôi đang trong quá trình chuyển đến nhà mới ở Dover. Tôi đã nhận được thư cho biết dịch vụ cấp nước của tôi sẽ bắt đầu vào ngày 6 tháng 4. Thư cũng nói gì đó về việc súc rửa đường ống vào ngày 4 tháng 4. Tôi có nên chờ đợi việc nước bị đổi màu khi tôi bắt đầu sử dụng không? Tôi có cần làm gì không?\n\nNgoài ra, tôi đã thử dùng trang bảo mật của quý công ty, nhưng nó hiện thông báo lỗi cho biết số tài khoản của tôi không hợp lệ. Tôi cần quý công ty giúp để có thể truy cập trực tuyến trước hạn chót ngày 15 tháng 5.\n\nCảm ơn mọi thông tin quý công ty có thể cung cấp.\n\nNa-Ri Cam\n\n---\n\nNgười nhận: Na-Ri Cam <n.cam@mailcurrent.com>\nNgười gửi: Bộ phận Hỗ trợ Khách hàng <questions@doverwatersupply.com>\nNgày: 18 tháng 3\nTiêu đề: Trả lời: Số tài khoản DWS4289\n\nKính gửi bà Cam,\n\nCảm ơn bà đã gửi tin nhắn. Nước của bà có thể trông hơi đục vào ngày 6 tháng 4 khi bà mở vòi lần đầu. Chúng tôi khuyên bà nên để nước chảy cho đến khi trong rồi mới sử dụng. Tôi xin cam đoan rằng nước hoàn toàn không có hại. Các khoáng chất gây đổi màu là tự nhiên, và kết quả phân tích nước gần đây nhất của chúng tôi cho thấy chất lượng rất cao.\n\nTôi xin lỗi về sự cố bà đã mô tả. Tôi đã khắc phục nó, nên bà sẽ không gặp thêm trục trặc nào nữa.\n\nNếu bà có câu hỏi nào khác, xin đừng ngần ngại liên hệ lại với chúng tôi.\n\nTrân trọng,\n\nRamona Hizon\nBộ phận Hỗ trợ Khách hàng, Công ty Cấp nước Dover","qs":[{"n":196,"q":"What is one purpose of the letter?","qvi":"Một mục đích của bức thư là gì?","opts":["To list customer benefits","To alert customers to a price change","To confirm the start of a service","To describe changes to a Web site"],"ans":"C","xp":"Câu hỏi mục đích. \"This letter is to confirm that Dover Water Supply will begin service at your address on Wednesday, April 6.\" → xác nhận việc bắt đầu dịch vụ cấp nước → (C). \"begin service\" = \"the start of a service\". Thư không nói về quyền lợi khách hàng, thay đổi giá hay thay đổi trang web.\n(A) Để liệt kê các quyền lợi của khách hàng\n(B) Để thông báo cho khách hàng về việc thay đổi giá\n(C) Để xác nhận việc bắt đầu một dịch vụ\n(D) Để mô tả những thay đổi trên trang web"},{"n":197,"q":"What most likely does Ms. Cam want to do online on May 15?","qvi":"Cô Cam nhiều khả năng muốn làm gì trực tuyến vào ngày 15 tháng 5?","opts":["Request a new water meter","Complete a customer survey","Report a leaking pipe","Pay a water bill"],"ans":"D","xp":"Câu hỏi suy luận (kết hợp). E-mail 1: \"I will need your help in getting online access by the May 15 due date.\" Thư: \"payment is due on the fifteenth of each month. Bills can be paid... by entering your account number and payment information on our secure page\" → ngày 15/5 là hạn thanh toán, cô muốn thanh toán hóa đơn nước qua trang web → (D).\n(A) Yêu cầu đồng hồ nước mới\n(B) Hoàn thành khảo sát khách hàng\n(C) Báo cáo đường ống bị rò rỉ\n(D) Thanh toán hóa đơn tiền nước"},{"n":198,"q":"According to the second e-mail, what should Ms. Cam do on April 6?","qvi":"Theo e-mail thứ hai, cô Cam nên làm gì vào ngày 6 tháng 4?","opts":["Boil her drinking water for five minutes","Allow her water to run for some time","Contact her neighbors","Request a service visit"],"ans":"B","xp":"Câu hỏi chi tiết. \"Your water might look cloudy on April 6... We recommend that you keep the water running until it is clear before you use it.\" → để nước chảy một lúc cho đến khi trong → (B). \"keep the water running\" = \"Allow her water to run\". Việc đun sôi nước không được nhắc tới.\n(A) Đun sôi nước uống trong năm phút\n(B) Để nước chảy một lúc\n(C) Liên hệ với hàng xóm\n(D) Yêu cầu nhân viên đến kiểm tra"},{"n":199,"q":"In the second e-mail, what is indicated about the water from Dover Water Supply?","qvi":"Trong e-mail thứ hai, điều gì được nêu về nước của Công ty Cấp nước Dover?","opts":["It is safe to use.","It is measured every month.","It is distributed to many cities.","It is naturally free of minerals."],"ans":"A","xp":"Câu hỏi chi tiết. \"I assure you that the water is not harmful in any way... our latest water analysis showed very high quality.\" → nước an toàn để sử dụng → (A). \"not harmful\" = \"safe\". (D) sai: nước có khoáng chất tự nhiên (\"The minerals... occur naturally\"). (B), (C) không được nhắc tới.\n(A) Nước an toàn để sử dụng.\n(B) Nước được đo kiểm hằng tháng.\n(C) Nước được phân phối đến nhiều thành phố.\n(D) Nước tự nhiên không có khoáng chất."},{"n":200,"q":"What can be concluded about Ms. Hizon?","qvi":"Có thể kết luận điều gì về cô Hizon?","opts":["She resolved the issue with Ms. Cam's account.","She sent a copy of the water analysis to Ms. Cam.","She will offer Ms. Cam a discount for new customers.","She lives in Ms. Cam's area."],"ans":"A","xp":"Câu hỏi suy luận (kết hợp). E-mail của cô Cam: trang bảo mật báo \"my account number was not valid\". E-mail trả lời của Ramona Hizon: \"I apologize for the problem you described. I have fixed it\" → cô Hizon đã giải quyết sự cố với tài khoản của cô Cam → (A). Không có thông tin về gửi bản phân tích nước, giảm giá hay nơi cô Hizon sống.\n(A) Cô ấy đã giải quyết sự cố với tài khoản của cô Cam.\n(B) Cô ấy đã gửi bản sao kết quả phân tích nước cho cô Cam.\n(C) Cô ấy sẽ giảm giá cho cô Cam vì là khách hàng mới.\n(D) Cô ấy sống trong khu vực của cô Cam."}]}]}};
